import{a as l}from"./manifestTechniqueLesson-CM64EG9q.js";function t(a){const e=`manifest-${a.number}`;return{schemaVersion:2,revision:1,id:e,courseId:"manifest",locale:"tr",title:a.title,goal:a.goal,minutes:{learning:5,suggestedAction:5,review:2},direction:{hook:a.hook,reason:{id:`${e}-reason`,label:a.reason,kind:"text",maxLength:160,optional:!0,suggestions:["Hedefim için daha az tekrar","Yeni hazırlık yerine işe başlamak","Yeniden denemeden önce destek almak"]},why:{id:`${e}-purpose`,label:"Bu adım bu hafta senin için neden değerli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:a.paragraphs,example:a.example},move:{invitation:"Hedefin aynı kalsın. Bugün ona yarayan tek bir iş seç.",instructions:a.instructions,prompts:[],suggestions:{action:a.action,minimum:a.minimum,cue:a.cue,place:a.place,fallback:a.fallback,observation:a.observation,minutes:[5,2,10],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:a.action[0],minimum:a.minimum[0],minutes:5,cueHint:a.cue[0],placeHint:a.place[0],obstacleHint:a.obstacle,fallbackHint:a.fallback[0],observationHint:a.observation[0]},accessibleAlternative:"İstersen yaz, sesle yazdır ya da uygulamayı sözle anlat; malzeme bulman veya zihninde canlı görüntüler oluşturman gerekmiyor.",stopRule:a.stopRule},result:{question:"Bugün seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Uygulamanın kendisinden ayrı olarak, hedefin için hangi somut işi yaptın?"},judgment:{primary:{id:`${e}-decision`,scenario:a.scenario,question:a.question,options:a.options.map(i=>({id:`${e}-${i.key}`,text:i.text,feedback:i.feedback})),bestOptionId:`${e}-${a.best}`}},carry:{takeaway:a.takeaway,followUp:{questionId:`${e}-return`,question:a.review,observationPrompt:"Planladığın fırsatta ne oldu? Bir yanıt geldiyse onu ayrı anlat.",adjustmentPrompt:"Bir sonraki fırsata uyması için planında hangi tek şeyi değiştireceksin?"}},goDeeper:{sections:a.deeper,sourceIds:a.sources}}}const r=[{id:"manifest-T01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makalede yer alan 24 bağımsız etki ve 15.907 katılımcı incelendi. Zihinsel karşılaştırmayı ‘şu olursa bunu yaparım’ planlarıyla birleştirmek, hedefe ulaşmayı ortalama olarak destekledi: g = 0,336 [0,229; 0,443]. Yanlılık düzeltmesi sonrası tahmin 0,242 [0,143; 0,342] oldu.",limitation:"Etkiler değişkenlik gösterdi ve yayın yanlılığına işaret eden bulgular vardı. Başarı garantisi sunmaz, sıkıntı yaşamanın gerekli olduğunu kanıtlamaz. Bu kütüphane veya ritüellerin ODA uyarlamaları sınanmadı."},{id:"manifest-T02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Bu alandaki temel meta-analizlerden biri, 94 bağımsız test ve 8.461 katılımcıyı kapsadı. Belirli bir durumu yapılacak işe bağlayan ‘şu olursa bunu yaparım’ planları, hedefe ulaşmada ortalama fayda gösterdi: d = 0,65 [0,60; 0,70].",limitation:"Eski ve farklı yöntemleri bir araya getiren araştırmalar. Araştırma planlarının tamamı önceden kayda geçirilmiş değildi. Bir plan dış engelleri ortadan kaldıramaz, çaba gereğini silemez veya başkasının kararını garanti edemez."},{id:"manifest-T03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Rastgele atamalı 138 deneyde toplam 19.951 katılımcı vardı. İlerlemeyi takip etmeye teşvik etmek, hedefe ulaşmayı ortalama olarak artırdı: d = 0,40 [0,32; 0,48]. Çalışmalar karşılaştırıldığında, ilerlemeyi yazılı kaydetmek daha büyük etkilerle ilişkiliydi.",limitation:"Uygulamalar ve hedefler farklıydı. Çalışmalar arasındaki bu ilişkiler, her kayıt özelliğinin işe yaradığını kanıtlamaz. Ertesi gün gözden geçirmek bir ODA uyarlamasıdır; en uygun sıklık olduğu gösterilmiş değildir."},{id:"manifest-T04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 çalışma, 123 etki ve 5.685 katılımcı incelendi. Zihinde canlandırma, daha sonraki davranışı ortalama olarak destekledi: g = 0,49 [0,37; 0,62]. Tüm canlandırma türlerini birlikte karşılaştıran analiz, türler arasında fark olduğunu ortaya koymadı.",limitation:"Örneklemlerin çoğu öğrenciydi; işler ve canlandırmalar farklıydı. Bazı alt gruplarda az sayıda etki vardı. Türler arasında güvenilir bir sıralama, dış olayları çekme veya yatmadan önce yapmanın özel bir üstünlüğü gösterilmedi."},{id:"manifest-T05",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Dört deneyde, kusursuz bir olumlu gelecek hayal etmenin bazı durumlarda o andaki enerjiyi azalttığı bulundu. Daha sonraki bazı başarı ölçümlerinde de farklar vardı. Bu bulgu, keyifli hayaller kurmakla çaba göstermeye hazırlanmayı ayırır.",limitation:"Kısa deneyler; katılımcılar çoğunlukla öğrenciydi. Her iyimserlik veya hayal kurma zararlı değildir. Beynin hedefi zaten tamamlanmış saydığı yönündeki açıklama, bu araştırmada ölçülmedi."},{id:"manifest-T06",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/abs/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"İki deneyde, kişinin kendisi hakkında çok olumlu bir cümleyi tekrarlamasının, özsaygısı düşük katılımcıların ruh hâlini kötüleştirebildiği bulundu. Özsaygısı yüksek katılımcılardaki fayda sınırlıydı.",limitation:"Belirli cümleler, örneklemler ve kısa vadeli sonuçlar incelendi. Her destekleyici sözün zarar verdiğini göstermez; tüm olumlama uygulamaları sınanmadı. İnanabileceğin bir eylem cümlesi kullanmak ODA'nın uyarlamasıdır."},{id:"manifest-T07",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://pubmed.ncbi.nlm.nih.gov/25133846/",type:"research",finding:"144 deneysel testte, sağlık bilgisiyle birlikte kişinin önemli bulduğu değerleri, özellikleri veya ilişkileri düşünerek kendini olumlaması incelendi. Bilgiyi kabul etme ve niyetler üzerindeki etkiler küçüktü. Davranışı ölçen 46 test ve 2.715 katılımcıda d = 0,32 [0,19; 0,44] bulundu.",limitation:"Değerlere dayalı kendini olumlamak, istenen sonucu olmuş gibi tekrarlamaktan farklıdır. Sağlık mesajlarıyla ilgili bulgular, tekrar edilen sloganların iş, para veya ilişki çektiğini göstermez."},{id:"manifest-T08",title:"Carrillo et al. · 2019 · Best possible self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 çalışma ve 2.909 katılımcı incelendi. Emek verdikten sonra ulaşılabilecek en iyi gelecek hakkında yazmak, kontrol gruplarına kıyasla iyi oluşu, iyimserliği ve olumlu duyguları ortalama olarak artırdı.",limitation:"Katılımcılar çoğunlukla genç öğrencilerdi. Hiçbir çalışma tüm kalite ölçütlerini karşılamadı. Ruh hâli ve iyimserlik bulguları, dış hedeflere ulaşıldığını veya geleceği şimdiki zamanda yazmanın işe yaradığını kanıtlamaz."},{id:"manifest-T09",title:"Davis et al. · 2016 · Gratitude interventions meta-analysis",url:"https://scottbarrykaufman.com/wp-content/uploads/2021/05/davis2016.pdf",type:"research",finding:"Rastgele atamalı şükran çalışmalarında, bazı kontrol koşullarına karşı iyi oluşta küçük ortalama faydalar bulundu. Şükran uygulamaları, psikolojik açıdan etkin başka uygulamalardan iyi oluşta daha iyi sonuç vermedi. Kaygı bulguları kesin bir sonuca varmak için yeterli değildi.",limitation:"Etkiler, karşılaştırılan uygulamalara ve çalışmaların kalitesine bağlı. Herkes için geçerli bir günlük yazma sıklığı, dış olayları çekme veya henüz yaşanmamış bir olaya olmuş gibi şükretmenin ek faydası gösterilmedi."},{id:"manifest-T10",title:"Cregg & Cheavens · 2021, online 2020 · Gratitude and symptom change",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 çalışma ve 3.675 katılımcı incelendi. Şükran uygulamalarının, birlikte değerlendirilen depresyon ve kaygı belirtilerindeki ortalama etkileri küçüktü. Bekleme listesine karşı etkiler, etkin kontrol koşullarına karşı olanlardan daha büyüktü. Kaygıyı ayrı inceleyen analiz yalnızca beş çalışmayı kapsadı ve kesin bir sonuca varamadı.",limitation:"Belirtilerdeki sınırlı bulgular, şükranın tek başına yeterli tedavi olduğunu göstermez. Yazarlar, depresyon veya kaygısını hafifletmek isteyenlere daha güçlü kanıta sahip uygulamaları öneriyor."},{id:"manifest-T11",title:"Locke & Latham · 2002 · Goal setting and task motivation",url:"https://med.stanford.edu/content/dam/sm/s-spire/documents/PD.locke-and-latham-retrospective_Paper.pdf",type:"research",finding:"On yıllara yayılan hedef belirleme araştırmalarını inceleyen bu derleme, belirli ve zorlayıcı hedeflerin performansı nasıl destekleyebildiğini anlatır. Hedefe bağlılık, geri bildirim, beceri ve işin karmaşıklığı sonuçları etkiler.",limitation:"Kuramı anlatan bir derleme; manifest ritüellerini sınayan bir çalışma değil. Hedefler uygulanabilir yöntemler ve kaynaklar gerektirir. Yeni veya karmaşık işlerde, hemen sonuç alma baskısı yerine öğrenmeye yönelik hedefler gerekebilir."},{id:"manifest-T12",title:"Frattaroli · 2006 · Expressive disclosure meta-analysis",url:"https://bpb-us-e2.wpmucdn.com/faculty.sites.uci.edu/dist/c/602/files/2019/08/Frattaroli-psych-bulletin-2006.pdf",type:"research",finding:"Yaşantı veya duyguları anlatmayı inceleyen rastgele atamalı 146 çalışma, ölçülen sonuçlar genelinde küçük bir ortalama fayda buldu: ortalama r = 0,075 [0,052; 0,098]. Etkiler, ölçülen sonuca ve uygulama biçimine göre değişti.",limitation:"Yaşanan olayları yazmak, istenen bir olayı olmuş gibi yazmaktan farklıdır. Bu derleme her günlük türünü doğrulamaz, travmadan iyileşme sözü vermez veya yazılan hikâyelerin dış sonuçlara neden olduğunu göstermez."},{id:"manifest-T13",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Manifestation beliefs",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"ABD'deki üç çevrimiçi anket örnekleminde toplam 1.023 katılımcı vardı. Manifest inancı, özgüven ve kişinin bildirdiği bazı finansal riskler ile iflasla ilişkiliydi. Bildirilen gelir veya eğitim düzeyiyle ilişkili değildi.",limitation:"İlişkiler ve kişilerin kendi bildirdiği sonuçlar, neden-sonuç ilişkisini, bu inancın toplumdaki yaygınlığını veya her tekniğin etkili olduğunu göstermez. Özgüven, başarının nesnel kanıtı değildir."},{id:"manifest-T14",title:"Denrell · 2003 · Undersampling failure and success stories",url:"https://pubsonline.informs.org/doi/10.1287/orsc.14.2.227.15164",type:"research",finding:"Faaliyetini sürdüren kuruluşlardan nasıl ders çıkarıldığını inceleyen analiz, başarısız örneklerin yeterince görülmemesinin, başarıyla ilgisiz bir uygulamayı başarıyla ilişkili gösterebildiğini anlatır.",limitation:"Kuruluşlara ilişkin modeller kullanıldı; ürün sahibinin viral paylaşımı incelenmedi. Aynı örnekleme ilkesini manifest başarı hikâyelerine uygulamak bir çıkarımdır. Belirli bir hikâyeyi anlatanın dürüst olmadığını göstermez."},{id:"manifest-T15",title:"Awh, Belopolsky & Theeuwes · 2012 · Attentional control",url:"https://research.vu.nl/en/publications/top-down-versus-bottom-up-attentional-control-a-failed-theoretica/",type:"research",finding:"Bu dikkat derlemesine göre, neye dikkat ettiğimizi mevcut hedeflerimiz, bir şeyin fiziksel olarak ne kadar göze çarptığı ve geçmişte nelere dikkat ettiğimiz şekillendirir. Hedefler, başka etkenlerle birlikte dikkatimizi yönlendirebilir.",limitation:"Görsel dikkat kuramı; hayal panolarını, olumlamaları, RAS'ın tek bir dilek filtresi gibi çalıştığı iddiasını veya dış fırsatların yaratılmasını sınamaz. Bir fırsatı fark etmekle o fırsatı var etmek farklı iddialardır."},{id:"manifest-T16",title:"Dai et al. · 2023 · Behavioral priming meta-analysis",url:"https://socialactionlab.org/wp-content/uploads/2024/01/Dai_Priming-Behavior-A-Meta-Analysis-of-the-Effects-of-Behavioral-and-Nonbehavioral-Primes-on-Overt-Behavioral-Outcomes_2023.pdf",type:"research",finding:"351 çalışma ve 862 etkiyi kapsayan derleme, hazırlayıcı uyaranların davranış üzerinde ortalama bir etkisini buldu. Planı önceden kayda geçirilmiş daha küçük çalışma grubunda etkiler daha küçüktü ve istatistiksel olarak kesin bir sonuca varılamadı. Bu durum, etkinin güvenilirliği ve hangi koşullarda görüldüğü konusundaki belirsizliği gösterir.",limitation:"Deneylerde fark ettirmeden sunulan hazırlayıcı uyaranlar, isteyerek yapılan manifest ritüellerinden farklıdır. Önceden kayda geçirilmiş küçük grup, hazırlayıcı uyaranların tüm etkilerini çürütmez. Genel sonuç da tekrarlanan cümleleri, kesin süre eşiklerini veya kozmik çekimi doğrulamaz."},{id:"manifest-T17",title:"Pham & Taylor · 1999 · Process versus outcome simulation",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167299025002010",type:"research",finding:"Sınavlarla ilgili erken bir çalışma, yalnızca iyi bir notu hayal etmeye kıyasla ders çalışma sürecini canlandırmayı destekledi. Planlama ve kaygı, not farklarını açıklamaya katkı sağladı. Süreç canlandırmanın notlar üzerindeki ana etkisi istatistiksel anlamlılık sınırındaydı. Sonradan yapılan, yalnız süreç ile yalnız sonuç canlandırmayı karşılaştıran analizde fark anlamlıydı.",limitation:"Daha sonraki Cole sentezinde, sınavda süreç canlandırma ile kontrol grubu arasındaki sonuç istatistiksel olarak anlamlı değildi. Bu sentez, her koşulda üstün bir canlandırma türü belirlemedi. Dar kapsamlı erken çalışma, kontrole karşı güvenilir not artışı veya dış olayları çekme göstermez."},{id:"manifest-T18",title:"Taylor et al. · 1998 · Mental simulation and self-regulation",url:"https://pubmed.ncbi.nlm.nih.gov/9572006/",type:"research",finding:"Bir araştırma programını anlatan bu kaynak, süreci ve zorluklarla başa çıkmayı canlandırmakla yalnızca başarıyla bitirmiş olmayı hayal etmeyi ayırır. Planlama ve sorun çözmeyi öne çıkarır.",limitation:"Bir araştırma programının derlemesi; kapsamlı bir meta-analiz veya süreç canlandırmanın her zaman üstün olduğunun kanıtı değil. Daha sonraki Cole senteziyle birlikte değerlendir ve ardından işi gerçekten dene."},{id:"manifest-T19",title:"Larson-Prior, Ju & Galvin · 2014 · Sleep, wakefulness and arousal circuits",url:"https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2014.00165/full",type:"research",finding:"Bu sinirbilim derlemesi, retiküler aktive edici sistemin uyanıklık ve beyin kabuğunun uyarılmasında rol alan, birbiriyle etkileşen devreler içindeki yerini anlatır.",limitation:"Uyarılma sinirbilimi, dilek yazmanın bir beyin filtresini fırsat getirecek şekilde programladığını veya uykuya yakın hâlde düşüncelerin dış olayları değiştirdiğini göstermez. Hiçbir manifest ritüeli sınanmadı."},{id:"manifest-P01",title:"Taylor McGrath · 369 manifestation method",url:"https://www.theselfcollective.com.au/blogs/news/369-manifestation-method",type:"technique",finding:"Uygulayıcının tarifi: bir niyet cümlesini şimdiki zamanda yaz; sabah üç, öğleden sonra altı, gece dokuz kez tekrarla.",limitation:"Uygulamayı anlatan bir rehber; etkinliği gösteren kontrollü araştırma değil. Tekrar sayıları, gün döngüleri, dikkatle ilgili iddialar ve Tesla bağlantıları bilimsel bulgu değildir."},{id:"manifest-P02",title:"Victoria Jackson · Scripting an ideal day",url:"https://themanifestationcollective.co/scripting-to-manifest/",type:"technique",finding:"Uygulayıcının tarifi: hayalindeki ideal günü kendi ağzından, şimdiki zamanda günlüğe yaz. Duyulara ilişkin ayrıntıları ve hislerini ekle, sonra yeniden oku.",limitation:"Bir ritüeli anlatır. Bilinçaltını programlama, titreşim, anlamlı tesadüfler ve kişinin kendi sonuçları, kontrollü araştırma kanıtı değildir."},{id:"manifest-P03",title:"Jack Canfield · Creating a vision board",url:"https://jackcanfield.com/blog/vision-board/",type:"technique",finding:"Uygulayıcının tarifi: hedeflerini ve bunları temsil eden görsel veya sözcükleri seç. Kâğıt üzerinde ya da dijital bir kolaj hazırla, görünür yere koy ve düzenli olarak gözden geçir.",limitation:"Uygulamayı anlatan bir rehber; panoların etkili olduğuna kanıt değil. Bu sayfa, Çekim Yasası'nı, başarı hikâyelerini veya RAS açıklamalarını doğrulamaz."},{id:"manifest-P04",title:"Jack Canfield · Daily affirmations",url:"https://jackcanfield.com/blog/daily-affirmations/",type:"technique",finding:"Uygulayıcının tarifi: kendi ağzından, şimdiki zamanda kısa ve belirli cümleler kur. Bunları oku veya tekrarla; çoğu tarif sabah ve akşam yapmayı önerir.",limitation:"Olumlu cümleler, değerlere dayalı kendini olumlama araştırmalarından farklıdır. Bu rehber, herkesin fayda göreceğini veya dış sonuçların değişeceğini göstermez."},{id:"manifest-P05",title:"Jack Canfield · Visualization techniques",url:"https://jackcanfield.com/blog/visualization-techniques-manifest-your-dreams/",type:"technique",finding:"Uygulayıcı rehberi, istenen sonucu duyulara ilişkin ayrıntılarla canlandırmayı, sahnede kendin varmış gibi prova yapmayı ve hedefe ulaşma sürecini zihinde canlandırmayı anlatır.",limitation:"Uygulamayı tarif eder; garantilere veya çekim iddialarına kanıt sunmaz. Zihinde canlandırmayla ilgili deneysel bulgular araştırma kaynaklarından kontrol edilmelidir."},{id:"manifest-P06",title:"Zanna Keithley · 55x5 method description",url:"https://zannakeithley.com/55x5-manifestation-method-worksheet/",type:"technique",finding:"Uygulayıcının tarifi: bir olumlama cümlesini, beş gün üst üste her gün art arda 55 kez yaz. Yazarken cümlenin zaten doğru olduğunu hayal et.",limitation:"Yalnızca herkese açık tarif kullanıldı; çalışma sayfası satın almak gerekmez. Tekrar sayıları ve yüksek titreşim açıklamaları, etkinliği gösteren yerleşik kanıt değildir."},{id:"manifest-P07",title:"Practitioner account · Two-cup method",url:"https://www.reddit.com/r/Manifestation/comments/1poqa0q/insanely_powerful_technique/",type:"technique",finding:"Uygulamayı yapan kişinin tarifi: bardaklara mevcut ve istenen durumu yazan etiketler yapıştır. Değişimi hayal et, suyu ilk bardaktan ikinciye dök ve iç.",limitation:"Adı bilinmeyen bir uygulayıcının anlatısı; doğrulanmış neden-sonuç kanıtı değil. Gerçeklik değiştirme ve sonucu zorla elde etme iddiaları desteklenmiyor. Sade içme suyu ve temiz bardaklar kullan."},{id:"manifest-P08",title:"Sandy · Pillow method guide",url:"https://theprettythoughts.com/the-pillow-method-an-easy-way-to-manifest/",type:"technique",finding:"Uygulayıcının tarifi: bir dileği şimdiki zamanda yaz, kâğıdı katlayıp yastığın altına koy. Uykuya hazırlanırken cümleyi tekrarla veya dileğini canlandır.",limitation:"Tekrar ve katlama sayıları değişir. Kâğıt, bilinçaltı, kristal, yağ ve çekimle ilgili iddialar, etkinliği gösteren kontrollü araştırma kanıtı değildir."},{id:"manifest-P09",title:"Sandy · Whisper method guide",url:"https://theprettythoughts.com/the-viral-whisper-method-manifestation-technique/",type:"technique",finding:"Uygulayıcının tarifi: rahatla, başka birinin yanına gittiğini hayal et. İstediğin şeyi kulağına üç kez fısılda, sonra hayalindeki sahneden ayrıl.",limitation:"Kişisel deneyim anlatısı; telepati kanıtı değil. Hayalinde birinden bir şey istemek, o kişiyi kontrol ettiğini göstermez; rızasını ve sınırlarını geçersiz kılamaz."},{id:"manifest-P10",title:"Simi · The Gratitude Game",url:"https://www.thesecret.tv/stories/the-gratitude-game/",type:"technique",finding:"Uygulamayı yapan kişi, şükran günlüğüne takdir ettiği şeyleri nedenleriyle birlikte yazmayı, ardından yazdıklarını yeniden okumayı anlatır.",limitation:"Kişisel anlatı; bir müdahale araştırması değil. Bu hikâye, şükranın olayları çektiğini veya sorunları ortadan kaldırdığını göstermez."},{id:"manifest-P11",title:"Alexandra · Act as if it is already done",url:"https://www.thesecret.tv/stories/act-as-if-its-already-done/",type:"technique",finding:"Kişinin kendi anlatısı, istediği işe kabulü kesinleşmiş gibi kıyafet ve bavul hazırlamayı, bu sırada istenen sonucu hayal etmeyi tarif eder.",limitation:"Yazar, zaten tanıdığı birinden teklif aldığını anlatıyor. Tek bir hikâye, sonuca neyin neden olduğunu ayıramaz veya genel bir çekim yasasını doğrulayamaz."},{id:"manifest-P12",title:"Victoria Jackson · Letter from your future self",url:"https://themanifestationcollective.co/wp-content/uploads/2021/04/Scripting-To-Success-Masterclass.pdf",type:"technique",finding:"Uygulayıcı kaynağı, hayalindeki gelecekteki hâlinin bugünkü sana hayatındaki değişimleri anlatan, anlayışla yaklaşan bir mektup yazmasını tarif eder.",limitation:"6-7. sayfalar uygulamayı belgeliyor; gelecekle iletişimi veya dış sonuçlarda etkinliği kanıtlamıyor. Tarih ve selamlama, mektup biçiminde isteğe bağlı tercihlerdir."},{id:"manifest-P13",title:"Abraham / Esther and Jerry Hicks · 17-second focus",url:"https://spiritlibrary.com/abraham-hicks/only-17-seconds-away-from-your-true-desires",type:"technique",finding:"Öğretmenin konuşma dökümü, karşıt bir düşünce olmadan istenen düşünceye 17 saniye odaklanmayı tarif eder. Dört kez yapıldığında toplam süre 68 saniyedir.",limitation:"Manevi bir öğreti; kontrollü kanıt değil. Kesin eşikler, düşüncelerin ‘tutuşması’, düşüncenin fiziksel dünyada gerçekleşmesi ve belirli çalışma saatlerine eşdeğer olduğu iddiaları desteklenmiyor."},{id:"manifest-P14",title:"Amy Parker · Creating a manifestation box",url:"https://envibelife.com/creating-a-manifestation-box/",type:"technique",finding:"Uygulayıcının kendi tarifi: niyet kartlarını veya görselleri bir kutuya koy, yaşamak istediğin duyguları ekle ve kutudakileri yeniden gözden geçir.",limitation:"Simgesel bir uygulamayı belgeler. Enerji alanı ve dileklerin gerçekleşmesine ilişkin açıklamalar inançtır; bilimsel bulgu değil. Elindeki bir kap yeterlidir."},{id:"manifest-P15",title:"Neville Goddard · Five Lessons, 1948",url:"https://readnevillegoddard.com/five-lessons/",type:"technique",finding:"Öğretmenin özgün metni, uykulu hâlde gevşemeyi, dileğin gerçekleştiği kısa bir sahneyi, sahneye kendin katılmayı ve hayalindeki eylem gerçekmiş gibi hissedene kadar tekrarlamayı anlatır.",limitation:"Ücretsiz döküm, SATS öğretisini belgeler; etkinliğini değil. Dış sonuçlara ilişkin metafizik iddialar ve eylem gerekmediği iddiası bilimsel kanıt değildir. Uykunu koru."}],d=[{number:6,technique:"3-6-9 yöntemi",title:"3-6-9: defterdeki şirkete bugün bir başvuru gönder",goal:"Defterini kullanmaya devam et; seçtiğin somut hedef için bir işi tamamla.",hook:"Yine “İşe girdim” mi yazıyorsun? Diğer sayfada adı duran şirkete bugün bir başvuru gönder.",reason:"Bu defter istediğin iş için adım atmanı mı sağlıyor, başvuru zamanını mı alıyor?",paragraphs:["3-6-9 yönteminde, istediğin şey olmuş gibi kurduğun olumlama cümlesini sabah üç, öğlen altı, gece dokuz kez yazarsın. İki sayfalı biçiminde, istediğin şirketler solda, “İşe girdim” sağda durur. Araştırma desteklemiyor: bu özel sayıların iş teklifi çektiği iddiasını. Tek bir başarı hikâyesi, tekrarın etkisini başvuruların etkisinden ayıramaz. Deneyip teklif alamayanları da göstermez.","ODA uyarlaması: sayfalar kalsın, tekrar düzeni isteğe bağlı olsun. Sola somut hedeflerini ve bugünkü başvuru, takip ya da hazırlık işini yaz. Sağa kendin hakkında inanabildiğin bir cümle ve “Şu engel çıkarsa bunu yaparım” planı ekle. Belirli bir işareti yapılabilir bir işle eşleştiren planları araştırma destekliyor. Bugün hedefin için bir iş yap. Yarın yaptığınla gelen yanıtı ayrı değerlendir."],example:{title:"Derya iki sayfayı da kullanıyor",text:"Derya sol sayfaya iki lojistik şirketi, sağa “Özenli başvurular hazırlıyorum” yazıyor. Öğle yemeğinden sonra bir ilanı inceleyip ona göre düzenlediği öz geçmişini gönderiyor. Planı şöyle: “Başvuru sitesi açılmazsa taslağı saklayıp insan kaynaklarına ulaşacağım.” Sitelerden biri açılmıyor. Derya ilettiği iletişim talebini kaydediyor. Henüz iki şirketten de bir iş teklifi gelmiş değil."},instructions:["Sol sayfaya bir hedef ve bugünkü başvuru, takip ya da hazırlık işini yaz.","Sağ sayfaya kendinle ilgili bir cümle ekle. Engel çıkarsa ne yapacağını yaz.","Hedefin için seçtiğin işi yap; yarın denemeni ve varsa gelen yanıtı ayrı değerlendir."],action:["İlana göre düzenlenmiş başvuruyu gönder","Şirkete başvurunun durumunu sor"],minimum:["Uygun bir ilana başvur","Başvuru hakkında bir soru gönder"],cue:["Öğle yemeği bittikten sonra","Sabah yazımı bitirdiğimde"],place:["Başvuru hazırladığım masada","Şirketin başvuru sitesinde"],obstacle:"Başvuru sitesi açılmıyor",fallback:["Taslağı sakla, insan kaynaklarına ulaş","Başka bir uygun başvuru fırsatını kullan"],observation:["Gönderdiğim başvuru veya talep, varsa yanıt","Başvuru için tamamladığım iş"],stopRule:"İş yapacağın zamanı alan tekrarları atla. Masrafını karşılayamadığın ya da uygun olmayan başvurulara ara ver.",scenario:"Derya cümlesini 18 kez yazdı ve üç şirketi listeledi. Ona uygun bir ilanın süresi bu gece doluyor. Başvuruda deneyimini anlatan kısa bir paragraf eksik.",question:"Defteri yeniden açınca hangi işi tamamlamalı?",options:[{key:"repeat",text:"Olumlama düzenini sürdürsün. Başvuruya dönmeden önce kendini anlatan daha uzun bir cümle hazırlasın.",feedback:"Bu cümle uygulamasının bir parçası olarak kalabilir. Ama onu uzatmak, başvurudaki eksik paragrafı tamamlamaz. Son tarih yaklaşıyor. Defterini açtığında bu paragrafı yazmayı hatırlasın ve kalan zamanı o iş için kullansın."},{key:"submit",text:"Eksik paragrafı yazıp başvursun. Gönderdiği başvuruyu ve işverenden gelebilecek yanıtı ayrı ayrı kaydetsin.",feedback:"Bu seçim, belirlediği hedefe ve son tarihe uyuyor. Başvuruyu göndermek onun yaptığı iş; yanıt gelmesi kendi kontrolünde değil. İsterse uygulamasını da sürdürebilir. Sonra ne olduğunu, olmayan bir yanıtı var saymadan değerlendirebilir."},{key:"expand",text:"Önce şirket listesini genişletsin; böylece yarın iş ararken daha fazla şirket arasından seçim yapabilsin.",feedback:"Daha geniş aramak ileride işe yarayabilir. Ama bu gece süresi dolan, ona uygun bir ilan zaten var. Listeyi genişletmek bu başvuruyu geciktirir. Önce başvurunun eksik deneyim paragrafını yazıp elindeki fırsatı kullansın."}],best:"submit",takeaway:"Defterini açınca başvurunu yap. Yaptığın işleri ve gelen yanıtları ayrı ayrı say.",review:"Hedefin için hangi işi yapmayı denedin? Listendeki bir şirketten yanıt geldi mi?",deeper:[{heading:"Yaygın tarif ve iki sayfalı defter",paragraphs:["1. İstediğin bir sonucu seç ve olmuş gibi bir cümle kur. 2. Bu olumlamayı sabah üç kez yaz. 3. Öğlen civarında altı kez tekrarla. 4. Gece dokuz kez yaz. Bu sayılar yöntemin yaygın tarifini anlatıyor; araştırmayla belirlenmiş bir uygulama dozu değiller. Bu yöntemi anlatan kişiler, aynı düzeni ne kadar süre sürdürdükleri konusunda da farklı şeyler söylüyor. [manifest-P01]","5. Kurs sahibinin aktardığı iki sayfalı örnekte, sağda “İşe girdim” yazıyor. Solda kişinin başvurduğu ve çalışmak istediği şirketler var. Bu kişi, listedeki bir şirketten teklif aldığını söylüyor. Bu, kurs sahibinin aktardığı bir hikâye; bağımsız olarak doğrulanmış deney verisi değil. Burada hayatta kalma yanlılığı olabileceğini söylemek bir çıkarım: görünen başarı, aynı uygulamayı deneyip teklif alamayanları göstermiyor. Kişi yaşadığını içtenlikle anlatıyor olabilir; bu yine de teklifin neden geldiğini açıklamaz. [manifest-T14]"]},{heading:"Tekrar düzeni kalsın, ardından bir iş gelsin",paragraphs:["Planlama araştırması, tanıyabileceğin belirli bir durumla yapabileceğin bir işi eşleştirmeyi inceliyor. Üç, altı veya dokuz tekrarın işvereni etkilediğini göstermiyor. Yazmak hoşuna gidiyorsa sayı kalsın. Yanına ne yapacağını ekle: hangi şirket, hangi uygun ilan ve bugün hangi iş? Sol sayfadaki şirket listesi ve gönderilen başvurular, teklif almaya giden somut bir yol sunar. Ama bu hikâye, kişinin teklifini hangi etkenin sağladığını ayırt edemez. Teklifi tek başına tekrarın sonucu sayma. [manifest-T02, manifest-T14]","Sağa “Özenli başvurular hazırlıyorum” yazmayı deneyebilirsin. Altına şunu ekle: “Site açılmazsa taslağı saklayıp insan kaynaklarına ulaşacağım.” Son tarihi, siteye erişimini ve ayırabileceğin zamanı kontrol et. Bugün başvur ya da sorunu ilet; yaptığın işi açıkça kaydet. Yarın işverenden yanıt gelip gelmediğine bak. Sessizliği yeterince inanmadığının işareti sayma. Tekrar, hazırlık, başvuru ve teklif ayrı ayrı kalsın. Böylece defterde ne yaptığın görülebilir. Bu iki sayfalı düzen ODA uyarlamasıdır; bütün olarak sınanmış bir uygulama değildir. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Geleceği olmuş gibi yazma",title:"Hayalindeki gün güzel. Oraya götüren işi de yaz",goal:"Gelecekteki bir sahneden yola çık; hedefin için bugün deneyeceğin bir iş seç.",hook:"Günlüğünde her şey yolunda, bugünkü iş hâlâ bekliyor mu? O güzel güne gelmeden önce ne yaptığını da yaz.",reason:"Yeni bir sayfa yazmadan önce, bu sayfa hangi işi yapmana yardım edecek?",paragraphs:["Scripting, istediğin gelecek şu an yaşanıyormuş gibi günlük yazmaktır. Bir sahne seçer, ayrıntılarını ve hissettiklerini yazıp yeniden okursun. Bulgular karışık: ilgili “olabileceğin en iyi sen” yazma çalışmalarında, iyi oluş ve iyimserlik ortalama olarak arttı. Ama olmuş gibi yazmanın olayları gerçekleştirdiği gösterilmedi. Duyguları yazarak anlatma araştırmaları da gerçek yaşantılarla ilgili; dileklerin gerçeğe dönüşmesiyle değil.","ODA uyarlaması: sahne kalsın, ama oraya götüren işleri de ekle. Somut hedefini, bugünkü engeli ve engel çıkarsa ne yapacağını yaz. Bugün deneyeceğin tek işin altını çiz. Yarın bütün sahnenin gerçekleşip gerçekleşmediğini sorgulamak yerine, denediğin işle planını karşılaştır. Bu öğeleri bir araya getiren alıştırma bir uyarlamadır; aynı biçimde sınanmış değildir."],example:{title:"Elif aradaki işi de yazıyor",text:"Elif yeni işindeki sakin bir sabahı yazıyor. O sabaha gelmeden önce yapacağı mülakat hazırlığını da ekliyor. Akşam yemeğinden sonra, zor bir müşteriyle nasıl ilgilendiğini anlatan tek bir yanıtı ses kaydına alıyor. Dinlerken acele ettiğini fark edip kısaltacağı bir cümleyi işaretliyor. İş hâlâ hayal, ama yarın geliştirebileceği gerçek bir kaydı var."},instructions:["Gelecekteki sahneyi yaz; gereken işleri ve kaynakları da sahneye ekle.","Bugünkü işin altını çiz. “Şu engel çıkarsa bunu yapacağım” diye ekle.","Seçtiğin en küçük adımı dene; yarın gerçekte ne olduğunu değerlendir."],action:["Bir mülakat yanıtını ses kaydına al","Bir portfolyo açıklaması taslağı yaz"],minimum:["Tek bir yanıt kaydını sakla","Kullanılabilir bir açıklamayı kaydet"],cue:["Akşam sofrası toplandıktan sonra","Günlüğümü kapattığımda"],place:["Mutfak masamda","Portfolyo dosyamda"],obstacle:"Kusursuz bir giriş cümlesi bulamıyorum",fallback:["İlk cümleyi taslak olarak yaz","Somut bir örnek iste"],observation:["Sakladığım ses kaydı","Taslağım ve hâlâ eksik kalan kısmı"],stopRule:"Seni sıkıntıya sokan sahneleri atla. Geleceği yazmak iyi gelmiyorsa sıradan iş notları kullan.",scenario:"Elif yazdığı sahnede mülakatta kendinden emin konuşuyor. Mülakatı yarın. Müşteri hizmetleriyle ilgili sık sorulan bir soru için henüz hazır bir örneği yok.",question:"Bu sayfayı bu akşam işe yarar hâle getiren değişiklik hangisi?",options:[{key:"draft",text:"Gerçek bir müşteri örneği eklesin, bir yanıtı prova etsin ve yarın dinlemek için taslak kaydını saklasın.",feedback:"Böylece yazdığı sahne yarınki işe bağlanır. İlk yanıtın taslak olması, hangi kısmın geliştirilmesi gerektiğini görmesini sağlar. İşe alınmayı garanti etmez; ama Elif yarın dinleyip üzerinde çalışabileceği bir hazırlık yapmış olur."},{key:"feelings",text:"Hangi müşteri örneğini kullanacağına karar vermeden önce, kendinden emin olmanın nasıl hissettirdiğini ayrıntılı yazsın.",feedback:"Duyguları anlatmak sahneyi kendisi için anlamlı kılabilir. Ama burada eksik olan, yaşadığı gerçek bir olaya dayanan yanıt. Hislerini daha ayrıntılı yazsa da bu eksik kalacak. Bir müşteri örneği seçip yanıtını prova etsin."},{key:"edit",text:"Hayal ettiği mülakatı baştan sona açık ve tutarlı anlatmak için günlüğündeki bütün metni yeniden düzenlesin.",feedback:"Tutarlı bir hikâye yazmak başlı başına bir hedef olabilir. Elif’in şu an ihtiyacı bir mülakat yanıtı hazırlamak. Akşamki sınırlı zamanını hikâyeyi düzeltmeye ayırırsa, yarın sorulduğunda kullanacağı müşteri örneğini hâlâ hazırlamamış olur."}],best:"draft",takeaway:"İstediğin geleceği yazarken, oraya götüren işlerden birini de bugün gerçekten denemek için seç.",review:"Yazdığın hangi adımı yapmayı denedin? O işin hangi kısmı hâlâ yarım kaldı?",deeper:[{heading:"Bu günlük uygulaması nasıl yapılıyor?",paragraphs:["1. İstediğin bir durum seç; örneğin çalışmak istediğin işte geçen bir gün. 2. O günü şimdi yaşıyormuş gibi günlük yaz. 3. Sıradan ayrıntıları anlat: neredesin, ne yapıyorsun, nasıl hissediyorsun? 4. Yazdığını yeniden oku; istersen sonra tekrar dön. Bazı biçimlerinde şükür ifadeleri veya sonucun olacağına dair kesinlik duygusu da eklenir. Bunlar uygulayıcıların tarifidir; iş teklifi almaya götürdüğü doğrulanmış bir yol değildir. [manifest-P02]","Hayal ettiğin olayların hayal olduğu açık kalsın. Başka birinin vermediği sözü vermiş gibi yazmadan da sıradan bir sahne kurabilirsin. ODA alıştırmasında gereken işleri, kullanabileceğin kaynakları ve bugün karşılaştığın bir engeli ekle. Sayfadan tek bir iş seç. İstersen klavyeyle yaz veya sesle anlat. Bunlar erişilebilir seçeneklerdir; her anlatım biçiminin araştırmada aynı etkiyi gösterdiğini iddia etmiyoruz. Defterle yazmak zorunda değilsin. Bu uygulamayı yapıp yapmamak da senin seçimin. [manifest-P02]"]},{heading:"Gelecek hayaliyle gerçek yaşantıyı yazmak farklı",paragraphs:["“Olabileceğin en iyi sen” araştırmasında, insanlar emek vererek ulaşabilecekleri iyi bir geleceği hayal eder. Carrillo ve arkadaşları iyi oluş, iyimserlik ve olumlu duygulanımda ortalama yararlar buldu. Çalışmaların kalitesiyle ilgili sınırlar vardı. Bu bulgu, düşünerek yazmanın bazı yararları olabileceğini destekler; yazılan olayların gerçekleşeceğini göstermez. Duyguları yazarak anlatmanın konusu ise gerçek yaşantılar veya hislerdir. O araştırmadaki küçük ortalama yarar da gelecekteki olayları düşünceyle çekme iddiasını doğrulamaz. İki yazma biçiminin neyi incelediğini ayrı tut. [manifest-T08, manifest-T12]","ODA sahneyi korur ve sayfayı kapattığında yapabileceğin bir iş ekler. Kursta zaten denediğin somut hedefi seç. Bugünkü adımı neyin engelleyebileceğini yaz. Sonra masrafını karşılayabileceğin, gerçekten yapabileceğin bir çözüm belirle. Ne zaman başlayacağını ve en küçük adımı kaydet; dene, yarın değerlendir. Mülakat provasını hazırlık olarak yaz. Gönderdiğin başvuruyu başvuru, gelen yanıtı ancak geldiğinde yanıt olarak kaydet. Böylece hayalinle yaptığın iş birbirine karışmaz. Bu düzen bir tasarım uyarlamasıdır; araştırmadaki iki yazma yönteminden hiçbirinin özgün deney düzeni değildir."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Hayal panosu",title:"Hayal panosu: o güzel masada bugün ne yapacaksın?",goal:"Panondaki bir görseli, yapabileceğin somut bir işe başlama işareti olarak kullan.",hook:"Panondaki çalışma masası çok güzel. Peki bugün kendi masanda hangi işi yapacaksın?",reason:"Hangi görsel başkasının başarı ölçüsünü değil, senin önceliğini anlatıyor?",paragraphs:["Hayal panosunda, istediğin hayatı anlatan görselleri ve sözleri bir araya getirirsin. Seç, yerleştir, görebileceğin bir yere koy ve ara ara bak. Bulgular karışık: güncel hedefler dikkati etkileyebilir; göze çarpan şeyler ve geçmiş deneyimler de etkiler. Bu, panonun işe yaradığını veya resimlerin fırsat çektiğini göstermez. Retiküler aktive edici sistem uyanıklıkla ilgilidir. Onu programlanabilir bir dilek filtresi diye anlatmak, kanıtın söylediğini aşar.","ODA uyarlaması: senin için anlamlı bir görsel kalsın. Altına somut hedefini ve bugün yapacağın tek işi yaz. Bir engel seç, çıkarsa ne yapacağını belirle. Görseli görmek başlama işaretin olsun. Yarın onu görünce en küçük adımı yapıp yapmadığına bak. Var olan bir fırsatı fark etmekle o fırsatı yaratmak farklı iddialar; kaydında da ayrı kalsın."],example:{title:"Ece masa görseline bir iş ekliyor",text:"Ece’nin panosunda bir tasarım stüdyosundaki masa var. Altına “Bir portfolyo örneği hazırla” yazıyor. Kahvaltıdan sonra resmi görünce yarım kalan projesini açıp bir açıklama yazıyor. Ortaya çıkan çalışma, stüdyo hayali kadar heyecan verici görünmüyor. Yine de dosyasına kaydediyor. Proje için hâlâ birinden yorum alması gerektiğini de not ediyor."},instructions:["Bir görsel seç; altına somut hedefini ve bugünkü yararlı işi yaz.","Görseli görmek başlama işaretin olsun. Olası bir engelde ne yapacağını planla.","İşi dene; yarın görseli gördüğünde başlama işaretini fark edip etmediğine bak."],action:["Bir portfolyo açıklaması yaz","Proje için bir yorum talebi gönder"],minimum:["Kullanılabilir bir proje açıklamasını kaydet","Yorum için belirli bir soru gönder"],cue:["Kahvaltıdan sonra panoyu görünce","Proje klasörümü açınca"],place:["Çalışma masamda","Portfolyo dosyamda"],obstacle:"Görseli görünce çalışmak yerine gezinmeye başlıyorum",fallback:["Gezinmeden önce proje dosyasını aç","Dosyanın yanına yazılı hatırlatıcı koy"],observation:["Görseli görünce işe başlayıp başlamadığım","Tamamladığım açıklama veya gönderdiğim talep"],stopRule:"Elindeki resimleri veya sözleri kullan. Seni harcamaya zorlayan görselleri atla.",scenario:"Ece her sabah panosunu görüyor, ardından stüdyo fotoğraflarına bakarak oyalanıyor. Portfolyosunda bitirdiği bir projeyi anlatmak için gereken açıklama henüz yok.",question:"Hangi değişiklik bugün daha çok işine yarar?",options:[{key:"fresh",text:"Pano yeniden anlamlı gelsin diye stüdyo görselini, ona daha çok ilham veren başka bir görselle değiştirsin.",feedback:"Yeni bir görsel seçmek hoşuna gidebilir. Ama kaydı, panoyu görünce internette gezindiğini gösteriyor; hedefinin eksik olduğunu değil. Resmi gördüğünde sırada ne yapacağını değiştirsin. Böylece mevcut görsel, bilinen işe başlamasını hatırlatabilir."},{key:"study",text:"Ulaşmak istediği düzeyi anlamak için ertesi sabahını farklı tasarım stüdyolarının portfolyolarını karşılaştırmaya ayırsın.",feedback:"Karşılaştırma daha sonra çalışmasına bilgi sağlayabilir. Ece’nin şu an açıklama bekleyen tamamlanmış bir projesi var. Gezinmek bu açıklama için gereken belirli bir soruyu yanıtlamıyorsa, bir sabah daha aynı oyalanma düzeni sürmüş olur."},{key:"label",text:"Görselin altına “Projeyi aç, açıklamasını yaz” eklesin. Stüdyo fotoğraflarına bakmadan önce bir açıklamayı kaydetsin.",feedback:"Böylece zaten gördüğü işaret, eksik olan işi hatırlatır. Ece yarın etiketi fark edip etmediğini ve açıklamayı kaydedip kaydetmediğini kontrol edebilir. Bu, inceleyebileceği somut bir denemedir. Panonun kendisi stüdyoda iş bulmayı garanti etmez."}],best:"label",takeaway:"Resmi gördüğünde bugün bir işe başla. Resmin gücünü sorgulamak yerine yaptığın işi değerlendir.",review:"Görselini görünce planladığın işi mi yaptın, yoksa başka bir şeye mi yöneldin?",deeper:[{heading:"Yeni bir şey almadan hayal panosu hazırla",paragraphs:["1. İstediğin bir yönü veya durumu seç. 2. Onu anlatan birkaç resim ve söz topla. 3. Kâğıda, elindeki bir panoya veya dijital bir sayfaya yerleştir. 4. Ara ara bakmak istediğin yere koy. 5. Panoya bakıp istediğin durumu hayal et. Bu adımlar yaygın uygulamanın nasıl yapıldığını anlatıyor. Panonun, o durumu gerçekten meydana getirdiğine dair kanıt değiller. Tarifle etkinlik iddiasını ayrı tut. [manifest-P03]","Bu kursta hayatının her yanını değiştirme hedeflerini yığmak yerine bir yön seç. Elindeki bir fotoğraf, çizim veya yazılı bir söz yeterli. Bir görselin altına yapacağın işi yaz: eğitim hakkında soru sormak, bir örneği bitirmek veya uygun bir ilana başvurmak. Görseli gördüğünde harekete geçebileceğin bir yer seç. Kullanacağın malzemeler ve yerleşim senin tercihin. Özel malzeme satın alman gerektiğine dair bilimsel bir koşul yok. Resimleri yerleştirmekle hedefin için seçtiğin işi tamamlamak ayrı işler; birini yapınca diğerini yapılmış sayma."]},{heading:"Fark etmek neyi açıklayabilir?",paragraphs:["Dikkat araştırması, neye yöneldiğimizi güncel hedeflerin, fiziksel olarak göze çarpan özelliklerin ve geçmişteki seçimlerin etkilediğini anlatır. İlgili fırsatlara bilinçli olarak bakmanın makul bir yanı var. Ama fark etmeyi geliştirdiği söylenen her yöntemi doğrulamaz. Retiküler aktive edici sistem, uyanıklık ve uyarılmayla ilgili sinir devrelerinde rol alır. Bu bulgular, panonun kontrol ettiği bir filtrenin iş, eş veya ev getirdiğini göstermez. Yeni fark ettiğin bir fırsat, dikkatini vermeden önce de var olmuş olabilir. Fark etmeyi, fırsatın kaynağı diye anlatma. [manifest-T15, manifest-T19]","ODA görsele gizli bir güç yüklemek yerine onu açık bir hatırlatıcı olarak kullanır. Hedefini, bugünkü işi ve seni en çok durdurabilecek engel çıkarsa ne yapacağını yaz. Panoyu görünce yine fotoğraflara dalıyorsan önce çalışma dosyanı açmayı planla. Yarın şu sorulara bak: işaret ortaya çıktı mı, onu fark ettin mi, hangi işi yaptın? Başkalarından gelen yanıtları da kendi yaptığından ayrı tut. Böylece hatırlatıcının o fırsatta neye yol açtığını görürsün. Bu görsel ve plan birleşimi, hayal panosu uygulaması olarak deneyle sınanmış değildir."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Olumlamalar",title:"Olumlamalar: inanamadığın cümleyi yapabileceğin işe çevir",goal:"Cesaret veren bir cümleyi, hedefin için yaptığını görebileceğin tek bir işle eşleştir.",hook:"“Çok başarılıyım” bugün sana boş mu geliyor? Sana yapacak bir iş veren cümleyi dene.",reason:"Bu cümle işi denemene yardım mı ediyor, kendini kesinlikle inanmak zorunda mı hissettiriyor?",paragraphs:["Olumlama, cesaret veren bir sözü tekrar tekrar söylemek veya yazmaktır. Çoğu kez istenen sonuç olmuş gibi kurulur. Cümle seçilir, tekrarlanır, ona inandığın hayal edilir. Bulgular karışık: Wood ve arkadaşlarının çalışmasında çok olumlu bir cümle, öz saygısı düşük bazı katılımcıların ruh hâlini kötüleştirdi. Araştırmadaki kendini olumlama, çoğunlukla önemli değerleri düşünmektir; başarı sloganı tekrarlamak değil. Sağlık davranışı bulguları, sözlerin iş teklifi çektiğini göstermez.","ODA uyarlaması: sana kullanışlı gelen, cesaret veren bir cümle kalsın. Bir değerini ve onu yansıtan işi seç: “Yaşadığım bir olayı dürüstçe anlatmaya hazırlanıyorum.” Somut hedefini, engeli ve engel çıkarsa ne yapacağını belirle. Bugün işi dene, yarın ne yaptığına bak. Sana daha kötü hissettiren cümleyi değiştir veya atla. Onu söylemek bir zorunluluk olmasın."],example:{title:"Selin cümlesini değiştiriyor",text:"Selin toplantıdan önce “Harika bir konuşmacıyım” diyor, ama daha çok utanıyor. “Tek bir düşüncemi açıkça anlatmaya hazırlanıyorum” cümlesine geçiyor. Masasında bir öneri yazıp söylemeyi prova ediyor. Toplantıda ilk cümleyi söylüyor, sonra ne diyeceğini unutuyor. Kaydına sunduğu öneriyi ve açıklamasının yarım kalan kısmını yazıyor. Söylediğiyle söyleyemediğini ayrı tutuyor."},instructions:["Bir değerini ve somut bir işi hatırlatan, cesaret verici bir cümle seç.","Bir engel belirle. İnanmayı şart koşmadan, engel çıkarsa yapabileceğin şeyi yaz.","Bugün işini dene; yarın yaptığını ve cümlenin sana nasıl hissettirdiğini değerlendir."],action:["Toplantıda hazırladığın bir cümleyi söyle","Proje hakkında açık bir soru sor"],minimum:["Önerinin ilk cümlesini söyle","Proje hakkında belirli bir soru gönder"],cue:["Toplantıda öneriler sorulduğunda","Proje mesajlarını açtığımda"],place:["Toplantı odamızda","Proje mesaj grubunda"],obstacle:"Cesaret veren cümlem bana inandırıcı gelmiyor",fallback:["Olumlama yapmadan hazırladığım cümleyi söyle","Yapacağım işi söyleyen sade bir hatırlatıcı kullan"],observation:["Ne söylediğim ve gelen yanıt","Cümle yardım etti mi, kötü hissettirdi mi?"],stopRule:"Seni sıkıntıya sokan cümleleri değiştir veya atla. Kendini kesinlikle inanmaya zorlaman gerekmiyor.",scenario:"Selin tekrar ettiği başarı cümlesiyle kendini daha kötü hissediyor. Yine de toplantıda yararlı bir öneri sunmak istiyor. Hazır bir taslak cümlesi var.",question:"Bu iki durumu da gözeten değişiklik hangisi?",options:[{key:"persist",text:"Önerisini prova etmeyi sürdürsün. Başarı cümlesini değiştirmeden önce birkaç seans daha tekrarlamaya devam etsin.",feedback:"Prova hazırlığına yardım edebilir. Ama ruh hâlini kötüleştiren bir cümlede ısrar etmesi gerekmiyor. Hazırladığı öneri zaten elinde. Bu, kendini bir söze inanmaya zorlamadan başlamasını sağlayacak başka bir yol; önerisini küçük tutarak deneyebilir."},{key:"action",text:"Sade bir iş hatırlatıcısı kullansın veya olumlamayı atlasın. Öneriler sorulduğunda hazırladığı cümleyi söylesin.",feedback:"Bu seçim, yaşadığı rahatsızlığı gözetirken yapılabilir bir katkıya yer bırakır. Selin ne söylediğini ve hatırlatıcının nasıl hissettirdiğini sonra değerlendirebilir. Öneri sunmak için harika bir konuşmacı olduğundan kesinlikle emin olması gerekmiyor. Hazır cümlesiyle başlayabilir."},{key:"wait",text:"Güçlü yanlarını anlatan daha iddialı bir cümle hazırlasın. İyice inanana kadar toplantıdaki önerisini ertelesin.",feedback:"Değerlerini düşünmekle kendini büyük bir iddiaya ikna etmeye çalışmak farklı işler. İnanmayı beklemek, zaten hazır olan öneriyi söylemek için önce öz güven şartı koyar. Katkısını küçük tutabilir; olumlama söyleyip söylememek onun seçimi olarak kalsın."}],best:"action",takeaway:"Cümleyi istersen hatırlatıcı olarak kullan. Ne yapabildiğini, yaptığın somut iş göstersin.",review:"Neyi denedin? Cümle yardım mı etti, zorlaştırdı mı, yoksa hiçbir fark yaratmadı mı?",deeper:[{heading:"Yaygın olumlama uygulamasının adımları",paragraphs:["1. İstediğin bir sonuç veya kişisel özellik seç. 2. Olumlu bir cümle kur; çoğu biçiminde şu anda doğruymuş gibi söylenir. 3. Tekrar tekrar söyle veya yaz. 4. Cümleyi kullanırken istediğin durumu hayal et. 5. Seçtiğin zamanda yeniden dön. Uygulayıcıların tariflerinde sıklık ve sözcükler değişir. Bu yaygın tarif, bilimsel olarak gerekli bir tekrar sayısı veya his belirlemez. Bu tarif, belirli bir sayıyı tamamlamanın gerekli olduğunu göstermiyor. [manifest-P04]","Uygulamanın en büyük vaadini doğru saymadan da onu sevebilirsin. ODA için, gerçekten deneyeceğin işe işaret eden bir cümle kullan. “Tek bir düşüncemi açıkça anlatmaya hazırlanıyorum” toplantı notlarının yanında durabilir. Hiç cümle kullanmamayı da seçebilirsin. Rahatsız eden veya inandırıcı gelmeyen bir söz, geçmen gereken sınav değil. Wood ve arkadaşları belirli bir olumlu sözü ve kısa süreli ruh hâli etkilerini inceledi. Bu sonuç, kendine anlayışla söylediğin her cümlenin zarar verdiğini göstermiyor. Bulguyu bütün sözlere genelleme. [manifest-T06]"]},{heading:"Bir değeri düşünmekle başarı sloganı farklı",paragraphs:["Kendini olumlama araştırmasında insanlar, kendileri için tehdit oluşturabilecek bilgiyle karşılaşmadan önce önemli değerleri, özellikleri veya ilişkileri düşünür. Epton ve arkadaşları sağlık mesajlarıyla yapılan deneyleri birleştirdi. Mesajı kabul etmede ve niyetlerde küçük ortalama etkiler, o bağlamda davranışta da yarar buldu. Bu işlemler, istenen sonucu olmuş gibi tekrar etmekten farklıdır. “İşe girdim” demenin ardından iş teklifi geleceğini göstermez. Bir araştırmanın olumlama sözcüğünü kullanması, yaygın olumlama cümlelerinin bütün vaatlerini sınadığı anlamına gelmez. [manifest-T07]","ODA bu ayrımdan yararlanır, bütün uygulamanın sınandığını söylemez. Dürüstlük gibi bir değer seç. Mevcut hedefinde bunu gösterecek tek bir iş belirle: yaptığın işi doğru anlatan bir örnek hazırla. Başlama fırsatını ve en küçük adımı kaydet. Ne diyeceğini unutmak gibi olası bir engelde ne yapacağını yaz. Bugün cümleni söylemeyi dene. Yarın sunduğun katkıyı ve hatırlatıcının kullanışlı gelip gelmediğini kaydet. Olumlama baskı yaratıyorsa atla; yapabileceğin iş kalsın. Söze inanmak, o işi denemenin ön koşulu olmasın. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Zihinde canlandırma",title:"Teklifi hayal ettin. Önce soruya vereceğin yanıtı prova et",goal:"Bir iş seç, zorlanacağın kısmı prova et ve gerçekten bir deneme yap.",hook:"İş teklifini hayal etmek güzel. Şimdi o tekliften önce sorulacak soruya yanıt vermeyi prova et.",reason:"Bir sahne daha kurmak gereken eksiği mi gösterecek, hazır olan işi mi geciktirecek?",paragraphs:["Zihinde canlandırma, istediğin olayı çoğu kez duyusal ayrıntılar ve başarı hissiyle hayal etmektir. Rahatla, sahneyi kur, içinde olduğunu düşün; istersen tekrarla. Manifestasyon açısından bulgular karışık: zihinsel canlandırma, sonraki davranışa ortalama destek verdi. Olayları çektiği gösterilmedi. Eski bir sınav çalışmasında bazı karşılaştırmalar, çalışma sürecini hayal etmeyi destekledi. Sonraki meta-analizde ise hangi canlandırma türünün daha iyi olduğu güvenilir biçimde belirlenemedi.","ODA uyarlaması: sonucu anlatan kısa bir sahne kalsın. Ardından yapacağın işi ve bir engeli prova et. Somut hedefini ve engel çıkarsa ne yapacağını seç. Bugün tek bir işi dene, yarın değerlendir. Prova yine hazırlık olarak kalsın. Zihninde görüntü oluşmuyorsa adımları yaz. Canlı bir resim veya özel bir his gerekmiyor."],example:{title:"Emre zor soruyu prova ediyor",text:"Emre mülakatın bittiğini hayal ediyor. Ardından çalışma hayatındaki boşluğu açıklamayı prova ediyor. Donakalırsa notundaki tarihlerden başlamayı planlıyor. Öğle yemeğinden sonra bir yanıtı kaydedip dinliyor. O dönemde ne öğrendiğini söylemediğini fark ediyor, bir cümle ekliyor. Yanıtı hâlâ prova gerektiriyor. Henüz mülakat sonucu yok; elindeki kayıt yalnızca hazırlığını gösteriyor."},instructions:["Sonuç sahnesini kısa tut. Sıradaki işi ve olası bir zorluğu prova et.","Somut hedefini ve bu zorluk çıkarsa ne yapacağını açıkça yaz.","Bugün işi gerçekten dene. Yarın yaptığını, provadan ayrı olarak değerlendir."],action:["Bir mülakat yanıtını prova için kaydet","Hazırladığın bir toplantı önerisini gönder"],minimum:["Tek bir taslak yanıt kaydını sakla","Önerinin bir cümlesini gönder"],cue:["Öğle yemeği bittikten sonra","Toplantıda görüşler sorulduğunda"],place:["Mülakat hazırladığım masada","Ekibin mesaj grubunda"],obstacle:"İlk cümlede donakalıyorum",fallback:["Notumdaki tarihlerden başla","Hazırladığım kısa giriş cümlesini oku"],observation:["Gerçekten kaydettiğim yanıt","Ayrı ayrı kaydettiğim hazırlık ve katkı"],stopRule:"Canlandırma sıkıntını artırıyorsa dur. Sıradan iş notlarını ve gündüz bir fırsatı kullan.",scenario:"Emre başarılı bir mülakatı iki kez hayal etti. Kaydettiği prova yanıtında hâlâ çalışma hayatındaki boşluğu açıklamıyor. Evden çıkmadan önce beş dakikası var.",question:"Canlandırmayı bu eksik için nasıl kullanabilir?",options:[{key:"rehearse",text:"Boşluğu açıklayan ilk cümleyi prova etsin. Bir taslak yanıt kaydedip gereken tarihleri söyleyip söylemediğine baksın.",feedback:"Bu hazırlık, görülen eksiğe yönelir ve dinleyebileceği bir kayıt oluşturur. Canlandırma mülakat sonucunu güvenceye almaz. Buradaki yararlı işlevi, Emre’nin yanıtı söylemeyi denemesine yardım etmektir. Kaydı dinleyince gerekli bilgiyi ekleyip eklemediğini kontrol edebilir."},{key:"outcome",text:"Başarılı mülakat sahnesini daha zengin ayrıntılarla yeniden kursun. Sonra ne kadar öz güven hissettiğini yazsın.",feedback:"Öz güven hissini kaydetmek mümkün. Ama bu his, yanıtlanmamış soruyu yanıtlamaz. Emre’nin kaydında prova gerektiren belirli bir açıklama var. Kalan zamanını bu açıklamayı söyleyip kaydetmeye ayırsın; böylece neyi eksik bıraktığını gerçekten dinleyerek görebilir."},{key:"research",text:"Bu akşam hangi yöntemi deneyeceğine karar vermeden önce, kalan zamanda birkaç canlandırma yöntemini karşılaştırsın.",feedback:"Yöntemleri karşılaştırmak ilgi çekici olabilir. Ama buradaki kanıt, başlamak için önce belirli bir tür seçmesini gerektirmiyor. Emre hangi işi yapmadığını zaten biliyor. Kısa bir deneme, yeni bir yöntem arayışından daha ilgili bilgi sağlayabilir."}],best:"rehearse",takeaway:"Sahne, yapacağın işi göstersin. Prova hazırlanmanı sağlar; işi denediğinde ne olduğunu görürsün.",review:"Provadan sonra hangi işi gerçekten denedin? Deneyince hangi eksik daha görünür oldu?",deeper:[{heading:"Yaygın sonuç sahnesi nasıl kuruluyor?",paragraphs:["1. Gerçekleşmesini istediğin bir olay seç. 2. Rahat bir yere yerleş. 3. İstediğin sonucu gösteren kısa bir sahne hayal et. 4. Sana anlamlı gelen ayrıntılarla o sahnenin içinde olduğunu düşün. 5. İstersen sonra tekrar dön. Bazı uygulayıcılar güçlü duygu veya sonucu zaten elde etmiş olma hissi ister. Bu adımlar bir uygulamanın tarifidir. Kurulan sahnenin, dışarıdaki bir olayı düşünceyle çektiğini göstermez. Hissetmenin yoğunluğu da bu iddiayı doğrulamaz. [manifest-P05]","ODA için sonuç sahnesini kısa tut; yapacağın işe zaman kalsın. Bugünle o sahne arasında hangi işin gelmesi gerektiğini belirle. İşin zorlanacağın kısmını zihninde prova et, ardından deneyeceğin çözümü yaz. Canlı görüntüler oluşturamıyorsan adımları sözle anlatabilirsin. Bu erişilebilir bir seçenektir; her hazırlık biçiminin aynı etkiyi verdiğinin kanıtı değildir. Hayal ettiğin işveren yanıtını gerçek yanıt diye kaydetme. Sahnenin içinde bir teklif duymak, dışarıdaki bir işverenden teklif aldığın anlamına gelmez. Hazırlık ve yanıt ayrı kalsın."]},{heading:"Araştırma tek bir canlandırma türünü üstün göstermiyor",paragraphs:["Pham ve Taylor’un eski sınav çalışmasında, çalışma sürecini hayal etme, istenen notu hayal etme, bunları birleştirme ve kontrol koşulu karşılaştırıldı. Bazı karşılaştırmalar süreç canlandırmasını destekledi. Notla ilgili bulgu, sürecin kontrol grubuna göre güvenilir yararını göstermez. Cole ve arkadaşları daha sonra farklı zihinsel canlandırmaları birleştirip davranışta ortalama yarar buldu; türler arasında fark belirlemedi. Bazı alt gruplar küçüktü. Bir sahnenin her zaman en iyi sonucu vereceğine söz vermek bu kanıtı aşar. Bulgular evrensel bir sıralama sunmuyor. [manifest-T17, manifest-T04]","ODA, senin yapacağın iş için hangi hazırlığın gerektiğini sorar. Hedefini biliyor ama ilk cümleden kaçınıyorsan, başlamayı ve bu engelle karşılaşınca ne yapacağını prova et. Yapılabilir en küçük adımı, başlama işaretini, yeri ve çözümünü kaydet. Bugün işi dene, yarın değerlendir. Yararlı bir prova ile gerçekten yaptığın işi ayrı ayrı yaz. Hazırlık sürüyor ama deneme gelmiyorsa provayı kısalt veya kullanabileceğin başka bir fırsat seç. Bu sahneden denemeye geçiş düzeni ODA uyarlamasıdır. Meta-analizin doğruladığı belirli bir uygulama protokolü değildir; araştırmanın bütününe o anlamı yükleme."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]},{number:11,technique:"55x5 yöntemi",title:"55x5: satırlar doldu, başvuru hâlâ boş mu?",goal:"İsteğe bağlı yazının yanına yapabileceğin bir adım ve değerlendirme koy.",hook:"Elli beş satır yazdın, başvuruya tek cümle eklemedin mi? Sıradaki cümleyi bugün işine yarayacağı yere yaz.",reason:"Asıl işe ayıracağın zamanı azaltmadan yazıya ne kadar zaman verebilirsin?",paragraphs:["55x5 yönteminde, istediğin sonucun olmuş gibi anlatıldığı bir olumlama cümlesini beş gün boyunca günde 55 kez yazarsın. Sonuç seçer, aynı cümleyi tekrar eder ve günlük sayıyı tamamlarsın. Kanıtla desteklenmiyor: bu sayının ya da beş günlük tekrarın sonucu hayatına çekmesi. İdeal geleceği hayal ettiren bazı deneylerde o anki enerji azaldı. Bu, her hayalin veya bu yazma ritüelinin çabayı azalttığını göstermez.","ODA uyarlaması: hoşuna gidiyorsa yazmaya devam et; tekrarlar isteğe bağlı kalsın. Belirli bir hedef ve her gün yapabileceğin tek bir iş seç. Engeli söyle, sonra fark edebileceğin bir an için “Şu olursa şunu yapacağım” planı kur. Daha çok yazmadan bugün işi dene; yarın ne yaptığını değerlendir. Araştırma bu tür somut planları destekliyor, özel tekrar takvimini değil."],example:{title:"Emre başvuruya zaman ayırıyor",text:"Emre “İşe yarayan başvurular hazırlıyorum” yazmayı seviyor, ama 55 satır molasının tamamını alıyor. Birkaç satırla yetinip öğle yemeğinden sonra başvuru için beş dakika ayırıyor. Bir bilgi eksikse işe alım ekibine soracağı soruyu yazacak. Bugün soruyu gönderiyor. Kaydına bu soruyu geçiriyor; başvuru yaptığını veya teklif aldığını yazmıyor."},instructions:["Bir hedef seç; kaç tekrar yapacağına karar vermeden önce asıl iş için zaman ayır.","Fark edebileceğin bir başlama anı seç; bir engel için “Şu olursa şunu yapacağım” de.","Bugünkü işi dene ve yarın ne yaptığını değerlendir; tekrar yapmak isteğe bağlı kalsın."],action:["Eksik bilgiyi soran bir mesaj gönder","Başvurunun bir bölümünü tamamla"],minimum:["İşe alım ekibine bir soru gönder","Tamamlanmış bir bölümü kaydet"],cue:["Öğle yemeği bittikten sonra","İsteğe bağlı yazma çalışmam bitince"],place:["İşe alım ekibine yazdığım e-posta taslağında","Başvuruyu hazırladığım masada"],obstacle:"Tekrarlar elimdeki bütün zamanı alıyor",fallback:["Tekrarı atla, en küçük adımı yap","Defteri açmadan asıl işe zaman ayır"],observation:["Yaptığım iş ve yazmaya ayırdığım süre","Gönderdiğim veya kaydettiğim şey"],stopRule:"Yazmak seni zorluyorsa veya asıl işe ayırabileceğin zamanı tüketiyorsa azalt ya da atla.",scenario:"Emre iki gün boyunca 55 tekrarı tamamladı. İki gün de başvurusuna zaman kalmadı. Bugün yine aynı kısa molası var.",question:"Hangi değişiklik daha işe yarar bir düzeni denemesini sağlar?",options:[{key:"faster",text:"Ritüeli eksiksiz sürdürebilmek için tekrarları daha hızlı yazsın; sonra zaman kalırsa başvuruya başlasın.",feedback:"Daha hızlı yazmak da başvuruya zaman bırakmayabilir. Önceki iki gün, aynı molaya iki işin sığmadığını gösteriyor. Önce yapabileceği işe zaman ayırsın. Sonra kalan süreye ne kadar isteğe bağlı yazı sığacağını seçsin."},{key:"weekend",text:"Beş günlük yazıyı tamamlasın, sonra hafta sonu başvuruya daha uzun bir zaman ayırsın.",feedback:"Hafta sonu uzun bir çalışma mümkün olabilir. Ama bu seçim, kanıtla desteklenmeyen bir tekrar sayısını korumak için asıl işi erteliyor. Bugün zaten küçük bir fırsatı var. Daha çok tekrar eklemeden önce o fırsatı denesin."},{key:"reserve",text:"Başvurunun bir bölümüne beş dakika ayırsın, tekrarları azaltsın veya atlasın; kaydettiği bölüme yarın baksın.",feedback:"Bu seçim, işi engelleyen zaman sorununu değiştiriyor. Yazı kişisel bir tercih olarak kalırken başvuruyu denemek mümkün oluyor. Kaydedilmiş bir bölüm, başvuruyu göndermeye yönelik hazırlıktır. İşverenin teklif verdiği anlamına gelmez."}],best:"reserve",takeaway:"Asıl işe zaman bırak. Tekrar sayısını tamamlamak, hedefin için gereken işi tamamlamak değildir.",review:"Hangi işi denedin? Yazı yazdıktan sonra o iş için ne kadar zaman kaldı?",deeper:[{heading:"Yaygın beş günlük tekrar tarifi",paragraphs:["1. İstediğin bir sonuç seç. 2. Sanki gerçekleşmiş gibi olumlu bir cümle yaz. 3. Günlük bir oturumda bu cümleyi 55 kez kopyala. 4. Aynı oturumu beş gün boyunca tekrarla. 5. Yazarken istediğin sonuca yeniden odaklan. Buradaki kesin tekrar sayısı, yöntemi öneren kişinin kuralıdır; kontrollü araştırmayla belirlenmiş bir uygulama miktarı değildir. Bazı tarifler belirli bir duygu hissetmeni veya dikkatin hiç dağılmamasını da ister. [manifest-P06]","Bu yazma biçimi hoşuna gidiyorsa koruyabilirsin, ama aldığı zamanı hesaba kat. Başlamadan önce bugün hedefin için yapacağın asıl işe ne kadar süre gerektiğini seç. ODA uyarlamasında daha kısa yazabilir veya tekrarları tamamen atlayabilirsin. Bir günü kaçırmak, gelecekteki sonucun iptal olduğu anlamına gelmez. Doldurduğun sayfayı yazı olarak kaydet; kaydettiğin başvuru bölümünü ise başvuru üzerinde yaptığın iş olarak. Bu iki kayıt da işverenin teklif verdiğini söylemez."]},{heading:"Plana yarayan şey tekrar sayısı değil",paragraphs:["Gollwitzer ve Sheeran’ın meta-analizi, farklı işlerde belirli bir durumu hedefe yönelik bir davranışla eşleştiren planları destekliyor. 55 tekrarı veya beş günlük manifest kuralını test etmiyor. Kappes ve Oettingen, ideal geleceğe dair bazı olumlu hayallerden sonra o anki enerjinin azaldığını buldu. Bu kısa deneyler, hoş bir tamamlanma hayalinin hazırlığın yerine geçmesine karşı bir uyarıdır. Her iyimser düşüncenin veya tekrarlanan cümlenin zararlı olduğunu kanıtlamaz. [manifest-T02, manifest-T05]","ODA sayfayı, yapabileceğin bir planı yazmak için kullanır. Hedefini, işin en küçük yararlı parçasını ve onu yapabileceğin fırsatı belirt. Yazı bütün molayı dolduruyorsa önce asıl işi yapmayı planla. Eksik bir bilgi yüzünden bölüm ilerlemiyorsa o bilgiyi sor. Bugün dene, yarın değerlendir: seçtiğin an geldi mi, hangi işi yaptın, geriye ne kaldı? Yazı ve eylemi birleştiren bu düzen bir uyarlamadır. Beş gün sonunda belirli bir sonuç vaat etmez."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"İki bardak yöntemi",title:"İki bardak: istediğin duruma hangi adımla geçeceksin?",goal:"Bardaklardaki yazılardan yola çıkıp yapabileceğin bir iş ve engel için plan seç.",hook:"Bardağa “Başvuruya hazırım” yazdın, portfolyo hâlâ yarım mı? Bugünkü durumunla istediğin durum arasını hangi iş yaklaştırır?",reason:"Elindeki zaman ve imkânlarla istediğin duruma yaklaşmak için ne gerekir?",paragraphs:["İki bardak yönteminde bir bardağa bugünkü durumunu, diğerine istediğin durumu yazarsın. İlkini doldurur, değişimi hayal eder, suyu ikinciye döker ve içersin. Kanıtla desteklenmiyor: suyun niyet taşıması veya boyut değiştirmesi. Hedef koyma araştırmaları belirli hedefleri, izlenecek yolları ve geri bildirimi inceler. Suyu bir bardaktan diğerine dökmeye kuantum açıklaması getirmez.","ODA uyarlaması: bardaklar sembol olarak kalsın; istersen iki daire çiz. İki yazının arasına belirli bir hedef, gerçek bir engel ve “Şu olursa şunu yapacağım” planı ekle. WOOP, istek, sonuç, engel ve plandan oluşur. Araştırmalar bu planlama birleşimini ortalama olarak destekliyor. Bugün aradaki farkı azaltacak bir işi dene. Yarın yaptığın işi, başkalarına da bağlı sonuçlardan ayrı değerlendir."],example:{title:"Ömer aradaki adımı yazıyor",text:"Ömer bardaklara “Portfolyo eksik” ve “Başvuruya hazırım” yazıyor. Aralarına bir not koyuyor: “Öğle yemeğinden sonra bir projenin açıklamasını kaydet.” Projeyi anlatamazsa projedeki temel kararını açıklayacak. Suyu döküyor, sonra açıklamayı yazıyor. Portfolyoya hâlâ bir proje daha eklemesi gerekiyor. Notuna bugün yaptığı işi ve neyin değiştiğini açıkça yazıyor."},instructions:["Bugünkü durumunu ve istediğin hedefi yaz; değişimin yapabileceğin ölçüde olmasına bak.","Aralarına bugünkü işi yaz; engel için “Şu olursa şunu yapacağım” planı ekle.","Aradaki farkı azaltacak işi dene; yarın hangi işi yaptığını değerlendir."],action:["Bir projenin açıklamasını yaz","Bir eğitimin koşulunu sor"],minimum:["Bir kararı anlatan açıklamayı kaydet","Eğitim hakkında bir soru gönder"],cue:["Öğle yemeği bittikten sonra","Bardakları kaldırdığım zaman"],place:["Portfolyo belgemde","Mutfak masasında"],obstacle:"İstediğim durum için daha fazla imkân gerekiyor",fallback:["Erişim imkânını veya daha küçük bir seçeneği sor","Projede verdiğim bir kararı sade anlat"],observation:["Aradaki farkı azaltmak için yaptığım iş","İki durum arasında hâlâ eksik kalanlar"],stopRule:"İstersen çizim kullan. Suyu içme adımını seçersen yalnızca içmeye uygun, güvenli su kullan.",scenario:"Ömer’in istediği durumu anlatan bardağında “Başvuruya hazırım” yazıyor. Portfolyosunda bir proje bitmiş ama açıklaması yok. İkinci proje ise hâlâ tamamlanmamış.",question:"Beş dakikada hangi iş aradaki farkı azaltabilir?",options:[{key:"caption",text:"Bitmiş projenin açıklamasını yazıp kaydetsin; sonra portfolyonun hazır olmasını hâlâ engelleyen eksikleri yazsın.",feedback:"Bu seçim, yapabileceği bir parçayı tamamlıyor ve kalan eksikleri görünür tutuyor. Tek açıklama bütün portfolyoyu hazır hâle getirmez. Ama yarın değerlendirebileceği, hedefe doğru atılmış somut bir adım verir."},{key:"rename",text:"Ritüel sırasında büyük hedefini aklında tutmak için ikinci bardağa “İşe alınmış tasarımcı” yazsın.",feedback:"Büyük hedefi onun için değerli olabilir. Ama bardağın yazısını değiştirmek eksik portfolyoyu ilerletmez. İsteğini korusun ve elindeki beş dakikada yapabileceği küçük işi seçsin. Bugünkü fırsat bu işe yeter."},{key:"schedule",text:"Açıklamaya başlamadan kalan bütün portfolyo işlerini sıralasın; böylece izleyeceği yolun tamamını planlamış olsun.",feedback:"İşleri sıralamak daha sonraki değerlendirmede yararlı olabilir. Bu kısa molada eksik açıklamanın ne olduğu zaten belli. Molanın tamamını yeni hazırlıklara harcamak yerine açıklamayı bitirmek, yapılabilir bir adımı denemesini sağlar."}],best:"caption",takeaway:"İki yazı aradaki farkı göstersin. Elindeki imkânlara uyan bir iş o farkın bir kısmını kapatsın.",review:"Yaptığın iş neyi değiştirdi? Yazdığın iki durum arasında hâlâ hangi eksikler var?",deeper:[{heading:"Yaygın iki bardak ritüeli",paragraphs:["1. İki bardak al; ilkine şu anki durumunu yaz. 2. İkinciye istediğin durumu yaz. 3. İlk bardağı suyla doldur. 4. Suyu ikinci bardağa dökerken istediğin değişimi hayal et. 5. Suyu iç ve istediğin duruma yeniden odaklan. Yöntemi uygulayan bazı kişiler bunu boyutlar arasında geçiş olarak anlatır. Bu metafizik açıklama, incelenen kanıtlarla doğrulanmış değildir. Buradaki adımlar, yaygın bir ritüelin nasıl yapıldığını anlatır. [manifest-P07]","Sembolik su aktarımını koruyabilir, açıklamasını bilimsel gerçek olarak kabul etmeyebilirsin. ODA çalışması için evindeki bardaklar veya çizdiğin iki daire yeterli. Suyu dökmeden iki yazının arasına yapacağın işi ekle. Başkasının henüz vermediği bir kararı kesinleşmiş gibi yazma. Portfolyo açıklamasını hazırlamak senin işin; işe alınmak ise işverenin kararına da bağlı bir sonuç. Suyu içeceksen yalnızca içmeye uygun, güvenli su kullan. Özel bir kap alman veya para harcaman gerekmez."]},{heading:"WOOP ile farkı ve imkânları düşün",paragraphs:["WOOP, bir isteği, istenen sonucu, bugünkü engeli ve planı sıraya koyar. İstenen geleceği mevcut engelle birlikte düşünmeyi “Şu olursa şunu yapacağım” planlarıyla birleştiren meta-analiz, hedefe ulaşmada ortalama olarak mütevazı bir yarar buldu. Sonuçlar değişkendi ve yayın yanlılığına dair işaretler vardı. Bardakları veya suyu test etmedi. Hedef koyma kuramında kararlılık, geri bildirim, beceri ve işin karmaşıklığı da önem taşır. Anlamlı bir hedefin uygulanabilir bir yolu olmalı; araçlara erişmeden veya yol belirlemeden zor bir hedef koymak yetmez. [manifest-T01, manifest-T11]","ODA aradaki adımı açıkça yazmanı ister. Mevcut hedefin için tek bir somut iş seç. Karşılaştığında bir şey yapabileceğin engeli söyle; eksik araç veya para gibi dış koşulları da kontrol et. “Araca erişemezsem kullanabileceğim başka bir seçenek soracağım” diyebilirsin. Böylece bugünkü işin destek istemek olur. En küçük adımı ve başlama anını kaydet, bugün dene, yarın değerlendir. Yardım isteğini, aldığın yardımdan ayrı kaydet. Sembolik bardaklarla bu pratik düzeni birleştirmek bir uyarlamadır; birlikte test edilmiş bir tedavi değildir."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:15,technique:"Şükran günlüğü",title:"Şükran günlüğü: desteği gör, hayal kırıklığını saklama",goal:"Gerçekten değer verdiğin bir şeyi yaz; zorluğu inkâr etmeden yararlı bir adım dene.",hook:"Arkadaşının yardımına teşekkür edip başvurunun reddedilmesine yine de üzülebilirsin. İkisi de günlüğünde yer bulsun.",reason:"Değişmesi gerekeni gizlemeden neye teşekkür edebilir veya değer verebilirsin?",paragraphs:["Şükran günlüğünde değer verdiğin şeyleri yazarsın; çoğu zaman nedenlerini ekler ve yeniden okursun. Bazı manifest tarifleri, gelecekteki bir olay olmuş gibi hayata teşekkür eder. Bulgular karışık: şükran uygulamaları bazı kontrol gruplarına göre iyi oluşta küçük ortalama yararlar gösteriyor. Psikolojik açıdan etkin başka uygulamalara göre üstünlük az. Belirtilerle ilgili bulgular mütevazı; şükran yeterli bir tedavi veya gelecek olayların hayatına çekildiğinin kanıtı değil.","ODA uyarlaması: günlüğün kalsın, ama gerçek bir şeyi anlat. Takdir ettiğin desteğin yanında belirli hedefini ve bir zorluğu yaz. Engel için “Şu olursa şunu yapacağım” de. Bugün bir iş seç. Yardım edene teşekkür etmek veya belirli bir konuda görüş istemek olabilir. Yarın yaptığın işi ve varsa yanıtı değerlendir. Minnettarlık hayal kırıklığını gizlemeyi gerektirmez."],example:{title:"Ayşe iki gerçeği de yazıyor",text:"Ayşe, arkadaşının başvurusuna bakmasına değer verdiğini yazıyor. Ret e-postasını da kaydediyor. Kahvaltıdan sonra hangi giriş cümlesinin düzeltilmesi gerektiğini soruyor. Arkadaşı telefonda konuşamazsa kısa mesaj gönderecek. Arkadaşı bugün cevap veremiyor. Ayşe gönderdiği soruyu ve yaşadığı hayal kırıklığını ayrı ayrı kaydediyor; henüz gelmeyen bir görüşü gelmiş gibi yazmıyor."},instructions:["Gerçekten değer verdiğin bir şeyi ve nedenini yaz; yaşadığın zorluk da görünür kalsın.","Bugünkü yararlı işi seç; olası bir engel için “Şu olursa şunu yapacağım” de.","O işi dene; yarın ne yaptığını ve varsa gelen yanıtı değerlendir."],action:["Belirli bir konuda görüş isteyen mesaj gönder","Birine verdiği somut destek için teşekkür et"],minimum:["Başvuru hakkında tek bir görüş sorusu gönder","Belirli bir yardım için teşekkür mesajı gönder"],cue:["Kahvaltı bittikten sonra","Şükran günlüğündeki yazıyı bitirince"],place:["Mesajlaştığımız yerde","Mutfak masasında"],obstacle:"Yardım eden kişi telefonda konuşamıyor",fallback:["Tek bir kısa görüş sorusu gönder","Bakabilecek başka bir kişiyi seç"],observation:["Gönderdiğim istek ve varsa gelen yanıt","Dürüstçe yazdığım takdir ve zorluk"],stopRule:"Kendini minnettar olmaya zorlama. Sıkıntı sürüyorsa bir günlüğün ötesinde desteği hak ediyorsun.",scenario:"Ayşe arkadaşının desteğine değer veriyor, ama başvurusu reddedildiği için üzgün. Arkadaşı mesajla tek bir somut soruya cevap verebileceğini söyledi.",question:"Bu durumda hangi günlük yazısı ve adım uygun?",options:[{key:"positive",text:"Bugün yalnızca destek gördüğü anları yazsın; ret yanıtını incelemeyi kendini daha minnettar hissettiği zamana bıraksın.",feedback:"Değer verdiği destek yazıda kalabilir. Ama takdir etmek, somut bir sorunu ertelemesini gerektirmez. Arkadaşı bir soruya cevap vermeye hazır. Ayşe reddedilmenin canını acıttığını kabul ederken işe yarayan bir soru da sorabilir."},{key:"both",text:"Desteği ve hayal kırıklığını yazsın; sonra hangi giriş cümlesinin sonraki başvuruyu daha açık kılacağını sorsun.",feedback:"Bu seçim, şükranı yaşanmış bir olaya dayandırıyor ve arkadaşının sunduğu desteği kullanıyor. Gönderdiği mesaj bir istek; henüz görüş almış değil. Yarın varsa gelen yanıtı kaydedip neyi düzelteceğine karar verebilir."},{key:"future",text:"Gelecek iş teklifi gelmiş gibi teşekkür yazsın; görüş istemeden önce bu yazıyı yeniden okusun.",feedback:"Geleceğe dönük bu tarif, yöntemi uygulayanların ritüelidir. Kaynak gösterilen derlemelerde test edilen şükran uygulaması değildir. Bir teklifin geldiğini gösteremez. Gerçek bir desteği takdir etmek ve somut bir soru sormak, günlüğü olan bitene bağlı tutar."}],best:"both",takeaway:"Gerçek olana değer ver. Zorluğu ve atacağın sıradaki yararlı adımı da görünür tut.",review:"Neye değer verdin, hangi işi denedin ve birinden yanıt geldi mi?",deeper:[{heading:"Yaygın şükran günlüğü tarifi",paragraphs:["1. Bir defter veya her zamanki yazma aracını aç. 2. Değer verdiğin bir şeyi söyle. 3. Senin için neden anlamlı olduğunu anlat. 4. İstersen başka bir madde ekle. 5. Seçtiğin bir zamanda yazdığını yeniden oku. Uygulayan bir kişinin kendi anlatısı, nedenleri yazma ve yeniden okuma biçimini tarif ediyor. Manifest uyarlamaları, gelecekte olmasını istediğin bir şey için şimdiden teşekkür etmeyi ekleyebilir. Bu, alınmış bir yardıma değer vermekten farklı bir iddiadır. [manifest-P10]","ODA için sıradan bir ayrıntı yeter: işe yarayan bir cevap, paylaşılan bir araç veya dinlendiğin bir an. Her sorunun karşısına olumlu bir madde bulman gerekmez. Ret yanıtı, erişemediğin bir imkân veya hayal kırıklığı bugün senin için önemliyse, onu takdir ettiğin şeyin yanına yaz. Mevcut hedefine uyan yararlı bir iş seç. Günlük yazısı düşünmeye yarar; birine teşekkür etmek veya istek göndermek ayrı bir iştir. Ne yazmak ne de bir istekte bulunmak yanıtı garanti eder."]},{heading:"Küçük ortalama yararlar, sınırlı karşılaştırmalar",paragraphs:["Davis ve arkadaşları, şükran uygulamalarının bazı kontrol gruplarına göre iyi oluşta küçük ortalama yararlar sağladığını buldu. Şükran, iyi oluş açısından psikolojik olarak etkin diğer uygulamalardan daha iyi sonuç vermedi; kaygıyla ilgili bulgular da kesin değildi. Cregg ve Cheavens, depresyon ve kaygı belirtilerini birlikte değerlendirdiğinde mütevazı ortalama değişimler buldu. Bekleme listesine karşı etkiler, etkin kontrol uygulamalarına karşı etkilerden daha büyüktü. Ayrı kaygı analizinin sonucu kesin değildi. Bu bulgular ideal bir günlük sıklığı, kesin rahatlama veya şükranın yeterli tedavi olduğunu göstermez. Evrene teşekkür ederek gelecekteki olayları gerçekleştirmeyi de test etmez. [manifest-T09, manifest-T10]","ODA buna pratik bir plan ekler, ama onu araştırmada test edilen uygulama diye sunmaz. Hedefini belirli tut, bugünkü engeli söyle ve “Şu olursa şunu yapacağım” planı seç. Yardım eden kişi arayamıyorsa bunun yerine tek bir somut soruyu mesajla gönder. Bugün dene, yarın değerlendir. İsteğini gelen yanıttan ayrı yaz; hayal kırıklığın da kayıtta kalabilsin. Şükran yazısı zorlama geliyorsa atlayabilirsin. Yine de yararlı işi yapabilir veya destek isteyebilirsin."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"Olmuş gibi davranma",title:"Olmuş gibi davran: önce örnek iş, sonra yeni kıyafet",goal:"Olmak istediğin kişi gibi, bütçene uyan tek bir davranış dene.",hook:"Kendini profesyonel hissetmek istiyorsun. Yeni kıyafet almadan önce bir örnek iş hazırlamaya ne dersin?",reason:"Başka ihtiyaçlara ayırdığın parayı harcamadan hangi davranış hedefini yansıtabilir?",paragraphs:["Olmuş gibi davranma yönteminde, istediğin sonuca ulaşmış kişi gibi davranırsın. Buna istediğin kimliği davranışında yaşatmak da denir. O kişiyi seçer, günlük düzenini hayal eder, sonra bazı davranışlarını veya sembollerini benimsersin. Bulgular karışık: belirli hedefler ve geri bildirim performansı destekleyebilir. Sonuç kesinleşmiş gibi davranmanın onu hayatına çektiği gösterilmedi. Manifest inancıyla ilgili anketler bazı maddi risklerle ilişki buldu; inancın bunlara neden olduğunu kanıtlamadı.","ODA uyarlaması: kimliğini prova et, ama yapabileceğin ve bütçene uyan bir davranış seç. Belirli hedefini, engeli ve “Şu olursa şunu yapacağım” planını yaz. Profesyonel biri yararlı bir örnek iş hazırlayabilir veya açık bir soru sorabilir. Bugün tek bir iş yap; yarın değerlendir. Sembol satın almak isteğe bağlıdır. Başka bir kişinin kabul edip etmemesi kendi kararıdır."],example:{title:"Mert istediği işi deniyor",text:"Mert serbest çalışan bir analist olmak istiyor. Pahalı bir ofis sandalyesi almayı düşünüyor, sonra bunun yerine örnek hesap tablosunu düzeltmeyi seçiyor. Öğle yemeğinden sonra bir hesabı kontrol edip açıklama ekliyor. Yazılıma erişemezse kullanabildiği ücretsiz bir araçla çalışacak. Örnek işi daha anlaşılır oldu; henüz bir müşterisi yok."},instructions:["Olmak istediğin kişiyi düşün; onu yansıtan somut ve bütçene uyan bir davranış seç.","Engel için “Şu olursa şunu yapacağım” de; başkalarının kararlarını kendi sözünün dışında tut.","Bugün o davranışı dene; yarın ne yaptığını ve ne harcadığını değerlendir."],action:["Bir örnek işi geliştir","Müşteriye tek bir somut soru sor"],minimum:["Açıklamalı bir örnek hesabı kaydet","Proje hakkında bir açıklama sorusu gönder"],cue:["Öğle yemeği bittikten sonra","Örnek iş dosyasını açtığımda"],place:["İş masamda","Örnek hesap tablomda"],obstacle:"Planladığım araca erişemiyorum",fallback:["Erişebildiğin ücretsiz bir araç kullan","Açıklamayı bir metin dosyasına yaz"],observation:["Ürettiğim iş ve gerçekten harcadığım para","Örnek işte kaydettiğim değişiklik"],stopRule:"Bütçenin sınırlarını koru. Belirsiz bir geliri veya başkasının rızasını kesinleşmiş kabul etme.",scenario:"Mert serbest çalışmak istiyor, ama henüz kesinleşmiş bir müşterisi yok. Ücretli bir araç almak temel ihtiyaçları için ayırdığı parayı harcatacak. Erişebildiği ücretsiz araç ise örnek işi yapmaya yeterli.",question:"Bugün hangi iş, istediği mesleğe en uygun adım olur?",options:[{key:"sample",text:"Elindeki araçla bir örnek işi geliştirsin, değişikliği kaydetsin ve temel ihtiyaçlarına ayırdığı parayı korusun.",feedback:"Bu seçim, istediği kimliği bütçesine uyan bir davranışa ve inceleyebileceği bir sonuca dönüştürüyor. Müşteri kazandığını göstermez, ama Mert’in paylaşabileceği işi geliştirir. Temel ihtiyaçların parası, sonucu belirsiz bir sembole gitmek zorunda değil."},{key:"purchase",text:"Çalışma ortamı olmak istediği profesyonele benzesin diye ücretli aracı şimdi satın alsın.",feedback:"Bir araç, iş onu gerektiriyorsa ve maliyeti bütçeye uyuyorsa yararlı olabilir. Burada ücretsiz araç işi yapabiliyor. Satın almak ise temel ihtiyaçların parasını azaltacak. Kimliğini prova etmek, gelecekte gelir alacağını kanıtlamaz."},{key:"wait",text:"Belirsiz bir sonuca çaba harcamamak için, örnek iş hazırlamadan önce kesinleşmiş bir müşterisi olmasını beklesin.",feedback:"Parayı korumak akıllıca. Ama elindeki imkânlarla küçük bir örnek iş hazırlayabilir. Kesinlik beklemek bu uygun maliyetli denemeyi de engelliyor. Yapabileceği kadar çabaya bir sınır koysun ve örnek işin hangi düzeltmeye ihtiyacı olduğunu incelesin."}],best:"sample",takeaway:"Bütçene uyan davranışı dene. Olmak istediğin kişiyi, harcamayı ve başkalarına bağlı sonuçları ayrı tut.",review:"Hangi davranışı denedin, neye mal oldu ve hangi sonuç gerçekten belli?",deeper:[{heading:"Yaygın kimlik provası tarifi",paragraphs:["1. İstediğin durumu veya olmak istediğin kişiyi seç. 2. O kişinin sıradan bir günü nasıl geçirdiğini hayal et. 3. O hayatla ilişkili davranışlar, eşyalar veya rutinler seç. 4. İstediğin değişim gerçekleşmiş gibi davran. 5. Provanın sana nasıl hissettirdiğine bak; istersen yeniden dene. Yöntemi uygulayan bir kişi, işi kesinleşmiş gibi kıyafet ve valiz hazırladığını anlatıyor. Sonradan aldığı teklif bir kişinin hikâyesidir; kontrollü bir karşılaştırma değildir. [manifest-P11]","ODA rol provasını korur, ama karşılayabileceğin bir davranış ister. Örnek iş hazırlamak, toplantıya gündemle gelmek veya açık bir soru sormak mevcut hedefine uyabilir. Pahalı eşyalara sahip olmak o rolü denemenin koşulu değildir. Başka biri rıza vermiş veya henüz karar vermeyen bir işveren seni işe almış gibi davranma. Olası gelecek, ilerlemek istediğin yönü gösterir. Şimdiden elinde olan bir kaynak değildir; bugünkü imkânların yerine kullanılamaz."]},{heading:"Hedefin geri bildirime ve gerçek imkânlara ihtiyacı var",paragraphs:["Hedef koyma kuramı, belirli ve zorlayıcı hedeflerin kararlılık, geri bildirim, beceri ve işin karmaşıklığı hesaba katıldığında performansı nasıl destekleyebildiğini anlatır. Bir kimliği benimsemenin tek başına istenen sonucu verdiğini göstermez. Dixon ve arkadaşları, manifest inancıyla kişinin kendi bildirdiği bazı maddi riskler ve iflas arasında ilişki buldu. Neden sonuç ilişkisini göstermedi. Özgüven veya kendini başarılı görmek, gelirin gerçekten eline geçmiş olmasıyla aynı şey değildir. [manifest-T11, manifest-T13]","ODA sembolden önce bir davranış seçer. Bugünkü işin somut çıktısını, elindeki zamanı ve araçları söyle. Yazılıma erişememek gibi olası bir engel için ne yapacağını planla; en küçük adım bütçene uysun. Bugün dene, yarın değerlendir. Ürettiğin işi, varsa masrafı ve başkasından gelen yanıtı ayrı yaz. Bir satın alma veya söz verme, başarı zaten gelmiş varsayımına dayanıyorsa yolu yeniden düşün. Kimliği eyleme bağlayan bu düzen bir uyarlamadır. Kaynak gösterilen araştırmalar bunu bir “olmuş gibi davranma” uygulaması olarak test etmedi."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Gelecekteki kendinden mektup",title:"Gelecekteki senden mektup: zor geçen salıyı da yaz",goal:"Gelecekteki senden gelen mektuptan bu hafta yapabileceğin bir iş çıkar.",hook:"Gelecekteki senin hayatı daha sakin. Peki iki işin aynı güne sıkıştığı zor bir salıyı nasıl atlattı?",reason:"Hangi gelecek için bu hafta bütçene uyan bir adım atmak istiyorsun?",paragraphs:["Bu mektupta, gelecekteki senin bugünkü sana yazdığını hayal edersin. Bir gelecek tarihi seçer, hayatı ve değişimleri anlatır, cesaret veren sözler yazar ve yeniden okursun. Bulgular karışık: benzer “olabileceğin en iyi sen” araştırmaları iyi oluşta ve iyimserlikte ortalama yararları destekliyor. Gelecekten mesaj geldiğini veya hedefe kesin ulaşılacağını göstermiyor. Araştırmadaki gelecek hayali, o hayata ulaşmak için çalışmayı da içeriyor.","ODA uyarlaması: mektubun sesi kalsın; çabayı, yardımı ve zor geçen sıradan bir günü de yaz. Belirli hedefini, bugünkü engeli ve “Şu olursa şunu yapacağım” planını söyle. Bugün tek bir iş seç, yapabileceğin bir fırsatı kaydet. Somut planlama araştırmayla destekleniyor; bu mektup ve plan birleşimi bir uyarlama. Yarın gelecek tahmininin çıkıp çıkmadığını değil, kendi denemeni değerlendir."],example:{title:"Ece sıradan günü yazıyor",text:"Ece’nin gelecek mektubu daha düzenli bir iş haftasını anlatıyor. İşler çakıştığında öncelikleri nasıl sorduğunu da yazıyor. Bugün iş e-postalarını açınca hangi işin önce yapılacağını soran bir mesaj gönderiyor. Yöneticisine ulaşamazsa ekip yazışmasını kullanacak. Yanıt hemen gelmiyor. Kaydında bir istek ve henüz çözüme kavuşmamış bir iş yükü var."},instructions:["Gelecekteki senin ağzından yaz; çaba, yardım ve sıradan bir engel de olsun.","Bugünkü işi ve belirli başlama anını seç; yapabileceğin bir “Şu olursa şunu yapacağım” planı ekle.","En küçük adımı dene; yarın gerçekte ne olduğuna dair kaydına bak."],action:["İş önceliği hakkında bir soru gönder","Yapabileceğin bir çalışma zamanı ayır"],minimum:["Durumu netleştirmek için bir soru gönder","Uygun bir çalışma zamanını kesinleştir"],cue:["İş e-postalarımı açtığımda","Akşam yemeği masası toplandıktan sonra"],place:["Ekip yazışmasında","Mutfak masasında"],obstacle:"İhtiyacım olan kişiye ulaşamıyorum",fallback:["Kararlaştırılmış ekip yazışmasını kullan","Çalışma için başka uygun bir zaman seç"],observation:["Gönderdiğim soru ve varsa gelen yanıt","Gerçekten kesinleştirdiğim çalışma zamanı"],stopRule:"Mektup baskı yaratıyorsa daha yakın veya daha az zorlayıcı bir geleceği seç. Ara verebilirsin.",scenario:"Ece’nin gelecek mektubu dengeli bir iş haftası vaat ediyor. Bugün iki acil iş çakışıyor. Yöneticisi, açıklama gereken soruları ekip yazışmasında sorabileceğini söyledi.",question:"Mektuba hangi ayrıntıyı eklemek işe yarar?",options:[{key:"calendar",text:"Bugünkü acil işlerden hangisinin önce yapılacağını sormadan, ideal haftasının eksiksiz takvimini anlatsın.",feedback:"Takvim, daha sonraki seçimlere yol gösterebilir. Ama bu öncelik çatışmasını tek başına çözemez. Ece’nin açıklama isteyebileceği bir yol var. O fırsatı kullansın; henüz cevaplanmayan soruyu da görünür tutsun. Hayal edilen takvim bir yanıtın yerine geçmez."},{key:"certainty",text:"Geleceğe güvenmekle ilgili daha güçlü sözler eklesin; iş yükü gözünde daha hafif görünene kadar beklesin.",feedback:"Cesaret veren sözler iyi gelebilir. Ama başka türlü hissetmeyi beklemek, iki acil işi de aynı anda bekletiyor. Kısa bir açıklama sorusu sorması zaten mümkün. Mektup yanıtı tahmin etmeden bu adımı atmasına yardım etmeli."},{key:"request",text:"Zor günlerde öncelikleri nasıl sorduğunu yazsın; sonra kararlaştırılmış ekip yazışmasından tek bir açıklama sorusu göndersin.",feedback:"Bu seçim, gelecek sahnesine bugünkü engele uyan bir davranış ekliyor. Mesajı göndermek Ece’nin yaptığı iş. Yanıt gelene kadar cevap belli değil. Yarın isteğini değerlendirip sıradaki adımını seçebilir; mektubun gerçekleştiğini varsayması gerekmez."}],best:"request",takeaway:"Gelecekteki senin sesi, bugün yapacağın somut işi ve ihtiyaç duyabileceğin desteği açıkça anlatsın.",review:"Mektuptaki hangi adımı denedin? Hangi yardım veya sonuç hâlâ belli değil?",deeper:[{heading:"Yaygın mektup biçimi",paragraphs:["1. Hayatından gelecekteki bir zaman seç. 2. O zamandaki sen olduğunu hayal et. 3. Bugünkü sana bir mektup yaz. 4. Nelerin değiştiğini ve sıradan hayatının nasıl hissettirdiğini anlat. 5. Cesaret veren sözler veya öğütler ekle, sonra mektubu yeniden oku. Uygulayıcı kaynağı, gelecekten bugüne konuşan bu sesi ve kendine şefkatli yaklaşımı belgeliyor. Tarihler ve hitaplar mektup biçimiyle ilgili seçimlerdir; bilimsel olarak gerekli olduğu gösterilmiş öğeler değildir. [manifest-P12]","ODA’da istediğin geleceği yaz; ama bunu bir mesaj veya tahmin olarak sunma. Sıradan bir zorluğu, gereken çabayı ve isteyebileceğin yardımı ekle. Daha sakin bir iş haftası için daha çok emin hissetmek yerine öncelikleri konuşmak gerekebilir. Gelecekteki yönünü, kursta denediğin işe bağla. Yarın yine aynı gerçek imkânlarla uyanacak kişi için yapılabilir bir adımın altını çiz. Uzak geleceği düşünmek yük geliyorsa daha yakın bir gelecekten yazabilirsin. Mektup baskı yaratmak zorunda değil."]},{heading:"Umut veren yazı bugüne bir yol açsın",paragraphs:["“Olabileceğin en iyi sen” meta-analizi, kontrol gruplarıyla karşılaştırıldığında iyi oluş, iyimserlik ve olumlu duygularda ortalama yararlar buldu. Örneklemler çoğunlukla genç öğrencilerdi. Hiçbir araştırma bütün kalite ölçütlerini karşılamadı. Hayal edilen gelecek, ona ulaşmak için çalıştıktan sonraki hayatı anlatır. Bulgular mektupların dış dünyadaki olayları tahmin ettiğini veya gerçekleştirdiğini göstermiyor. Ayrı olarak, “Şu olursa şunu yapacağım” araştırmaları belirli bir anı yapabileceğin davranışla eşleştirmeyi destekliyor. İki kaynak da bu mektup düzenini aynen test etmedi. [manifest-T08, manifest-T02]","ODA mektubu tek bir adım seçmek için kullanır. Belirli hedefini söyle, bugünkü işe en yakın engeli bul ve “Bu olursa…” diye başlayıp yapabileceğin şeyi yaz. Başlama anını, yeri ve en küçük adımı kaydet. Sonra bugün veya seçtiğin sonraki fırsatta dene. Yarın gerçekte ne olduğuna bak: bir istek, bir iş, bir gecikme veya ara verme olabilir. Diğer kişi yanıt vermediyse cevabı belirsiz bırak. Hayal ettiğin geleceği bugünün kanıtı saymadan sıradaki adımı değiştir."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]},{number:13,technique:"Yastık yöntemi",title:"Yastık yöntemi: notuna sabah yapacağın bir iş ekle",goal:"Yatmadan önce yazdığın dilek notunu koru, uyanıkken yapacağın bir işe bağla.",hook:"Yatarken yine aynı dileği mi düşünüyorsun? Yastığının altındaki notuna yarın yapacağın küçük bir iş ekle.",reason:"Planı gündüz yapmak uykuya daha çok yer bırakır mı?",paragraphs:["Yastık yönteminde yazdığın dileği yastığının altına koyarsın. Yaygın tarif şöyle: Dileğini olmuş gibi yaz, kâğıdı katla, yastığın altına yerleştir. Sonra uyumadan önce cümleyi tekrarla ya da istediğin sonucu hayal et. İncelenen kanıtlar, bu kâğıdın dış dünyada istediğin sonucu sağladığını desteklemiyor. Notta yazan bir dilek, gerçekleştiği doğrulanmış bir olay değildir. [manifest-P08, manifest-T19]","ODA'da notu koruyabilirsin. Yanına açık bir hedef ve karşına çıkabilecek bir engel ekle. Belirli bir durum olunca hangi işi yapacağını da yaz. Bu tür somut planlar araştırmalarla destekleniyor; yatma saatine özgü bir çekim etkisi desteklenmiyor. Bugün yararlı bir iş yap, yarın ne olduğunu değerlendir. Plan yapmak seni uyanık tutuyorsa kalan kısmı gündüze bırak. [manifest-T02, manifest-T19]"],example:{title:"Sabah gönderilecek mesaj",text:"Merve mutfak masasında iş dileğini yazıp bir ilana uygun başvuru gönderiyor. Yastık altına koyduğu nota şunu ekliyor: Kahvaltı bulaşıklarını kaldırınca uygun bir yeni ilanı kontrol edeceğim. Ertesi sabah ilana bakıp başka bir başvuruya başlıyor. Başvuruya daha fazla ayrıntı eklemesi gerekiyor. Merve gönderdiği başvuru ile bitmemiş taslağı ayrı yazıyor; henüz hiçbir işverenden yanıt gelmedi."},instructions:["Notun kalsın; yatağa yerleşmeden önce hedefini ve olası engeli de yaz.","Belirli bir durum olunca ne yapacağını yaz, bugün yararlı bir iş yap.","Yarın denediğin işi değerlendir; yastık ritüeli ile yaptığın işi ayrı tut."],action:["Bir ilana uygun başvuru gönder","Tanıdığına iş imkânı sor"],minimum:["Uygun bir başvuruyu gönder","Belirli bir soru gönder"],cue:["Kahvaltı bulaşıklarını kaldırınca","Bugünkü öğle molasından sonra"],place:["Mutfak masasında","Her zamanki çalışma yerimde"],obstacle:"Yatmadan plan yapınca uykum kaçıyor",fallback:["Yarın öğle molasında plan yap","Gündüz kullanacağın bir not yaz"],observation:["Başvuru gönderildi; yanıt henüz bilinmiyor","Soru gönderildi; yanıt ayrı yazıldı"],stopRule:"Ritüel uykunu geciktiriyorsa dur. Plan yapmayı gündüze bırak; yatarken cümleyi tekrarlaman gerekmiyor.",scenario:"Merve'nin notunda sabah uygun bir ilan hakkında soracağı soru var. Yarın ne zaman soracağı zaten belli. Ama yatarken notu yeniden yazdığı için uykusu kaçıyor.",question:"Bu gece ne yapmalı?",options:[{key:"a",text:"Notu bir kez daha yazıp ilanla ilgili sorunun hâlâ içine sinip sinmediğine yarın karar vermeli.",feedback:"Bir kez daha yazmak, gereken yeni bir ayrıntı eklemeden uykusundan çalıyor. Soruyu ne zaman soracağı zaten belli. Planladığı soruyu koruyabilir, başka bir düzeltme gerekiyorsa onu gündüz yapabilir."},{key:"b",text:"Notu olduğu gibi bırakıp uyumalı, sabah planladığı an gelince açık pozisyon hakkında sorusunu sormalı.",feedback:"Böylece hem uykusunu koruyor hem yapacağı işi unutmuyor. Yarın soruyu gönderip göndermediğini yazabilir. İşverenden gelecek yanıtı ise kendi yaptığı işten ayrı değerlendirmeli; soru göndermek, yanıt almakla aynı şey değil."},{key:"c",text:"Sabah soruyu sormak yerine gündüz daha uzun süre işverenden gelecek yanıtı gözünde canlandırmalı.",feedback:"Uzun uzun plan yapmak için gündüz daha uygun. Ama bu seçim, yapabileceği yararlı bir işin yerine geçiyor. Yanıtı hayal etmek mesajı göndermiyor ve işverenin nasıl karar vereceğini de göstermiyor."}],best:"b",takeaway:"Yastık notun kısa olsun; yapacağın iş için uyanık olduğun bir an seç.",review:"Notu yazdıktan sonra hangi işi denedin? Yatarken plan yapmak uykunu etkiledi mi?",deeper:[{heading:"Yastık yönteminin yaygın tarifi",paragraphs:["1. İstediğin sonucu seç ve sanki şu anda gerçekmiş gibi bir cümle yaz. Örneğin, beklediğin teklifin geldiğini hayal ederek yazabilirsin. Bu, yöntemi anlatan kişinin tarifindeki bir adım. Cümle, doğrulanmış bir haberi değil senin dileğini anlatıyor. Yazdığını kimseyle paylaşmak zorunda değilsin; not sana özel kalabilir. [manifest-P08]","2. Kâğıdı katla ve yastığının altına koy. Rehberde nasıl yazılacağı ve katlanacağı hakkında başka ayrıntılar da var. Bunlar yazarın kendi tarifine ait; dış dünyada sonuç almak için gerekli oldukları gösterilmiş değil. Elinde bulunan sıradan bir not kâğıdı yeterli. [manifest-P08]","3. Yatağa yerleşirken cümleyi oku ya da içinden tekrarla. Bu kısmı seviyorsan dileğin gerçekleşmiş gibi hayal edebilirsin. Ardından uyumana izin ver. Bırakmak için görüntünün çok canlı olması, cümleyi tekrar tekrar söylemen ya da belirli bir duyguyu yakalaman gerekmiyor. [manifest-P08]","4. İstersen başka bir akşam nota tekrar bak. Rehber, insanların kullandığı bir ritüeli anlatıyor; işe yaradığını gösteren kontrollü bir araştırma değil. Uyanıklıkla ilgili beyin devrelerini ele alan derleme de yatarken tutulan dileklerin sorgulayıcı düşünmeyi devre dışı bıraktığını ya da dış dünyada olayları gerçekleştirdiğini göstermiyor. [manifest-P08, manifest-T19]"]},{heading:"Notuna uyanıkken yapacağın bir iş ekle",paragraphs:["Yatağa girmeden önce nota küçük, uygulanabilir bir talimat ekle. Hedefini açıkça yaz; karşına çıkmasını beklediğin engeli ve yapabileceğin işi belirt. İş arıyorsan şöyle olabilir: 'Kahvaltı masası kalkınca uygun bir başvuruyu göndereceğim. Formu anlayamazsam işe alım sorumlusuna belirli bir soru soracağım.' İş teklifi gibi sonucu henüz bilinmeyen şeyleri, senin yapacağın başvurudan ayrı tut. [manifest-T02]","Gollwitzer ve Sheeran'ın birçok araştırmayı bir araya getiren incelemesinde, belirli bir durum olunca ne yapılacağını söyleyen planlar farklı ortamlarda hedefe ulaşmaya ortalama olarak katkı sağladı. İnceleme, yastık altındaki kâğıdı test etmedi; plan yapmanın çaba gereksinimini kaldırdığını da göstermedi. Uyanıklık derlemesi ise birlikte çalışan beyin devrelerini anlatıyor, dilekleri gerçekleştiren bir bilinçaltı yolunu değil. Bunlar birbirinden ayrı iddialar. [manifest-T02, manifest-T19]","Bugün işi denemek ve yarın değerlendirmek, ODA'nın uygulamaya eklediği pratik tercihler. Birlikte test edilmiş bir yatma rutini değiller. Neyi gönderdiğini, sorduğunu ya da tamamladığını yaz; gelen yanıtı ayrıca belirt. Notu düzeltirken uykun kaçıyorsa bırak ve gündüz uygun bir fırsat seç. Yapacağın yararlı iş, ritüeli bitirmiş olmana bağlı değil. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Fısıltı yöntemi",title:"Fısıltı yöntemi: söyleyebileceğin bir isteğin provasını yap",goal:"Hayalindeki konuşmayı, bugün senin yapabileceğin açık ve saygılı bir isteğe dönüştür.",hook:"Mesajına yanıt mı bekliyorsun? Fısıltı ritüelini kullanarak sıradaki adımını sen seçebilirsin.",reason:"Saygılı biçimde dile getirebileceğim bir isteğim var mı?",paragraphs:["Fısıltı yönteminde başka birine bir isteğini söylediğini hayal edersin. Yaygın tarif şöyle: Rahatla, o kişiye yaklaştığını düşün, istediğini üç kez kulağına fısılda ve hayalindeki sahneden ayrıl. İncelenen kanıtlar, bu yolla uzaktaki birinin sana yanıt vermesini sağlayabildiğini desteklemiyor. Karşı tarafın rızası ve koyduğu sınırlar hâlâ geçerli; hayalinde konuşman bunları değiştirmiyor. [manifest-P09]","ODA'da fısıltı sana özel kalabilir. Belirli bir hedef seç ve önündeki engeli yaz. Karşı tarafın hayır diyebilmesine de yer bırakarak saygılı bir isteğin provasını yap. Belirli bir durum olunca ne yapacağını planla, bugün uygun bir istekte bulun ve yarın kendi yaptığını değerlendir. Bu tür planları araştırmalar destekliyor. Başkasının yanıtından emin hissetmen, onun kabul edeceğine dair kanıt değil. [manifest-T02, manifest-T13]"],example:{title:"Üstelemeden sormak",text:"Can öğle molasında bir proje görüşmesi isteğini fısıldadığını hayal ediyor. Sonra bunu gönderebileceği bir cümleye çeviriyor: 'Perşembe günü on dakika konuşabilir miyiz?' İş arkadaşı perşembe günü boş zamanı olmadığını söylüyor. Can mesajı ve hayır yanıtını yazıp gelecek haftanın uygun olup olmadığını soruyor. Can'ın yaptığı ritüel, arkadaşını kabul etmek zorunda bırakmadı."},instructions:["İsteğini kendi başına, saygılı bir cümleyle fısılda; karşı tarafın hayır diyebilmesine yer bırak.","Hedefini, engeli ve ne zaman ne yapacağını yaz; bugün uygun bir istekte bulun.","Yarın ne sorduğuna ve gelen yanıtı nasıl karşıladığına bak."],action:["Kısa bir proje görüşmesi iste","Uygun zamanı öğrenmek için soru gönder"],minimum:["Açık bir görüşme isteği gönder","Konuyla ilgili bir soru sor"],cue:["Bugünkü öğle molasından sonra","Birlikte kararlaştırdığımız görüşme başlayınca"],place:["İş yerindeki masamda","Her zamanki görüşme yerimizde"],obstacle:"Basit bir isteği sürekli yeniden yazıyorum",fallback:["Sade bir istek cümlesi kullan","Kararlaştırdığımız görüşmede sor"],observation:["İstek iletildi; yanıt ayrı yazıldı","Sınır gözetildi; sonraki adım seçildi"],stopRule:"İletişim kurmanı istemediğini söyleyen birine ulaşma. Kendi hayalinde canlandırdığın şey, başka birinin sınırlarını geçersiz kılamaz.",scenario:"Can görüşmek istiyor. İş arkadaşı bu hafta zamanı olmadığını söylemiş, ama gelecek hafta için sorabileceğini belirtmiş. Fısıltı çalışması Can'a güven veriyor.",question:"Elindeki bilgiye göre hangi adım uygun?",options:[{key:"a",text:"Gelecek hafta ne zaman uygun olduğunu bir kez sormalı, sonra tekrar tekrar mesaj atmadan yanıtı kabul etmeli.",feedback:"Arkadaşı gelecek hafta için sorabileceğini söyledi; açık bir soru sormak bu sınırı gözetiyor. Can isteği ve yanıtı ayrı yazabilir. İçinin rahatlaması, arkadaşının zamanı üzerinde söz hakkı olduğu anlamına gelmiyor."},{key:"b",text:"Hayalindeki konuşma tamamlanmış gibi hissettirdiği için arkadaşının bir saat önermesini beklemeli.",feedback:"Beklemeyi seçebilir, ama hayalindeki konuşmada gelecek haftayı gerçekten sormuş olmadı. Arkadaşının önerisi, uygun bir istekte bulunabileceği bir fırsat. Görüşme hâlâ işine yarayacaksa bu fırsatı kullanarak bir kez sorabilir."},{key:"c",text:"Bu haftaki görüşmenin kendisi için ne kadar değerli olduğunu daha içten bir mesajla anlatmalı.",feedback:"Daha içten bir mesaj da arkadaşından, uygun olmadığını söylediği haftayı yeniden düşünmesini istiyor. Daha güçlü duygularını üstelemek için gerekçe yapmamalı. Bunun yerine arkadaşının sunduğu gelecek hafta seçeneği hakkında sorabilir."}],best:"a",takeaway:"İsteğini prova et; karşı taraf kendi yanıtını seçer.",review:"Gerçekte hangi istekte bulundun? Karşı tarafın yanıtını veya koyduğu sınırı nasıl karşıladın?",deeper:[{heading:"Hayalde yapılan konuşmanın yaygın tarifi",paragraphs:["1. Kişiyi ve ondan almak istediğin yanıtı seç. Yöntemi anlatan kişinin tarifinde bu çalışma hayalinde yapılıyor. Bir yanıt seçmek, senin ne istediğini gösterir. Karşı tarafın ne istediğini göstermez ve onunla iletişim kurmana izin verildiği anlamına gelmez. [manifest-P09]","2. Rahatla ve o kişiyi bir yerde hayal et. Yanına yaklaşıp isteğini üç kez kulağına fısıldadığını düşün. Üç tekrar, bu tarifin bir parçası; birini etkilemek için bilimsel olarak belirlenmiş bir miktar değil. Dilersen gözlerini açık tutabilir ya da sahneyi görüntü yerine sözlerle anlatabilirsin; bu senin uyarlaman olur. [manifest-P09]","3. Hayalindeki sahneden ayrıl. Bazı tariflerde kişinin alnını öptüğünü hayal etmek de var. Bu, sahnenin başka bir ayrıntısı; uzaktan etki olduğuna dair kanıt değil. ODA'da çalışmayı kendine sakla ve gerçekten saygılı biçimde söyleyebileceğin bir istek seç. Hayalindeki yakınlığı gerçek kişinin rızası yerine koyma. [manifest-P09]","4. Gerçekte bir istekte bulunmanın uygun olup olmadığına karar ver. Bu anlatı, ritüelin nasıl yapıldığını belgeliyor; telepatiyi ya da birini kontrol edebildiğini göstermiyor. Karşı taraf hayır diyebilir, sessiz kalabilir veya fikrini değiştirebilir. İsteği tekrar tekrar fısıldamak, ona yanıt verme zorunluluğu getirmez. [manifest-P09]"]},{heading:"Konuşmada senin yapacağın kısmı planla",paragraphs:["Hedefin açık olsun: Uygun bir görüşme zamanı sormak, birinin sana hayran olmasını sağlamaktan farklı. Basit bir mesajı tekrar tekrar düzeltip geciktirmek gibi, karşılaştığında bir şey yapabileceğin bir engel seç. Sonra başlama anını belirle: 'Öğle molam bitince uygun zamanını öğrenmek için açık bir soru göndereceğim.' Karşı taraf iletişim istemiyorsa yapacağın iş, bu sınırı gözetmek olabilir. [manifest-T02, manifest-P09]","Belirli bir durum olunca ne yapılacağını planlama araştırmaları, fark edebileceğin bir durumu seçtiğin işe bağlamayı destekliyor. Mesajı alan kişiyi kontrol ettiğini göstermiyor. Dixon ve çalışma arkadaşları üç çevrimiçi anket örnekleminde, manifestasyona inanmak ile özgüven ve bildirilen bazı maddi riskler arasında ilişki buldu. Bu ilişkiler neden sonuç bağı kurmuyor; çalışma fısıltı yöntemini de test etmedi. Emin hissetmek, başka birinin kabulünü ölçmenin yolu değil. [manifest-T02, manifest-T13]","Kendi başına prova yapmak ve ertesi gün değerlendirmek, ODA'nın eklediği uyarlamalar. Bugün uygun bir istekte bulun veya birlikte kararlaştırdığınız fırsatı planına yaz. Yarın gerçekten ne sorduğunu, gelen bir yanıt varsa ne olduğunu ve o yanıtı gözetip gözetmediğini belirt. Sessizlik varsa sonuç hâlâ bilinmiyor. Uygun başka bir adım seçebilir ya da durabilirsin; hayalindeki konuşmayı yapılmış bir konuşma olarak sayma. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:18,technique:"17 saniye odaklanma",title:"17 saniye odaklanma: süre bitince işe başla",goal:"Sevdiğin kısa arayı başlamak için kullan; süreye bilimsel bir özellik yükleme.",hook:"On yedi saniye dolmadan aklın mı dağıldı? Yine de şimdi sıradaki adımı atabilirsin.",reason:"Sayaç başlamama mı yardım ediyor, işi mi geciktiriyor?",paragraphs:["17 saniye yönteminde istediğin şeyi, ona ters düşen bir düşünce olmadan on yedi saniye boyunca aklında tutarsın. Bazı tariflerde on yedi saniyelik dört aralık kullanılır ve toplam altmış sekiz saniye olur. İncelenen kanıtlar bu sürelere özel bir çekim eşiği olduğunu desteklemiyor. Ön uyaranların davranışı nasıl etkilediğini inceleyen hazırlama araştırmaları da bu sayıları ya da bilinçli dilek ritüellerini doğrulamıyor. [manifest-P13, manifest-T16]","ODA'da on yedi saniyeyi sevdiğin bir kısa ara olarak tutabilirsin. Hedefini ve engeli açıkça yaz. Belirli bir durum olunca bugün hangi işi yapacağını planla, yarın da denemeyi değerlendir. Somut planları araştırmalar destekliyor. Düşüncen dağıldı diye süreyi yeniden başlatman gerekmiyor. Sayaç sana ne zaman başlayacağını hatırlatsın; sonuç almanın koşulu olmasın. [manifest-T02, manifest-P13]"],example:{title:"Yarım kalan odaklanma arası",text:"Ayşe öğle yemeğinden önce portfolyosu için on yedi saniyelik sayaç kuruyor. Gelen kargo düşüncesini bölüyor. Sayacı yeniden kurmadan planını uyguluyor: Yemekten sonra uygun bir müşteriye işlerinden bir örnek gönderecek. Müşteri başka bir tarz istediğini söylüyor. Ayşe yeniden odaklanma çalışmasına dönmek yerine gönderdiği mesajı ve aldığı geri bildirimi yazıyor; bunları birbirinden ayrı değerlendiriyor."},instructions:["Hedefini seç; istersen on yedi saniyelik kısa bir ara ver.","Engeli ve ne zaman ne yapacağını yaz; bugün yararlı bir iş yap.","Yarın denediğin işi ve varsa aldığın geri bildirimi birlikte değerlendir."],action:["Uygun bir iş örneği gönder","Bir taslağa geri bildirim iste"],minimum:["Uygun bir örnek gönder","Geri bildirim için belirli bir soru sor"],cue:["Bugünkü öğle yemeğinden sonra","İstersem kurduğum sayaç bitince"],place:["Her zamanki çalışma yerimde","Kütüphanedeki masada"],obstacle:"Dikkatim dağılınca süreyi baştan başlatıyorum",fallback:["Sayacı atla ve örneği gönder","Başlama anını bir nota yaz"],observation:["Örnek gönderildi; yanıt ayrı yazıldı","Soru soruldu; geri bildirim henüz bilinmiyor"],stopRule:"Baştan başlamak işi geciktiriyorsa veya sıkıntı veriyorsa sayacı bırak. İstemediğin düşünceler geldi diye ritüelle düzeltmen gereken bir şey yok.",scenario:"Ayşe'nin hazır örneği müşterinin isteğine uygun. Bir bildirim odaklanma süresini böldü. Toplantıdan önce örneği göndermek için beş dakikası var.",question:"Bu fırsatı en iyi nasıl kullanır?",options:[{key:"a",text:"Bildirimleri kapatıp bir kez daha odaklanmalı, toplantıdan önce yeterli zaman kalırsa örneği göndermeli.",feedback:"Bildirimleri kapatmak sevdiği kısa arayı kolaylaştırabilir. Ama yapabileceği iş zaten belli. Kesintisiz bir süre daha odaklanmayı şart koşarsa şu anda örneği gönderebileceği fırsatı kaçırabilir; işe başlamak için bunu beklemesi gerekmiyor."},{key:"b",text:"Hem odaklanma çalışmasını hem örneği göndermeyi yarın daha uzun, kesintisiz bir zamana bırakmalı.",feedback:"Daha çok zaman isteyen bir iş için ileri bir saat seçilebilir. Burada örnek hazır ve beş dakikası var. Ritüelin yarıda kalması, gönderilecek mesajı da ertelemesini gerektirmiyor; bu süreyi örneği göndermek için kullanabilir."},{key:"c",text:"Hazır örneği şimdi göndermeli, mesajı ve yarıda kalan odaklanma arasını birbirinden ayrı yazmalı.",feedback:"Bu seçim elindeki fırsatı kullanıyor ve olanı açıkça gösteriyor. Örnek gönderildi; odaklanma arası bölündü. Bunlar ayrı olaylar. İkisi de müşterinin nasıl karar vereceğini söylemiyor; o yanıtı ayrıca beklemesi gerekiyor."}],best:"c",takeaway:"Sayaç, işe ne zaman başlayacağını hatırlatsın; başlamadan önce tamamlaman gereken bir koşul olmasın.",review:"Hangi yararlı işi denedin? Sayaç başlamana yardım mı etti, seni mi geciktirdi?",deeper:[{heading:"On yedi saniyelik tarif ne istiyor?",paragraphs:["1. Yaşamak istediğin bir deneyim veya olumlu bir düşünce seç. Esther ve Jerry Hicks aracılığıyla Abraham'a atfedilen öğreti, karşıt bir düşünce olmadan buna odaklanmanı istiyor. Bu açıklama ritüelin nasıl yapıldığını anlatıyor. Araştırmayla sınanmış bir yöntem tarif etmiyor. [manifest-P13]","2. Düşünceyi on yedi saniye aklında tut. Bazı tariflerde dört aralık art arda uygulanır; toplam süre altmış sekiz saniye olur. Tanıdık biçimi korumak istiyorsan sayaç kullanabilirsin. Ama incelenen kanıtlar, bu iki süreden herhangi birinde dileklerin gerçekleşmesini sağlayan özel bir çekim eşiği bulunduğunu göstermiyor. [manifest-P13, manifest-T16]","3. Dikkatinin dağılıp dağılmadığını fark et; bunu geleceğin hakkında bir hükme dönüştürme. ODA'da işe başlamak için süreyi yeniden başlatmak gerekmiyor. Öğretide düşüncelerin gerçekliği değiştirdiği ya da saatlerce çalışmaya denk geldiği söyleniyor. Bunlar burada incelenen araştırmaların bulguları değil. [manifest-P13]","4. Arayı bitir ve sıradaki işini seç. Deneysel hazırlama araştırmaları, belirli koşullarda sunulan uyaranların etkisini inceliyor. Bilinçli olarak süre tutup dilek düşünmekle aynı çalışma değil. Sevdiğin bir süre ritüelinin parçası olarak kalabilir; onu koruman, bu sürenin bilimsel olarak doğrulandığı anlamına gelmez. [manifest-T16, manifest-P13]"]},{heading:"Sürenin sonunu başlama anı yap",paragraphs:["Sayacı kurmadan önce bir iş seç. Portfolyo hedefi için bugün uygun bir iş örneğini göndermek olabilir. Engeli de belirt: Kusursuz odaklandığını hissedene kadar süreyi baştan başlatmak. Sonra şöyle yaz: 'Sayaç bitince, düşüncem dağılmış olsa da hazır örneği göndereceğim.' Sayaç baskı yaratıyorsa ne zaman başlayacağını hatırlatan başka bir işaret seç. [manifest-T02]","Gollwitzer ve Sheeran'ın meta-analizi, belirli bir durum olunca ne yapılacağını söyleyen planları farklı işlerde ortalama olarak destekliyor. Dai ve çalışma arkadaşlarının hazırlama derlemesi genel toplamda ortalama bir etki buldu. Ancak yöntemleri önceden kaydedilmiş çalışmaların sınırlı alt grubunda etkiler daha küçüktü ve istatistiksel olarak kesin sonuca varılamadı. Bu belirsizlik bütün hazırlama etkilerini çürütmüyor. İki derleme de on yedi saniyeyi, altmış sekiz saniyeyi veya istenmeyen düşüncelerin sonuçları engellediği kuralını doğrulamıyor. [manifest-T02, manifest-T16]","ODA'nın kısa ara verip işe başlama sırası bir uyarlama; bu iki araştırmanın uyguladığı yöntem değil. Yarın denediğin işi ve dışarıdan gelen geri bildirimi, ne kadar iyi odaklandığından ayrı yaz. Ara, sana uygun bir başlama anı sağladı mı? Yoksa tekrarlarken işi yapabileceğin zamanı mı tüketti? Gerçekte olanlara bakarak sayacı koruyabilir, süreyi kısaltabilir veya tamamen bırakabilirsin. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Dilek kutusu",title:"Dilek kutusu: bir dilek için bugün adım at",goal:"Dilek kutun kalsın; belirli bir hedef için yapabileceğin bir adım at.",hook:"Kutuna dilek ekleyip duruyor musun? Bugün hangi kart için bir iş yapacaksın?",reason:"Bugün zamanım ve imkânlarım hangi dileğe uygun?",paragraphs:["Dilek kutusunda yazılı dilekleri, resimleri veya senin için anlamlı nesneleri bir kapta saklarsın. Yaygın tarif şöyle: Bir kutu seç, niyetlerini ve yaşamak istediğin duyguları içine ekle. Sonra ara sıra bakıp dileklerin gerçekleştiğini hayal et. İncelenen kanıtlar, bir kabın bu dilekleri gerçekleştirdiğini desteklemiyor. Elindeki bir kutu yeterli; özel bir kutu edinmen gerekmiyor. [manifest-P14]","ODA'da kartları koruyabilirsin. Birini seçip açık bir hedef, bir engel ve o engelle karşılaşınca ne yapacağını yaz. Bugün bir iş yap, yarın gerçekten nasıl denediğini değerlendir. Hedefi engellerle karşılaştırıp ne yapılacağını planlamak araştırmalarla destekleniyor. İlerlemeyi takip etmek de ortalama olarak destek buluyor. Ama bu kutu uyarlaması, bütünüyle test edilmiş bir program değil. [manifest-T01, manifest-T03]"],example:{title:"Kutudan çıkan bir kart",text:"Emre mutfak masasında hafta sonu kursu için yazdığı kartı eski bir ayakkabı kutusuna koyuyor. Engeli yazıyor: Zamanı sınırlı. Sonra kursu düzenleyen kişiyi arayıp farklı katılım seçenekleri olup olmadığını soruyor. Kursta esnek bir seçenek yok. Ertesi gün aramayı yazıp başka bir kurs seçiyor; kutuya daha fazla dilek eklemekle yetinmiyor."},instructions:["Elindeki bir kabı kullan ve açık bir hedef içeren bir kart seç.","Engeli ve o durumda ne yapacağını yaz; bugün yapabileceğin bir iş yap.","Yarın o kartı aç, gerçekte hangi işi denediğini ve ne olduğunu yaz."],action:["Kursa katılım seçeneklerini sor","Program hakkında gereken bir ayrıntıyı öğren"],minimum:["Kurs hakkında belirli bir soru gönder","İşine yarayacak bir bilgi sor"],cue:["Bugünkü kahvaltıdan sonra","Ofisin telefon hattı açılınca"],place:["Mutfak masasında","Sessiz çalışma köşemde"],obstacle:"Kursun saatleri bana uymayabilir",fallback:["Başka bir katılım seçeneği sor","Uygun başka bir yerle iletişim kur"],observation:["Soru gönderildi; saatlerle ilgili yanıt yazıldı","Başka yere ulaşıldı; yanıt henüz bilinmiyor"],stopRule:"Elindeki malzemeleri kullan. Bir seçenek imkânlarını aşıyorsa yapacağın işi değiştir veya ara ver.",scenario:"Emre'nin kurs kartında saatlerin çakışması yazıyor. Kursu düzenleyen kişi bugün sorulara yanıt verebiliyor. Emre'nin kutuya eklemek istediği birkaç yeni resim de var.",question:"Kursun ona uyup uymadığını en iyi hangi adım gösterir?",options:[{key:"a",text:"Kursu düzenleyen kişiye katılım seçeneklerini sormalı, sonra gelen yanıtı kurs kartına yazmalı.",feedback:"Bu adım, yazdığı engeli kontrol etmesini ve gerçekten olanı görmesini sağlıyor. Yanıt, bu kursun uygun olmadığını gösterebilir. Bu da Emre'nin yapabileceği başka bir adımı seçmesine yarayan bir bilgi."},{key:"b",text:"Kutu, istediği deneyimin tamamını anlatsın diye önce yeni resimleri içine eklemeli.",feedback:"Resimler sevdiği ritüelin parçası olarak kalabilir. Ama kursun saatleriyle ilgili soruya yanıt vermiyorlar. Bugün elindeki fırsat, kursa katılmanın mümkün olup olmadığını öğrenmek. Resimleri eklemek bu soruyu sormanın yerine geçmez."},{key:"c",text:"Saatler çakıştığı için bu kurs belirsiz; hemen başka bir kurs seçmeli.",feedback:"Başka bir kurs daha uygun olabilir. Ama kursu düzenleyen kişi bu belirsizliği şimdi açıklığa kavuşturabilir. Emre, hedefini değiştirip değiştirmeyeceğine karar vermeden önce belirli bir soru sorarak işe yarayan bilgi alabilir."}],best:"a",takeaway:"Dilek kartın kalsın; yapabileceğin bir iş ekle ve gerçekte ne olduğunu yaz.",review:"Kartındaki hedef için bugün hangi işi denedin? Yazdığın engel hakkında ne öğrendin?",deeper:[{heading:"Yaygın dilek kutusunu hazırla",paragraphs:["1. Bir kutu veya kap seç. Yöntemi anlatan rehber, kutuyu niyetleri saklayacağın bir yer olarak kullanıyor. ODA'da eski bir ayakkabı kutusu ya da zarf gibi, zaten elinde olan bir şeyi kullanmanı istiyoruz. Özel bir nesne satın almak bu çalışmanın parçası değil. [manifest-P14]","2. Dileklerini kartlara yaz veya onları temsil eden resimler seç. Rehberde her sonucu neden istediğin ve elde edince nasıl hissedeceğin de yazılıyor. İstersen bu kişisel ayrıntıları kendine saklayabilirsin. Sade bir başlık da kartın neyi temsil ettiğini gösterir ve yöntemin biçimini korumaya yeter. [manifest-P14]","3. Kartları veya resimleri kutuya koy. Bu ritüeli seviyorsan arada içindekilere bakıp dileklerini elde ettiğini hayal et. Bunlar yöntemi kendi deneyimiyle anlatan bir kişinin adımları. Kabın dış dünyada bir olay yarattığına dair kanıt değiller. [manifest-P14]","4. Gerçek bir fırsatta üzerinde çalışacağın bir kart seç. Rehberdeki enerji alanı açıklaması, araştırmayla ortaya konmuş bir bulgu değil, bir inanç. Simgesel kutunu koruyabilir, bugün kart için ne yaptığını değiştirebilirsin. [manifest-P14]"]},{heading:"Engeli kartın arkasına yaz",paragraphs:["Dilek veya resim ön yüzde kalsın. Arka yüze hedefini açıkça yaz; beklediğin engeli ve o durumda ne yapacağını ekle. Kurs için şöyle olabilir: 'Kurs ofisinin telefon hattı açılınca katılım seçeneklerini soracağım. Saatler bana uymuyorsa uygun başka bir kurs hakkında bilgi isteyeceğim.' Bugün yapabileceğin bir iş seç. Kart hazırlamak ile gerçekten bilgi sormak farklı işler; kartı yazmış olmayı soru sorulmuş gibi sayma. [manifest-T01]","Zihinsel karşılaştırmayı uygulama planıyla birleştirmek, istediğin sonucu gerçek bir engel ve o engelle karşılaşınca yapacağın işe bağlar. Meta-analizde hedefe ulaşmaya ortalama olarak küçük bir katkı bulundu; sonuçlar değişkendi ve yayın yanlılığı olasılığı vardı. Harkin ve çalışma arkadaşları ilerlemeyi takip etmeye teşvik etmenin ortalama yararını buldu. Bu iki derleme de dilek kutusunu test etmedi. Ertesi gün değerlendirmenin en iyi takvim olduğunu da kanıtlamadı. [manifest-T01, manifest-T03]","ODA'da ertesi gün karta dönmek, yaptığını değerlendireceğin pratik bir zaman sağlar. Gerçekte ne sorduğunu ve ne öğrendiğini yaz. Bir soruyu göndermek, yararlı yanıt almak veya kursa kaydolmakla aynı şey değil. Para, erişim veya zaman yüzünden hedef mümkün değilse onu değiştir. Kutunda yeniden yazılmış bir kart, ara verdiğin bir hedef ya da denediğin hâlde sonuç alamadığın bir iş de bulunabilir. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS: uykuya benzer hâl",title:"SATS: sahneyi bırakıp uyuyabilirsin",goal:"Sakin bir sahne hayal et, uykuyu geciktirmeden yapacağın işin provasını yap.",hook:"Yatarken kusursuz sahneyi tekrar tekrar mı kuruyorsun? Şimdi bırakıp yarın yine yararlı bir adım atabilirsin.",reason:"Bu sahneyi canlandırınca uykuya yeterince zaman kalıyor mu?",paragraphs:["SATS, yani uykuya benzer hâl, rahatlayıp uykun gelmişken dileğinin gerçekleştiği kısa bir sahne hayal etmektir. Uygulayanlar başarıya ulaşıldığını düşündüren bir sahne seçer, kendilerini içindeymiş gibi hayal eder ve gerçekmiş gibi tekrarlar. Bazıları bu sırada uyur. Araştırmanın sonucu: Benzer canlandırma çalışmalarında bulgular karışık; uykuluyken hayal kurmanın dilekleri gerçekleştirmesi desteklenmiyor. Zihinsel canlandırma davranışa ortalama olarak katkı sağlayabilir, ama yatma saatine özel bir üstünlük gösterilmiş değil. [manifest-P15, manifest-T04, manifest-T19]","ODA'da sakin bir sahne hayal edebilirsin. Hedefini ve engeli açıkça yaz; belirli bir durum olunca ne yapacağını planla. Sonra ilk uygulanabilir adımın provasını yap. Bugün bir iş yap, yarın ne olduğunu değerlendir. Sahne kusursuz hissettirmek zorunda değil. Tekrarlamak seni uyanık tutuyorsa dur; uyuyabilmen, ne kadar inandığını gösteren bir sınav değil. [manifest-P15, manifest-T19]"],example:{title:"Süresi sınırlı bir sahne",text:"Ece masasında bir eğitim programı hakkında soru gönderiyor. Yatmadan önce programa katıldığını kısaca hayal ediyor, sonra yarın öğle molasında ücreti sormanın provasını yapıyor. Sahneyi tekrarlayınca uykusu açıldığı için bırakıyor. Ertesi gün soruyor; program onun için fazla pahalı. Gelen ücret yanıtını ayrı yazıp ücretsiz bir seçenek arıyor."},instructions:["Uykuya hazırlanmadan önce hedefini, engeli ve ne zaman ne yapacağını bir nota yaz.","İlk adımın kısa bir provasını yap; bugün yararlı bir iş yap.","Uykuya öncelik ver; yarın gerçekte denediğin işi ve ne olduğunu değerlendir."],action:["Bir programın ücretini sor","Katılım için gereken bir ayrıntıyı öğren"],minimum:["Ücret hakkında belirli bir soru gönder","Katılım imkânı hakkında bir soru sor"],cue:["Bugünkü öğle molasından sonra","Programın ofisi açılınca"],place:["Her zamanki çalışma yerimde","Mutfak masasında"],obstacle:"Hayal kurarken uykum kaçıyor",fallback:["Gündüz sözlerle prova yap","Hayal kurmadan doğrudan sor"],observation:["Soru soruldu; yanıt ayrı yazıldı","Uykunun kaçtığı fark edildi; hayal bırakıldı"],stopRule:"Canlandırma uykunu açıyorsa veya sıkıntını artırıyorsa dur. Gündüz prova yapabilir ya da canlandırmayı atlayabilirsin; uykunu koru.",scenario:"Ece'nin gündüz ücreti sormak için açık bir planı var. Tekrarladığı SATS sahnesi onu uyanık tutuyor. Üstelik sahne hâlâ tam olarak gerçekmiş gibi hissettirmiyor.",question:"Şimdi hangi seçimi yapmalı?",options:[{key:"a",text:"Sahneyi basitleştirip yeterince inandırıcı gelene ve bırakabileceğini hissedene kadar tekrar etmeli.",feedback:"Sahneyi basitleştirmek gündüz yapılan bir provaya uygun olabilir. Ama sahnenin inandırıcı gelmesi, durmanın şartı değil. Tekrarlar onu uyanık tutuyor; devam etmek, ritüeli uykunun önüne koyuyor. Sahneyi bırakmak için bu hissi beklememeli."},{key:"b",text:"Sahneyi bırakıp uyumalı, gündüz planladığı an gelince programın ücretini sormalı.",feedback:"Ne zaman ne yapacağı zaten belli. Sahneyi bırakmak, hedeften vazgeçmeden uykusunu korumasını sağlıyor. Yarın sorduğu soruyu ve ücret hakkında aldığı bilgiyi yazabilir; bu işi yapabilmek için sahneyi tamamlaması gerekmiyor."},{key:"c",text:"Ücreti sormak yerine gündüz daha kolay yöneteceği, daha uzun bir SATS çalışması yapmalı.",feedback:"İsteğe bağlı canlandırma için gündüz daha uygun olabilir. Ama daha uzun bir sahne de ücret sorusuna yanıt vermiyor. Gerçek soruyu sorma planı kalsın; yapacağı bir prova varsa onu bu işe hazırlık olarak görsün."}],best:"b",takeaway:"Kısa sahnenin kusursuz gelmesini beklemeden bırakabilirsin; gerçekte hangi işi denediğini hayal ettiğinden ayrı yaz ve değerlendir.",review:"Gerçekte hangi işi yapmayı denedin? Sahneyi canlandırmak sana uyumak için yeterince zaman bıraktı mı?",deeper:[{heading:"SATS öğretisindeki sahne",paragraphs:["1. Bir sonuç ve bu sonucun gerçekleştiğini düşündüren kısa bir sahne seç. Neville Goddard'ın derslerinde, kendine dışarıdan bakmak yerine dileğinin gerçekleştiği sahnenin içinde yer almak anlatılıyor. Bu, öğretmenin yönteminin bir parçası. Dış dünyadaki olayları değiştirmenin kanıtlanmış bir yolu değil. [manifest-P15]","2. Rahatça otur veya uzan. İstersen gözlerini kapat, gevşe ve uykunun gelmesine izin ver. Kaynak, bu hâli uygulamanın bir parçası olarak görüyor. ODA'da gözlerin açık kalabilir veya sahneyi sözlerle anlatabilirsin. Uykunu zorla getirmeye çalışman istenmiyor. [manifest-P15]","3. Kısa sahneyi gerçekmiş gibi hayal ederek tekrarla. Bazı tariflerde bu duygu içindeyken uykuya dalınır; bazılarında hafifçe dikkatini vermeye devam edersin. Sahne inandırıcı gelmeden önce de bırakabilirsin. Hayalinde belirlediğin bir ölçüyü tutturmak için kendini uyanık tutma. [manifest-P15]","4. Metafizik iddiaları tariften ayrı tut. Uyanıklık üzerine derleme, birbiriyle etkileşen uyku ve uyanıklık devrelerini anlatıyor. Uykulu hâlin dilekleri gerçeğe dönüştürdüğüne dair kanıt sunmuyor. Goddard'ın hiçbir iş yapmaya gerek olmadığı yönündeki öğretisi de zihinsel canlandırma araştırmalarının sonucu değil. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Uykunu koruyarak bir adımın provasını yap",paragraphs:["Uykuya hazırlanmadan önce belirli bir hedef seç ve engeli yaz. Eğitim programında hedefin, ücretin imkânlarına uyup uymadığını öğrenmek olabilir. Gerçekte soracağın sorunun kısa bir provasını yap. Yanıt, programın sana uygun olmadığını gösterirse ne yapacağını da düşün. Bu, ODA'nın pratik uyarlaması; Goddard'ın tarif ettiği duyguyu veya sahneyi aynen kurman gerekmiyor. [manifest-P15, manifest-T04]","Cole ve çalışma arkadaşlarının araştırmaları birleştiren incelemesinde, zihinsel canlandırma farklı çalışmalarda davranışa ortalama olarak katkı sağladı. Katılımcıların çoğu öğrenciydi. Canlandırma türleri arasında güvenilir bir sıralama veya yatma saatine özel bir üstünlük gösterilmedi. Uyanıklık derlemesi de uykulu olmanın düşünceyi devre dışı bıraktığını ya da dış dünyada sonuç yarattığını göstermiyor. Genel canlandırma bulguları, SATS hakkındaki her iddiayı doğrulayamaz. [manifest-T04, manifest-T19]","Gerçek soruyu sormak için gündüz bir başlama anı seç. Uygunsa bugün yararlı bir bilgi sor. Yarın soruyu ve gelen yanıtı, hayal ettiğin sahneden ayrı yaz. Sahne uykunu açıyorsa dur; gündüz prova yapmayı veya canlandırmayı bırakmayı seç. Sahneyi yarım bıraksan da sıradaki iş planında kalabilir. Bu adımların tamamı, bir SATS uygulaması olarak birlikte test edilmiş değil. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],n=d.sort((a,e)=>a.number-e.number).map(t),m=[...r,{id:"M01",title:"Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve “şu olursa bunu yaparım” planları",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makaleden 24 bağımsız etki, 15.907 katılımcı: hedefe ulaşmada mütevazı ortalama yarar, g = 0,336 [0,229, 0,443]. Yayın yanlılığı düzeltmesiyle tahmin 0,242 [0,143, 0,342] oldu.",limitation:"Sonuçlar oldukça farklıydı, yayın yanlılığı işaretleri vardı. Bu kurs ve kısa alıştırmaları sınanmadı. Sonuçlar garanti değil."},{id:"M02",title:"Gollwitzer ve Sheeran · 2006 · Belirli planlar ve hedefe ulaşma",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 bağımsız test, 8.461 katılımcı: belirli “şu olursa bunu yaparım” planları hedefe ulaşmaya ortalama destek verdi, d = 0,65 [0,60, 0,70].",limitation:"Farklı yöntemlerle yapılmış, eski tarihli çalışmalar. Hepsi önceden kayıt altına alınmış değildi. Planlar çabayı, hatırlamayı, somut kısıtları veya belirsizliği ortadan kaldırmaz."},{id:"M03",title:"Harkin ve arkadaşları · 2016 · Hedefte ilerlemeyi izlemek",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 deneyde toplam 19.951 katılımcı vardı. Hedefe ulaşma analizinde 18.398 kişi: d = 0,40 [0,32, 0,48]. Küçük çalışmalar için duyarlılık düzeltmesi 0,19 [0,10, 0,28] tahmini verdi.",limitation:"Hedefler ve uygulamalar farklıydı. Çalışmaların özellikleriyle etki büyüklükleri arasındaki ilişkiler, herkese açık paylaşımın gerekli olduğunu göstermez. Bu kayıt biçimi, değerlendirme zamanı veya ODA kursu doğrulanmadı."},{id:"M04",title:"Cole ve arkadaşları · 2021 · Zihinde canlandırma ve davranış değişikliği",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 çalışma, 123 etki, 5.685 katılımcı: zihinde canlandırmanın genel etkisi g = 0,49 [0,37, 0,62]. Türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı.",limitation:"Çoğunlukla öğrencilerle, farklı canlandırmalar incelendi. Yalnızca süreç canlandırması beş etki içeriyordu; tahmin kesin değildi. Güvenilir bir tür sıralaması veya bu kısa alıştırmanın doğrulaması yok."},{id:"M07",title:"Dixon, Hornsey ve Hartley · 2025, çevrim içi 2023 · Manifestasyon inancı",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Üç ABD çevrim içi anketi, 1.023 katılımcı: manifestasyon inancı bazı mali risk bildirimleri ve bildirilen iflasla ilişkiliydi. Bildirilen gelir veya eğitimle ilişki bulunmadı.",limitation:"İlişki neden-sonucu göstermez, her manifestasyon tekniğini nesnel olarak sınamaz. Kişinin bildirdiği mali sonuçlar, tek bir kişinin geleceği için tahmin değildir."},{id:"M10",title:"Gollwitzer ve Brandstätter · 1997 · Belirli bir başlama fırsatı seçmek",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"İkinci çalışmada 86 öğrenciden rapor yazmaları istendi. Raporunu geri veren, kimliği belirlenebilen 36 kişi içinde, plan yapan 17 kişiden 12’si, kontrollerde 19 kişiden altısı iki gün içinde yazdı.",limitation:"%71 ile %32 karşılaştırması araştırmaya alınan herkesi değil, raporu geri verenleri kapsar. Planlama toplam katılımı artırmadı. Dar bir öğrenci işi; ODA kursu doğrulanmadı."},{id:"M11",title:"Oettingen ve arkadaşları · 2015 · Planlama ve takvime saat yazmak",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Birinci çalışmada 84 lisans öğrencisi analiz edildi. Önceden planlanan karşılaştırma, planlanan saatlerde zihinsel karşılaştırma ve “şu olursa bunu yaparım” planları lehineydi: p = 0,03. Genel karşılaştırma p = 0,057.",limitation:"Tamamlanan iş veya üretkenlik değil, takvime saat yazma ölçüldü. Eksik yanıtlar dışlandı. Kursun kısa uyarlaması ve koşulların uygunluğunu ayırma biçimi sınanmadı."},{id:"M14",title:"NIMH · Ruh sağlığı sorunlarında yardım almak",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Resmî rehber, sıkıntı, günlük hayatta aksama veya acil tehlike için uzman ve kriz desteği yollarını anlatır.",limitation:"Bir rehber, etkililik deneyi değil. ODA ruhsal hastalığa tanı koymaz, tedavi etmez. ABD dışında yerel sağlık ve acil yardım hizmetlerini kullan."},{id:"manifest-positive-fantasies",title:"Kappes ve Oettingen · 2011 · İdealleştirilmiş olumlu hayaller",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Çoğunlukla öğrencilerle yapılan dört deneyde bazı idealleştirilmiş olumlu hayallerden sonra anlık enerji daha düşüktü. Üçüncü çalışma olumlu hayalleri sorgulayanlarla değil, nötr veya yönlendirilmemiş hayallerle karşılaştırdı.",limitation:"Küçük, kısa deneylerdir. Bütün iyimserlik veya hayal kurma zararlı değildir. Tekrarlanan hayal döngüsü veya beynin hedefi tamamlanmış saydığı bir sinyal ölçülmedi."},{id:"manifest-belief-study",title:"Dixon, Hornsey ve Hartley · 2025, çevrim içi 2023 · Manifestasyon inancı",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Toplam 1.023 kişilik üç ABD çevrim içi anketinde manifestasyon inancı, kendine güvenle ve iflas dahil bazı mali risk bildirimleriyle ilişkiliydi. Bildirilen gelir veya eğitimle ilişki yoktu.",limitation:"İlişkiler neden-sonucu göstermez, her tekniği nesnel olarak sınamaz. Kişilerin bildirdiği sonuçlar, tek bir kişinin geleceği için tahmin değildir."},{id:"manifest-murphy",title:"Joseph Murphy · Bilinçaltının Gücü · Yayıncının kitap tanıtımı",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Yayıncı, Murphy’nin popüler kişisel gelişim kitabını ve hayal gücüyle inanç hakkındaki öğretilerini tanımlar.",limitation:"Yayıncı özeti, kontrollü çalışma değil. Yatma ritüelinin tam metni doğrulanmadı. Burada para çekmeye, iyileşmeye veya yatma vaktinin öğrenmede özel üstünlüğüne kanıt yok."}],s={id:"manifest",title:"Hayalin yerinde sayıyor mu? Bugün bir adım at",subtitle:"Beş temel dersin ardından 15 yaygın teknik: araştırmanın söylediği ve bugün yapabileceğin bir iş.",description:"Seçtiğin bir isteği somut işe dönüştür. Teknik kütüphanesinde de aynı denemeyi sürdür: uygulamaları öğren, araştırmanın sınırına bak ve yapabileceğin bir adım dene.",lessonLibrary:{id:"manifest-technique-library",title:"Teknik kütüphanesi",description:"15 tanıdık uygulama. Nasıl yapıldıklarını, araştırmanın neyi desteklediğini ve iş yapıp sonucu değerlendirdiğin ODA uyarlamasını öğren.",lessonIds:n.map(a=>a.id),sourceIds:r.map(a=>a.id)},scope:"Burada manifestasyon, niyetini hazırlık ve davranışla hayata geçirme çalışmasıdır. Düşüncelerin kuantum etkileriyle olayları yönettiği, evrenin odaklandığın şeyi getirdiği veya her isteğin kesin gerçekleşeceği iddia edilmez. Bu kurs mali, tıbbi veya psikolojik danışmanlık değildir.",outcome:"Anlamlı tek hedef, kullanabileceğin en küçük adım, dürüst deneme kayıtları ve gelecek haftaya uyan bir plan.",photo:{id:"1676782778930-11b311ec5134",alt:"Çimenli tepeden uzak dağlara doğru yükselen toprak yol"},lessons:[{id:"manifest-1",v2:{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"tr",title:"Hayalin bekliyor mu? Bugün işe yarayan bir şey yap",goal:"Seçtiğin hedef için kullanabileceğin küçük bir iş çıkar.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Yine bir hafta geçti, istediğin hayat hâlâ uzakta mı? Bir isteğin için bugün somut bir iş yap.",reason:{id:"manifest-1-reason",label:"Bu kimin hedefi? Zaman ayırmana gerçekten değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Benim hedefim; akşam telefona bakmak bekleyebilir","Ailemin önceliği; metni cilalamak bekleyebilir","Başkasının hedefi; ayıracağım zamanı yeniden düşünmeliyim","Bu hedefi kimin için istediğimden emin değilim"]},why:{id:"manifest-1-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Daha iyi bir iş bulmak sonuçtur. Öz geçmişindeki bir cümleyi düzeltmek ise yapabileceğin bir iştir. Seni arayıp aramamaya yine başkaları karar verir. Yapmaya değer bir iş seç. Emeğini, onların yanıtına göre ölçmek zorunda değilsin.","Öğrencilerle yapılan bir deneyde başlama zamanını ve yerini seçmek, raporunu geri verenler arasında zamanında yazmayı artırdı. Toplam katılımı artırmadı. Plan başlamak için destek olabilir, sonucu garanti etmez. Bugün kullanabileceğin bir cümle yaz, soruyu yanıtla veya bir şey iste. Kurs boyunca aynı hedefi koru. Sonra gerçekte ne olduğunu anlatmak için dön."],example:{title:"Emre işe başlıyor",text:"Akşam yemeğinden sonra Emre mutfak masasında lojistik işi hedefi için on dakika ayırıyor. Öz geçmişindeki bir cümleyi, depodaki sekiz vardiyanın planını nasıl yaptığını anlatacak biçimde düzeltiyor. Cümle hâlâ içine sinmiyor. Yine de taslağı saklayıp neyi değiştirdiğini kaydediyor. Hiçbir işveren henüz metni görmedi. Yarın üzerinde çalışabileceği gerçek bir taslak var."}},move:{invitation:"Kendi işine yarayan adımı belirt. Öneriler, Emre’nin öz geçmişinden uyarlayabileceğin örnekler.",instructions:["Kaydetmeden önce hangi belgeyi, soruyu veya nesneyi değiştireceğini belirt.","En küçük adımı yap. Dışarıdan gelen yanıtı, yaptığın işten ayrı kaydet."],prompts:[],suggestions:{action:["Öz geçmişte vardiya planını anlatan cümleyi düzelt","Öz geçmişi okuyana hangi ayrıntının eksik olduğunu sor","Vardiya dağılımını gösteren bir iş örneği hazırla"],minimum:["Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet","Eksik öz geçmiş ayrıntısını soran mesajı gönder","Vardiya dağılımını gösteren iş örneğini kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Akşam yemeğinin sofrası toplandıktan sonra","Öğle yemeği bitince","Sabah içeceğimi içtikten sonra"],place:["Mutfak masamda","Kütüphanedeki çalışma masasında","Öz geçmiş belgemde"],minutes:[10,2,5],fallback:["Bir vardiya değişikliğini sade bir cümleyle yaz","Uygun başka bir fırsat seç ve belirt","Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor"],observation:["Kaydettiğim öz geçmiş cümlesi","Öz geçmiş sorusunu gönderip göndermediğim","En küçük adımı neyin engellediği"]},suggested:{action:"Öz geçmişte vardiya planını anlatan cümleyi düzelt",minimum:"Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet",minutes:10,cueHint:"Akşam yemeğinin sofrası toplandıktan sonra",placeHint:"Mutfak masamda",obstacleHint:"Ayırabildiğim süre planladığımdan daha kısa",fallbackHint:"Bir vardiya değişikliğini sade bir cümleyle yaz",observationHint:"Kaydettiğim öz geçmiş cümlesi"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Güvenli olmayan veya maddi gücünü aşan adımlara ara ver. Bunun yerine somut destek seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Emre kendisine uygun bir iş ilanı bulmuş. Akşam yemeğine on dakika var. Öz geçmişi, ilanda istenen vardiya planlama deneyimini anlatmıyor.",question:"İlk denemede hangi adım daha işe yarar?",options:[{id:"manifest-1-research-more",text:"İşin istediği hayata gerçekten uyup uymadığını anlamak için başka ilanlara da bakmak.",feedback:"İlan karşılaştırmak hedefini netleştirebilir. Ama bu iş zaten uygun. Eksik olan, Emre’nin deneyimini işe yarar biçimde anlatan bir cümle. Elindeki zamanı o cümleyi düzeltmek için kullan."},{id:"manifest-1-improve-line",text:"Bu ilana uygun bir öz geçmiş cümlesi yazmak, taslağı saklamak ve eksikleri not etmek.",feedback:"Bu seçim, on dakikaya sığan ve Emre’nin kullanabileceği bir iş çıkarır. Taslağa yorum gerekebilir, işveren yanıt vermeyebilir. Bunların hiçbiri yaptığı işi ortadan kaldırmaz."},{id:"manifest-1-clarify-future",text:"Öz geçmişine ne yazacağını seçmeden önce ideal çalışma gününü ayrıntılarıyla anlatmak.",feedback:"İstediği çalışma gününü anlatmak sonraki seçimlere yön verebilir. Emre uygun işi zaten seçmiş. Daha çok anlatmak bu somut eksiği erteler. Önce cümleyi yaz, sonra ne gerektiğine bak."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"İsteğin için bugün işe yarayan bir adım at. Gerçekte yaptığını, beklediğin yanıttan ayrı kaydet.",followUp:{questionId:"manifest-1-return",question:"Kaydettiğin denemeden sonra elinde kullanabileceğin hangi iş var?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Başlama planı neye yardım edebilir?",paragraphs:["Gollwitzer ve Brandstätter’in 1997 tarihli ikinci deneyinde Münih’teki 86 öğrenciye Noel hakkında rapor yazma işi verildi. Plan yapanlar kesin bir zaman ve yer seçti. O fırsatı gözlerinde canlandırdı, başlamaya karar verdi ve seçimlerini yazdı. Raporunu geri veren, kimliği belirlenebilen 36 kişinin içinde plan yapan 17 kişiden 12’si, kontrol grubundaki 19 kişiden altısı istenen iki günde yazdı. Bu oranlar araştırmaya alınan herkesi değil, raporunu geri verenleri anlatır. Plan yapmak toplam katılımı artırmadı. [M10]","Ders, belirli bir başlama fırsatı seçme fikrini alıyor. Ardından o anda kullanabileceğin bir iş yapmanı istiyor. Bu genel uyarlama, Noel raporu deneyinde sınanmadı. Yalnızca bir tarih seçmek, o gün zamanı nereden bulacağını söylemez. Fark edebileceğin bir olayı ve ulaşabileceğin bir yeri seç. Gerekli araç veya kaynak yoksa onu istemek bugünkü adımın olabilir. Yardım henüz gelmese de yaptığın isteği kaydet. İsteğin gönderilmesi, yardımın alınması veya işin bitmesiyle aynı sonuç değil."]},{heading:"İsteklerin başkalarının kararını yönetmez",paragraphs:["Wang ve arkadaşlarının 2021 derlemesi, 15.907 katılımcı içeren 21 makaleden 24 bağımsız etkiyi birleştirdi. İstenen sonucu bir engel ve “şu olursa bunu yapacağım” planıyla ele almak, hedefe ulaşmada mütevazı bir ortalama yarar gösterdi. Etki g = 0,336, %95 güven aralığı 0,229 ile 0,443 arasındaydı. Bulgular oldukça farklıydı. Yayın yanlılığı için yapılan düzeltme tahmini küçülttü. Bu bulgu, sınırları olan planlamayı destekler. Kursun sana sonuç vereceğine söz vermez. [M01]","Dixon ve arkadaşları, toplam 1.023 kişinin katıldığı üç ABD çevrim içi anketinde manifestasyon inancını inceledi. Bu inanç, bildirilen bazı mali risklerle ve iflas bildirimleriyle ilişkiliydi. Bildirilen gelir veya eğitimle ilişki bulunmadı. Bu ilişkiler, inancın iflasa neden olduğunu göstermez. Her manifestasyon alıştırmasını nesnel olarak sınamaz. [M07] İsteğini yapacağın işi seçmek ve koşullara bakmak için kullan. Düşüncelerinin fırsatları çektiği, sıkıntıya neden olduğu veya bir sonucu hak ettirdiği sonucunu çıkarma. Para, bakım ihtiyaçları, erişim ve başkalarının kararları yine önem taşır."]}],sourceIds:["M10","M01","M07"]}},photo:{id:"1768055104910-8c8d213835fb",alt:"Deftere yapılacaklar listesi yazan el"},schemaVersion:2,title:"Hayalin bekliyor mu? Bugün işe yarayan bir şey yap",minutes:6,goal:"Seçtiğin hedef için kullanabileceğin küçük bir iş çıkar.",reading:["Daha iyi bir iş bulmak sonuçtur. Öz geçmişindeki bir cümleyi düzeltmek ise yapabileceğin bir iştir. Seni arayıp aramamaya yine başkaları karar verir. Yapmaya değer bir iş seç. Emeğini, onların yanıtına göre ölçmek zorunda değilsin.","Öğrencilerle yapılan bir deneyde başlama zamanını ve yerini seçmek, raporunu geri verenler arasında zamanında yazmayı artırdı. Toplam katılımı artırmadı. Plan başlamak için destek olabilir, sonucu garanti etmez. Bugün kullanabileceğin bir cümle yaz, soruyu yanıtla veya bir şey iste. Kurs boyunca aynı hedefi koru. Sonra gerçekte ne olduğunu anlatmak için dön."],practice:["Senin için önemli bir isteği tek cümleyle yaz veya düşün.","Seni o isteğe yaklaştıran ve senin seçebileceğin bir davranış belirle.","İşi küçük bir bitişle anlat. Örneğin “taslağın üç cümlesini yazmak”."],reflection:"Bugün isteğin için yapabileceğin davranış ne?",question:"Hangisini doğrudan yapmayı seçebilirsin?",options:["İşverenin kesin beni seçmesi.","Yarın öz geçmişimin üç cümlesini düzenlemek.","Hiçbir şeyin ters gitmemesi."],correct:1,feedback:"Başkalarının kararını garanti edemezsin. Kendi hazırlığını somut bir işe dönüştürebilirsin.",takeaway:"İsteğin için bugün işe yarayan bir adım at. Gerçekte yaptığını, beklediğin yanıttan ayrı kaydet.",sources:["M10","M01","M07"],deeper:[{heading:"Başlama planı neye yardım edebilir?",paragraphs:["Gollwitzer ve Brandstätter’in 1997 tarihli ikinci deneyinde Münih’teki 86 öğrenciye Noel hakkında rapor yazma işi verildi. Plan yapanlar kesin bir zaman ve yer seçti. O fırsatı gözlerinde canlandırdı, başlamaya karar verdi ve seçimlerini yazdı. Raporunu geri veren, kimliği belirlenebilen 36 kişinin içinde plan yapan 17 kişiden 12’si, kontrol grubundaki 19 kişiden altısı istenen iki günde yazdı. Bu oranlar araştırmaya alınan herkesi değil, raporunu geri verenleri anlatır. Plan yapmak toplam katılımı artırmadı. [M10]","Ders, belirli bir başlama fırsatı seçme fikrini alıyor. Ardından o anda kullanabileceğin bir iş yapmanı istiyor. Bu genel uyarlama, Noel raporu deneyinde sınanmadı. Yalnızca bir tarih seçmek, o gün zamanı nereden bulacağını söylemez. Fark edebileceğin bir olayı ve ulaşabileceğin bir yeri seç. Gerekli araç veya kaynak yoksa onu istemek bugünkü adımın olabilir. Yardım henüz gelmese de yaptığın isteği kaydet. İsteğin gönderilmesi, yardımın alınması veya işin bitmesiyle aynı sonuç değil."]},{heading:"İsteklerin başkalarının kararını yönetmez",paragraphs:["Wang ve arkadaşlarının 2021 derlemesi, 15.907 katılımcı içeren 21 makaleden 24 bağımsız etkiyi birleştirdi. İstenen sonucu bir engel ve “şu olursa bunu yapacağım” planıyla ele almak, hedefe ulaşmada mütevazı bir ortalama yarar gösterdi. Etki g = 0,336, %95 güven aralığı 0,229 ile 0,443 arasındaydı. Bulgular oldukça farklıydı. Yayın yanlılığı için yapılan düzeltme tahmini küçülttü. Bu bulgu, sınırları olan planlamayı destekler. Kursun sana sonuç vereceğine söz vermez. [M01]","Dixon ve arkadaşları, toplam 1.023 kişinin katıldığı üç ABD çevrim içi anketinde manifestasyon inancını inceledi. Bu inanç, bildirilen bazı mali risklerle ve iflas bildirimleriyle ilişkiliydi. Bildirilen gelir veya eğitimle ilişki bulunmadı. Bu ilişkiler, inancın iflasa neden olduğunu göstermez. Her manifestasyon alıştırmasını nesnel olarak sınamaz. [M07] İsteğini yapacağın işi seçmek ve koşullara bakmak için kullan. Düşüncelerinin fırsatları çektiği, sıkıntıya neden olduğu veya bir sonucu hak ettirdiği sonucunu çıkarma. Para, bakım ihtiyaçları, erişim ve başkalarının kararları yine önem taşır."]}],example:{title:"Emre işe başlıyor",text:"Akşam yemeğinden sonra Emre mutfak masasında lojistik işi hedefi için on dakika ayırıyor. Öz geçmişindeki bir cümleyi, depodaki sekiz vardiyanın planını nasıl yaptığını anlatacak biçimde düzeltiyor. Cümle hâlâ içine sinmiyor. Yine de taslağı saklayıp neyi değiştirdiğini kaydediyor. Hiçbir işveren henüz metni görmedi. Yarın üzerinde çalışabileceği gerçek bir taslak var."}},{id:"manifest-2",v2:{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"tr",title:"Yine prova mı? Şimdi gerçekten bir cümle yaz",goal:"Takıldığın bir anı prova et. Ardından aynı hedef için yaptığın işin bir sonraki küçük parçasını tamamla.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"İstediğin hayatı gözünde canlandırmak kolay. Peki boş sayfayı açtığında ne yapıyorsun?",reason:{id:"manifest-2-reason",label:"Bir prova daha işe yarar mı, yoksa asıl denemeyi mi erteler?",kind:"text",maxLength:160,optional:!0,suggestions:["Eksik bir yönergeyi fark ettirir","Yazmaya hazır cümleyi erteler","Henüz bir prova kaydım yok"]},why:{id:"manifest-2-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin işi ve varsa o iş için tuttuğun kaydı aç. Prova, belirli bir hareketi zihninde yapmaktır. İlk cümleni söylemek gibi. Adımları sıraya koymak başka bir hazırlıktır. İkisi de işi gerçekten yaptığın denemenin yerine geçmez.","Bir derlemede zihinde canlandırmanın davranışa ortalama yararları bulundu. Ama hangi türünün en iyi olduğu gösterilmedi. Bu kısa provanın işe yaradığını da kanıtlamaz. Yalnızca nerede takıldığını ve o anda ne yapabileceğini bulmak için kullan. Görüntü oluşmuyorsa hareketi sözcüklerle anlat. Ardından aynı işte kullanabileceğin bir sonraki cümleyi yaz."],example:{title:"Emre boş satırda takılıyor",text:"Emre akşam yemeğinden sonra öz geçmişine dönüyor. Otuz saniye boyunca zor bir vardiya değişikliğini anlatmayı prova ediyor. Donup kalacağını düşünüyor. Bu yüzden “Sekiz vardiyayı şu durumda değiştirdim…” diye başlamayı deniyor. Sonra kullanabileceği bir cümle yazıyor. İki sözcüğü siliyor ve yorum almak için bir soru bırakıyor. Prova, ne kadar ayrıntı gerekeceğini göstermemişti."},rehearsal:{label:"İsteğe bağlı hazırlık",steps:["Sonraki hareketi ve nerede takılabileceğini anlat.","İlk yapacağını bir kez prova et. Bu, hazırlıktır."]}},move:{invitation:"Seçtiğin işi koru. Öz geçmiş önerileri, kendi işine göre düzenleyebileceğin örnekler.",instructions:["Seçtiğin işi, en küçük adımı, başlama anını ve yeri koru. Takıldığın ana odaklan.","Planın yoksa kaydetmeden önce yapacağın işi ve uygun bir fırsatı belirt.","Bir kez prova et, ardından yap. Yalnızca prova etmek hazırlıktır."],prompts:[],suggestions:{action:["Prova et, sonra vardiya planını anlatan cümleyi yaz","Prova et, sonra öz geçmiş ayrıntısını sor","Yazılı adımlarla bir öz geçmiş tarihini düzelt"],minimum:["Provanın ardından bir öz geçmiş cümlesi kaydet","Eksik öz geçmiş ayrıntısını soran mesajı gönder","Öz geçmişte düzelttiğin bir tarihi kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Akşam yemeğinin sofrası toplandıktan sonra","Öğle yemeği bitince","Öz geçmiş belgesi açılınca"],place:["Mutfak masamda","Kütüphanedeki çalışma masasında","Öz geçmiş belgemde"],minutes:[5,2,10],fallback:["Provayı bırak, yaşadığın bir vardiya değişikliğini yaz","Görüntü kurma, yazılı ilk adımı kullan","Metni okuyana hangi ayrıntının eksik olduğunu sor"],observation:["Provada fark etmeyip işi yaparken gördüğüm ayrıntı","Yazdığım öz geçmiş cümlesi","Yalnızca prova edip etmediğim"]},suggested:{action:"Prova et, sonra vardiya planını anlatan cümleyi yaz",minimum:"Provanın ardından bir öz geçmiş cümlesi kaydet",minutes:5,cueHint:"Akşam yemeğinin sofrası toplandıktan sonra",placeHint:"Mutfak masamda",obstacleHint:"Başlamak yerine provayı düzeltip duruyorum",fallbackHint:"Provayı bırak, yaşadığın bir vardiya değişikliğini yaz",observationHint:"Provada fark etmeyip işi yaparken gördüğüm ayrıntı"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Yatakta plan yapmak seni uyanık tutuyorsa bırak. Gündüz uygun bir fırsat seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Emre ilk öz geçmiş cümlesini anlatabiliyor ve belgesi hazır. Ama başvurunun tamamını bir kez daha prova etmek istiyor.",question:"Bu denemeye hangi sonraki adım yardım eder?",options:[{id:"manifest-2-full-rehearsal",text:"Hiç yazmadan önce en iyi başlangıcı seçebilmek için başvurunun tamamını bir kez daha prova etmek.",feedback:"Tam prova ilerideki işi hazırlayabilir. Ama Emre’nin kullanabileceği bir başlangıcı ve hazır bir belgesi var. Baştan bir tur daha dönmek, önündeki denemeyi erteler. Cümleyi yazıp ortaya çıkana bak."},{id:"manifest-2-new-goal-scene",text:"Motivasyonunu tazelemek için yeni işteki ilk gününü canlandırıp başvuruya daha sonra dönmek.",feedback:"İşi hayal etmek neden önemli olduğunu netleştirebilir. Ama Emre’nin hazır başlangıcını sınamaz. Cümleyi şimdi belgeye yaz. Ardından hangi kısmın beklediğinden daha zor geldiğine bak."},{id:"manifest-2-perform-opening",text:"İlk cümleyi bir kez prova etmek, taslağa yazmak ve zorluğu beklediğiyle karşılaştırmak.",feedback:"Bu seçim, hazırlığı gerçek bir adım için kullanır. Yazılan cümle Emre’ye değerlendirebileceği bir şey verir. Kalitesi ve hissettiği rahatsızlık hâlâ açık sorulardır. Denemenin sayılması için bunların çözülmesi gerekmez."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"İşe yarayan hazırlığın ardından gerçek bir adım at. İkisini ayrı kaydet.",followUp:{questionId:"manifest-2-return",question:"Hareketi prova etmekle gerçekten yapmak arasında hangi farkı gördün?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Canlandırma araştırması bir sıralama vermiyor",paragraphs:["Cole ve arkadaşlarının 2021 derlemesi, 5.685 katılımcıyla yapılan 94 çalışmadaki 123 etkiyi birleştirdi. Zihinde canlandırmanın davranış üzerindeki genel etkisi g = 0,49, %95 güven aralığı 0,37 ile 0,62 arasındaydı. Örneklemlerin çoğu öğrencilerden oluşuyordu. Canlandırmaların içeriği, süresi ve ölçülen sonuçları farklıydı. Bu yüzden ortalama sonuç, senin kısa alıştırmanda ne olacağını önceden söylemez. Bunu kişisel bir başarı oranı olarak da okuyamayız. [M04]","Derleme, süreç adımlarını düşünmekle bir işi zihninde yapmayı ayrı ele aldı. Yalnızca süreç adımlarına ilişkin tahmin beş etkiye dayanıyordu. Güven aralığı etkisizlik değerini de içeriyordu. Türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı. Bu nedenle daha yüksek alt grup ortalamaları, güvenilir bir kazanan olduğunu göstermez. Bir grafiği daha yoğun canlandırma talimatına dönüştürme. Ders, provayı tek bir somut ayrıntıyı görmek için kullanıyor. Ardından işi denemeni istiyor. Yazıyla anlatmak erişilebilir bir seçenektir. Araştırmada görüntüyle eşdeğer bulunmuş bir yöntem olduğu iddiası değildir."]},{heading:"Fırsata hazırlan, sonra o fırsatı kullan",paragraphs:["İlk rapor planlama deneyinde katılımcılar, işe başlayacakları belirli zaman ve yeri gözlerinde canlandırdı. Zamanında yazma karşılaştırması, raporu geri veren ve kimliği belirlenebilen öğrencilerle sınırlıydı. İş, dar kapsamlı bir öğrenci ödeviydi. Bu bulgu herkes için geçerli bir hayal etme metni sunmaz. Yatakta prova yapmanın yararını da göstermez. [M10] Burada hazırlık, mevcut hedefin için bir sonraki kısmı gerçekten yapmana yardım ettiği sürece işe yarar.","Bir şifrenin eksik olduğunu, yönergenin açık olmadığını veya bir cümleyi henüz anlatamadığını fark edebilirsin. Şifreyi yenilemek hazırlıktır. Gereken bilgiyi göndermek ise işin bir parçasıdır. Kaydında bu fark görülsün. Yatarken plan yapmak seni uyanık tutuyorsa bırak. Bunun yerine gündüz uygun bir fırsat seç. Bu, kursun pratik bir uyarlaması. Kısa prova, isteğe bağlı bir uygulama alıştırmasıdır. Doğrulanmış bir ritüel veya başlamanın şartı değildir. Canlı bir görüntü kurman ya da belli bir duyguyu hissetmen gerekmiyor."]}],sourceIds:["M04","M10"]}},photo:{id:"1517363898874-737b62a7db91",alt:"Sıcak ışıkta pencere yanında sessizce oturan biri"},schemaVersion:2,title:"Yine prova mı? Şimdi gerçekten bir cümle yaz",minutes:6,goal:"Takıldığın bir anı prova et. Ardından aynı hedef için yaptığın işin bir sonraki küçük parçasını tamamla.",reading:["Seçtiğin işi ve varsa o iş için tuttuğun kaydı aç. Prova, belirli bir hareketi zihninde yapmaktır. İlk cümleni söylemek gibi. Adımları sıraya koymak başka bir hazırlıktır. İkisi de işi gerçekten yaptığın denemenin yerine geçmez.","Bir derlemede zihinde canlandırmanın davranışa ortalama yararları bulundu. Ama hangi türünün en iyi olduğu gösterilmedi. Bu kısa provanın işe yaradığını da kanıtlamaz. Yalnızca nerede takıldığını ve o anda ne yapabileceğini bulmak için kullan. Görüntü oluşmuyorsa hareketi sözcüklerle anlat. Ardından aynı işte kullanabileceğin bir sonraki cümleyi yaz."],practice:["Hedefinin hayatında yaratmasını istediğin bir farkı belirt.","İlk iki hareketini görüntüyle veya sözcüklerle sıraya koy.","Provadan sonra bir hazırlık işini gerçekten yap."],reflection:"Provada hangi eksik hazırlığı fark ettin?",question:"Bu kursta zihinsel prova ne demek?",options:["Gerçek bir işi yapmaya hazırlanmak için alıştırma.","Düşüncelerinle dışarıdaki olayları kesin olarak yönetmek.","Bir daha denemeye gerek duymamak."],correct:0,feedback:"Prova hazırlıktır. Kaynaklar bu kısa alıştırmayı doğrulamaz veya dışarıdaki sonucu yönettiğini göstermez. Hazırlığı gerçek bir adım için kullan.",takeaway:"İşe yarayan hazırlığın ardından gerçek bir adım at. İkisini ayrı kaydet.",sources:["M04","M10"],deeper:[{heading:"Canlandırma araştırması bir sıralama vermiyor",paragraphs:["Cole ve arkadaşlarının 2021 derlemesi, 5.685 katılımcıyla yapılan 94 çalışmadaki 123 etkiyi birleştirdi. Zihinde canlandırmanın davranış üzerindeki genel etkisi g = 0,49, %95 güven aralığı 0,37 ile 0,62 arasındaydı. Örneklemlerin çoğu öğrencilerden oluşuyordu. Canlandırmaların içeriği, süresi ve ölçülen sonuçları farklıydı. Bu yüzden ortalama sonuç, senin kısa alıştırmanda ne olacağını önceden söylemez. Bunu kişisel bir başarı oranı olarak da okuyamayız. [M04]","Derleme, süreç adımlarını düşünmekle bir işi zihninde yapmayı ayrı ele aldı. Yalnızca süreç adımlarına ilişkin tahmin beş etkiye dayanıyordu. Güven aralığı etkisizlik değerini de içeriyordu. Türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı. Bu nedenle daha yüksek alt grup ortalamaları, güvenilir bir kazanan olduğunu göstermez. Bir grafiği daha yoğun canlandırma talimatına dönüştürme. Ders, provayı tek bir somut ayrıntıyı görmek için kullanıyor. Ardından işi denemeni istiyor. Yazıyla anlatmak erişilebilir bir seçenektir. Araştırmada görüntüyle eşdeğer bulunmuş bir yöntem olduğu iddiası değildir."]},{heading:"Fırsata hazırlan, sonra o fırsatı kullan",paragraphs:["İlk rapor planlama deneyinde katılımcılar, işe başlayacakları belirli zaman ve yeri gözlerinde canlandırdı. Zamanında yazma karşılaştırması, raporu geri veren ve kimliği belirlenebilen öğrencilerle sınırlıydı. İş, dar kapsamlı bir öğrenci ödeviydi. Bu bulgu herkes için geçerli bir hayal etme metni sunmaz. Yatakta prova yapmanın yararını da göstermez. [M10] Burada hazırlık, mevcut hedefin için bir sonraki kısmı gerçekten yapmana yardım ettiği sürece işe yarar.","Bir şifrenin eksik olduğunu, yönergenin açık olmadığını veya bir cümleyi henüz anlatamadığını fark edebilirsin. Şifreyi yenilemek hazırlıktır. Gereken bilgiyi göndermek ise işin bir parçasıdır. Kaydında bu fark görülsün. Yatarken plan yapmak seni uyanık tutuyorsa bırak. Bunun yerine gündüz uygun bir fırsat seç. Bu, kursun pratik bir uyarlaması. Kısa prova, isteğe bağlı bir uygulama alıştırmasıdır. Doğrulanmış bir ritüel veya başlamanın şartı değildir. Canlı bir görüntü kurman ya da belli bir duyguyu hissetmen gerekmiyor."]}],example:{title:"Emre boş satırda takılıyor",text:"Emre akşam yemeğinden sonra öz geçmişine dönüyor. Otuz saniye boyunca zor bir vardiya değişikliğini anlatmayı prova ediyor. Donup kalacağını düşünüyor. Bu yüzden “Sekiz vardiyayı şu durumda değiştirdim…” diye başlamayı deniyor. Sonra kullanabileceği bir cümle yazıyor. İki sözcüğü siliyor ve yorum almak için bir soru bırakıyor. Prova, ne kadar ayrıntı gerekeceğini göstermemişti."}},{id:"manifest-3",v2:{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"tr",title:"Engel gerçek. Önce koşulları değiştir",goal:"Son denemene bak. Engel için yapabileceğin bir değişiklik seç ve dene.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Çocuk bakımı, bilgisayara erişim ya da bitkinlik mi önünü kesiyor? Daha çok inanmak gününü yeniden düzenlemez.",reason:{id:"manifest-3-reason",label:"Nerede destek gerekiyor? Şimdi hangi koşulu değiştirebilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Ortak bilgisayarı kullanacağım saatte anlaşmalıyız","Öz geçmişte yapacağım düzeltmeyi küçültebilirim","Bakım sorumluluklarım bugün zaman bırakmıyor","Henüz somut bir engelle karşılaşmadım"]},why:{id:"manifest-3-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı hedefini ve varsa deneme kaydını kullan. Henüz denemedin mi? Karşılaşabileceğin somut bir engeli belirt. “Akşam yemeğinden sonra ortak bilgisayarı kullanamıyorum” neyi değiştirebileceğini gösterir. “Disiplinsizim” ise hangi koşulun seni durdurduğunu söylemez.","İstenen sonucu, gerçek engeli ve “şu olursa bunu yapacağım” yanıtını birleştiren çalışmalarda mütevazı ortalama yararlar bulundu. Rahatsızlık hissetmenin yöntemi işe yarattığı gösterilmedi. Para, bakım sorumlulukları, zaman ve erişim gerçek koşullardır. İnancındaki kusurlar değildir. Tek değişiklik dene: işi küçült, uygun bir fırsat bul veya belirli bir yardım iste. İstemek, yardımın geldiği anlamına gelmez."],example:{title:"Emre bilgisayarı başka saatte kullanıyor",text:"Emre akşam yemeğinden sonra öz geçmişini düzenleyecekti. Ama kızının ödevi için ortak bilgisayar gerekti. Kaydına bu çakışmayı yazıyor. Ertesi gün akşam yemeğinden önce bilgisayarı on dakika kullanıp kullanamayacağını soruyor. Anlaşıyorlar. O fırsat geldiğinde bir cümleyi düzeltiyor ve duruyor. Başvuruda hâlâ yapılacak iş var. Bilgisayar zamanı istemekle cümleyi düzeltmeyi ayrı ayrı kaydedebiliyor."}},move:{invitation:"Bilgisayar gibi bir kaynağa mı ihtiyacın var? “Bunu uyarla”, sonra “Destek” seç. Kime soracağını belirt.",instructions:["Gereken kaynağı kullanabileceğin kesinleştiyse seçtiğin işi, en küçük adımı, başlama anını ve yeri koru.","Gereken kaynağı kullanamıyorsan kimden yardım isteyeceğini, neye ihtiyacın olduğunu ve ne zaman kullanacağını belirt.","İstemeyi, yardım almaktan veya işi tamamlamaktan ayrı kaydet."],prompts:[],suggestions:{action:["Kızıma akşam yemeğinden önce bilgisayarı kullanıp kullanamayacağımı sor","Kütüphane görevlisine uygun bilgisayar saatini sor"],minimum:["Kızımdan bilgisayarı on dakika kullanmayı iste","Kütüphaneye bilgisayar kullanıp kullanamayacağını mesajla sor"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Evde ödevlerin zamanı konuşulunca","Bugün öğle yemeğinden sonra","Akşam yemeğinin sofrası toplandıktan sonra"],place:["Mutfak masamda","Kütüphanenin iletişim formunda","Kütüphanedeki çalışma masasında"],minutes:[5,2,10],fallback:["Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor","Evdeki kişiye bilgisayarı kullanmak istediğini mesajla bildir","Uygun bir zaman kararlaştırılana kadar ara ver"],observation:["Erişim isteğim ve varsa gelen yanıt","Bilgisayar zamanının kararlaştırılıp kararlaştırılmadığı","Belirttiğim öz geçmiş düzeltmesini yapıp yapmadığım"]},suggested:{action:"Kızıma akşam yemeğinden önce bilgisayarı kullanıp kullanamayacağımı sor",minimum:"Kızımdan bilgisayarı on dakika kullanmayı iste",minutes:5,cueHint:"Evde ödevlerin zamanı konuşulunca",placeHint:"Mutfak masamda",obstacleHint:"Kızım bilgisayar için zaman ayıramıyor",fallbackHint:"Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor",observationHint:"Erişim isteğim ve varsa gelen yanıt",kind:"support"},accessibleAlternative:"Yazabilir, konuşabilir veya yardım alabilirsin. Erişim kararlaştırıldıktan sonra işi yapmak için “Bunu uyarla” seç.",stopRule:"Alıştırma seni çok bunaltıyorsa veya ortam güvenli değilse ara ver. Uygun destek al."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Emre’nin akşam öz geçmiş düzenleme saatleri, ortak bilgisayarda yapılan ödevlerle çakışıyor. Evdekiler anlaşırsa akşam yemeğinden önce on dakikalık bir fırsat var.",question:"Bu engeli aşmak için hangi adım daha uygun?",options:[{id:"manifest-3-arrange-opening",text:"Uygun on dakika için anlaşmak ve aynı taslakta işe yarayan bir cümleyi o anda düzeltmek.",feedback:"Bu seçim, işi durduran koşulu değiştirir ve işe yarayan en küçük adımı korur. Yine de anlaşmaları gerekir. Fırsat henüz kesinleşmediyse yaptığın isteği ayrı kaydet. Bilgisayarı kullanmış gibi yazma."},{id:"manifest-3-keep-evening",text:"Akşam planını korumak, bilgisayar boşalınca hazır olmak için daha uzun bir prova eklemek.",feedback:"Prova cümleleri hazırlayabilir. Ama bilgisayarın kullanımındaki çakışmayı çözmez. Emre’nin başka bir zaman seçme olasılığı var. Yeni bir hazırlık düzeni eklemeden önce o zaman için anlaş."},{id:"manifest-3-wait-week",text:"Ödevler hafifleyene kadar gelecek haftayı beklemek, sonra istediği daha uzun öz geçmiş çalışmasına dönmek.",feedback:"Yapılabilir hiçbir fırsat yoksa beklemek uygun olabilir. Burada küçük bir fırsat şimdi kararlaştırılabilir. İşin tamamını kendiliğinden ertelemek yerine önce bu seçeneği dene. Sonucu sonra değerlendir."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Seni durduran gerçek koşulu belirt. Yapacağın işi değiştir veya gereken somut desteği iste.",followUp:{questionId:"manifest-3-return",question:"Erişim isteğini ilettin mi ya da işi yaptın mı? Hangi konuda hâlâ anlaşmak gerekiyor?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Engel bir bilgi. Rahatsızlık şart değil",paragraphs:["2021’de zihinsel karşılaştırmayı planlamayla birleştiren derleme, 24 bağımsız etkide hedefe ulaşmada mütevazı ortalama artış buldu. Sonuçların oldukça farklı olması ve yayın yanlılığı işaretleri kesinliği sınırlar. Derleme, rahatsızlık hissetmeyi yöntemin işe yarayan parçası olarak ayrı ayrı sınamadı. Bir güçlüğü adlandırmak hoş gelmeyebilir. Ama burada amaç sıkıntıyı bilerek artırmak değil. Ne gerektiğini görmek ve atabileceğin bir adım seçmek. [M01]","Oettingen ve arkadaşlarının incelenen 2015 uygulamasında öğrenciler istedikleri sonucu ve temel engeli ayrıntılı yazdı. Engel çıkarsa ne yapacaklarını seçip planladı. Olağan zamanını ve yerini ekledi. Birinci çalışmada önceden planlanan karşılaştırma, takvime yazılan saatler için yöntem lehineydi. Ölçülen sonuç tamamlanmış iş değil, planlamaydı. Koşulların genel karşılaştırması kesin sonuç vermedi. [M11] ODA, koşulların uygunluğunu kontrol etmeyi ve gerçek denemeyi ekliyor. Bu kısa alıştırma, dış koşullarla kişisel tepkileri ayırma biçimiyle birlikte o deneyde ayrıca doğrulanmadı. Sonucu bir üretkenlik sözü olarak kullanamayız."]},{heading:"Doğru adım bazen destek istemektir",paragraphs:["İstediğin sonucu, o sonuca ilerlemek için gereken koşullardan ayır. Araç eksikse erişim gerekir. Ortam güvenli değilse korunmak gerekir. Bakım sorumluluğuyla çakışma varsa başka bir zaman gerekebilir. Bu ayrım, planlama araştırmasından yararlanan bir kurs tercihidir. Her engeli tek bir kutuya yerleştiren doğrulanmış bir sınıflandırma değil. Destek isteğinde hangi yardıma, hangi fırsatta ihtiyaç duyduğunu söylersen somut bir istek yapmış olursun. Yardımı istemek, karşı tarafın vereceği yanıttan ayrı kalır. [M01, M11]","Biri yanıt vermediyse isteği ve henüz yanıt gelmediğini kaydet. Yardım almış veya işi tamamlamış gibi yazma. Başka yapılabilir bir adım seçebilir, hedefini değiştirebilir ya da ara verebilirsin. Sıkıntı sürüyorsa veya günlük hayatını önemli ölçüde aksatıyorsa alıştırmayı yoğunlaştırmak yerine uzman desteği al. NIMH rehberi, sağlık ve kriz desteğine ulaşma yollarını anlatır. ODA’nın bir durumu tedavi ettiğine kanıt değildir. [M14] Sonraki kaydın, korunmak veya destek istemek dahil, seçtiğin işi anlatsın. Başta gördüğün gerçek engeli sonradan yeterince inanmadığın için yaşanmış gibi anlatma."]}],sourceIds:["M01","M11","M14"]}},photo:{id:"1767134063671-322e6faf9206",alt:"Yapraklı orman yoluna devrilmiş ağaç"},schemaVersion:2,title:"Engel gerçek. Önce koşulları değiştir",minutes:6,goal:"Son denemene bak. Engel için yapabileceğin bir değişiklik seç ve dene.",reading:["Aynı hedefini ve varsa deneme kaydını kullan. Henüz denemedin mi? Karşılaşabileceğin somut bir engeli belirt. “Akşam yemeğinden sonra ortak bilgisayarı kullanamıyorum” neyi değiştirebileceğini gösterir. “Disiplinsizim” ise hangi koşulun seni durdurduğunu söylemez.","İstenen sonucu, gerçek engeli ve “şu olursa bunu yapacağım” yanıtını birleştiren çalışmalarda mütevazı ortalama yararlar bulundu. Rahatsızlık hissetmenin yöntemi işe yarattığı gösterilmedi. Para, bakım sorumlulukları, zaman ve erişim gerçek koşullardır. İnancındaki kusurlar değildir. Tek değişiklik dene: işi küçült, uygun bir fırsat bul veya belirli bir yardım iste. İstemek, yardımın geldiği anlamına gelmez."],practice:["Hedefinin önündeki en yakın engeli belirt.","Değiştirebileceğin kısmıyla destek veya zaman gerektiren kısmını ayır.","Şimdi yapılmıyorsa işi küçült veya uygun bir zamana taşı."],reflection:"Engeline daha gerçekçi bakınca planında ne değişti?",question:"Dış koşullar önümü kestiğinde…",options:["Yeterince inanmadığım için olduğunu varsaymalıyım.","Koşulları görmezden gelmeliyim.","Desteği, zamanı veya hedefin büyüklüğünü yeniden düşünebilirim."],correct:2,feedback:"Gerçekçi plan dış koşullara bakar. Sonuçları yalnızca düşüncelerin belirlemez.",takeaway:"Seni durduran gerçek koşulu belirt. Yapacağın işi değiştir veya gereken somut desteği iste.",sources:["M01","M11","M14"],deeper:[{heading:"Engel bir bilgi. Rahatsızlık şart değil",paragraphs:["2021’de zihinsel karşılaştırmayı planlamayla birleştiren derleme, 24 bağımsız etkide hedefe ulaşmada mütevazı ortalama artış buldu. Sonuçların oldukça farklı olması ve yayın yanlılığı işaretleri kesinliği sınırlar. Derleme, rahatsızlık hissetmeyi yöntemin işe yarayan parçası olarak ayrı ayrı sınamadı. Bir güçlüğü adlandırmak hoş gelmeyebilir. Ama burada amaç sıkıntıyı bilerek artırmak değil. Ne gerektiğini görmek ve atabileceğin bir adım seçmek. [M01]","Oettingen ve arkadaşlarının incelenen 2015 uygulamasında öğrenciler istedikleri sonucu ve temel engeli ayrıntılı yazdı. Engel çıkarsa ne yapacaklarını seçip planladı. Olağan zamanını ve yerini ekledi. Birinci çalışmada önceden planlanan karşılaştırma, takvime yazılan saatler için yöntem lehineydi. Ölçülen sonuç tamamlanmış iş değil, planlamaydı. Koşulların genel karşılaştırması kesin sonuç vermedi. [M11] ODA, koşulların uygunluğunu kontrol etmeyi ve gerçek denemeyi ekliyor. Bu kısa alıştırma, dış koşullarla kişisel tepkileri ayırma biçimiyle birlikte o deneyde ayrıca doğrulanmadı. Sonucu bir üretkenlik sözü olarak kullanamayız."]},{heading:"Doğru adım bazen destek istemektir",paragraphs:["İstediğin sonucu, o sonuca ilerlemek için gereken koşullardan ayır. Araç eksikse erişim gerekir. Ortam güvenli değilse korunmak gerekir. Bakım sorumluluğuyla çakışma varsa başka bir zaman gerekebilir. Bu ayrım, planlama araştırmasından yararlanan bir kurs tercihidir. Her engeli tek bir kutuya yerleştiren doğrulanmış bir sınıflandırma değil. Destek isteğinde hangi yardıma, hangi fırsatta ihtiyaç duyduğunu söylersen somut bir istek yapmış olursun. Yardımı istemek, karşı tarafın vereceği yanıttan ayrı kalır. [M01, M11]","Biri yanıt vermediyse isteği ve henüz yanıt gelmediğini kaydet. Yardım almış veya işi tamamlamış gibi yazma. Başka yapılabilir bir adım seçebilir, hedefini değiştirebilir ya da ara verebilirsin. Sıkıntı sürüyorsa veya günlük hayatını önemli ölçüde aksatıyorsa alıştırmayı yoğunlaştırmak yerine uzman desteği al. NIMH rehberi, sağlık ve kriz desteğine ulaşma yollarını anlatır. ODA’nın bir durumu tedavi ettiğine kanıt değildir. [M14] Sonraki kaydın, korunmak veya destek istemek dahil, seçtiğin işi anlatsın. Başta gördüğün gerçek engeli sonradan yeterince inanmadığın için yaşanmış gibi anlatma."]}],example:{title:"Emre bilgisayarı başka saatte kullanıyor",text:"Emre akşam yemeğinden sonra öz geçmişini düzenleyecekti. Ama kızının ödevi için ortak bilgisayar gerekti. Kaydına bu çakışmayı yazıyor. Ertesi gün akşam yemeğinden önce bilgisayarı on dakika kullanıp kullanamayacağını soruyor. Anlaşıyorlar. O fırsat geldiğinde bir cümleyi düzeltiyor ve duruyor. Başvuruda hâlâ yapılacak iş var. Bilgisayar zamanı istemekle cümleyi düzeltmeyi ayrı ayrı kaydedebiliyor."}},{id:"manifest-4",v2:{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"tr",title:"Hazır hissetmeyi bekleyip durma",goal:"Fark edebileceğin bir başlama işareti seç. Takıldığın yerde küçük bir adım dene.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"“Hazır olunca” dediğin an hep erteleniyor. Gerçekten fark edebileceğin bir olay seç.",reason:{id:"manifest-4-reason",label:"İşaret en son geldiğinde işi ertelemek sana neye mal oldu?",kind:"text",maxLength:160,optional:!0,suggestions:["Örnekleri karşılaştırdım; cümle yazamadım","Hazır hissetmeyi bekledim; taslak değişmedi","Bakım sorumluluğu vardı; güvenli fırsat yoktu","Başlama anı henüz gelmedi; cümle kurarken oyalanabilirim"],help:"Önceki denemen yoksa seni durdurabilecek bir tereddüdü belirt."},why:{id:"manifest-4-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Başlama işareti ve engel çıkınca yapacağın şey farklı işlere yarar. “Tabaklar kalkınca bir öz geçmiş cümlesi yaz” sana fırsat verir. “Takılırsam bir vardiya değişikliğini anlat” ise o fırsatın içinde ne yapacağını söyler.","Farklı hedeflerde yapılan araştırmalar, belirli “şu olursa bunu yaparım” planlarının işi sürdürmeye ortalama destek verdiğini buldu. Bütün unutkanlığı, çabayı veya somut engelleri kaldırmazlar. Seçtiğin işi koru. Varsa kaydettiğin engeli ele al. Fark edebileceğin tek işaret ve o anda atabileceğin küçük bir adım seç. İşaret hiç oluşmazsa fırsat olmadığını kaydet ve başka bir zaman bul."],example:{title:"Emre işareti kullanıyor",text:"Emre ortak bilgisayarın yanına not bırakıyor: “Tabaklar kalkınca bir cümleyi düzelt. Takılırsan bir vardiya değişikliğini anlat.” Perşembe günü o an geliyor ve notu görüyor. Kullanabileceği bir cümle yazıyor. Ama aile sorumlulukları yeniden başlamadan bölümü bitiremiyor. Kaydında iki bilgi de var: Cümle yazıldı, bölüm henüz tamamlanmadı. Birini ötekinin yerine koymuyor."}},move:{invitation:"Seçtiğin işi ve başlama zamanını koru. Öneriler, Emre’nin öz geçmişinden uyarlayabileceğin örnekler.",instructions:["Değişiklik gerekmiyorsa seçtiğin işi, en küçük adımı, başlama anını ve yeri koru.","Kaydetmeden önce gerçekten takıldığın an için daha küçük ne yapabileceğini belirt."],prompts:[],suggestions:{action:["Akşam yemeğinden sonra vardiya planını anlatan cümleyi yaz","Öğle yemeğinden sonra öz geçmiş ayrıntısını sor","Çaydan sonra öz geçmişte bir tarihi düzelt"],minimum:["Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet","Eksik öz geçmiş ayrıntısını soran mesajı gönder","Öz geçmişte düzelttiğin bir tarihi kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Tabaklar kaldırılınca","Öğle yemeği bitince","Çayımı masaya bıraktığımda"],place:["Mutfak masamda","Öz geçmiş belgemde","Kütüphanedeki çalışma masasında"],minutes:[5,2,10],fallback:["Yaşadığın bir vardiya değişikliğini tek cümleyle anlat","Uygun başka bir fırsat seç ve belirt","Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor"],observation:["İşaretin oluşması ve onu fark etmem","Vardiya değişikliğini anlatıp anlatmadığım","Öz geçmişte kaydettiğim düzeltme"]},suggested:{action:"Akşam yemeğinden sonra vardiya planını anlatan cümleyi yaz",minimum:"Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet",minutes:5,cueHint:"Tabaklar kaldırılınca",placeHint:"Mutfak masamda",obstacleHint:"Başlama anı geliyor ama cümleyi kurarken takılıyorum",fallbackHint:"Yaşadığın bir vardiya değişikliğini tek cümleyle anlat",observationHint:"İşaretin oluşması ve onu fark etmem"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Bakım ve güvenlik sorumluluklarını koru. Bu işaret uygun olmaktan çıkarsa başka fırsat kullan."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Emre’nin akşam yemeğinin sofrasını topladıktan sonra beş dakikası var. Taslağı ve doğru bir vardiya değişikliği örneği hazır. Ama cümleyi kurarken oyalanıyor.",question:"Hangi plan hem başlamaya hem takılınca ilerlemeye uyar?",options:[{id:"manifest-4-mood-cue",text:"Akşam yemeğinden sonra zihni daha açık olduğunda, en iyi örnekleriyle öz geçmiş bölümünü beş dakika düzenlemek.",feedback:"Zihninin açılması güzel olurdu. Ama bu, sürekli değişebilen bir başlama işareti. Akşam yemeğinin bittiği, fark edebileceğin anı kullan. Elindeki beş dakikaya sığacak kadar küçük bir adım seç. Hazır hissetmeyi beklemen gerekmiyor."},{id:"manifest-4-full-section",text:"Tabakları kaldırınca üç vardiya örneğini karşılaştırmak ve öz geçmiş cümlesi için en iyisini seçmek.",feedback:"Karşılaştırma seçim yapmayı kolaylaştırabilir. Ama Emre’nin doğru bir örneği zaten var. Yeni örnek aramak beş dakikayı tüketir. Önce o vardiya değişikliğini anlat. Cümle ortaya çıktıktan sonra sözcüklere bak."},{id:"manifest-4-cue-and-response",text:"Tabakları kaldırınca bir cümleyi düzeltmek; sözcüklerde takılırsa yaşadığı bir vardiya değişikliğini sade anlatmak.",feedback:"Bu plan, ne zaman başlayacağını ve takılırsa ne yapacağını ayrı ayrı belirler. Emre hazır taslağıyla deneyebilir. Plan bir adımı destekler. Çabasız hatırlama veya bütün bölümü bitirme sözü vermez. Gerçekte olanı kaydet."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Başlama anını seç. Takılırsan ne yapacağını belirle. Sonra ikisinin de gerçekleşip gerçekleşmediğine bak.",followUp:{questionId:"manifest-4-return",question:"Başlama işaretini fark ettin mi? Takılınca yapmayı planladığın adımı o anda atabildin mi?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Belirli bir plan neye yardım eder?",paragraphs:["Gollwitzer ve Sheeran’ın 2006 bölümü, 8.461 katılımcıyla yapılan 94 bağımsız testi birleştirdi. “Şu olursa bunu yapacağım” planlarının hedefe ulaşmadaki ortalama etkisi d = 0,65, %95 güven aralığı 0,60 ile 0,70 arasındaydı. İşler ve yöntemler farklıydı. Bu eski araştırmaların hepsi önceden kayıt altına alınmış değildi. Sonuç, kendi yazdığın herhangi bir cümlenin kesin işe yarayacağını göstermez. Ortalamayı kişisel sonucun gibi kullanma. [M02]","Fırsat planlama deneyinde öğrenciler rapora başlayacakları belirli zaman ve yeri seçti. Zamanında yazma karşılaştırması herkesi değil, raporunu geri veren ve kimliği bilinen kişileri kapsıyordu. [M10] Buradaki pratik fikir, “plan iradenin yerini alır” iddiasından daha dar. Önceden ne yapacağını seç. Sonra o an geldi mi, fark ettin mi, seçtiğin adımı atabildin mi, bunlara bak. Gerekiyorsa dışarıdan hatırlatıcı kullanmayı sürdür. Bir aracın yanına not bırakmak ODA’da bir seçenek. Notu mutlaka fark edeceğini gösteren, deneyle sınanmış bir garanti değil."]},{heading:"Aynı denemede iki ayrı ihtiyaç",paragraphs:["Başlama planın işi ne zaman deneyeceğini söyler. Engel çıkınca yapacağın şey ise gördüğün güçlüğe karşılık verir. İncelenen zihinsel karşılaştırma uygulaması engelle davranışı eşleştirdi, olağan zamanını ve yerini ekledi. Herkesin iki ayrı kurala ihtiyacı olduğunu göstermedi. [M11] Kurs bu iki işi, mevcut denemende neyin aksadığını daha kolay görebilmen için ayırıyor. Bu, araştırmada ayrıca sınanmış bir teşhis yöntemi değil. Kendi kaydına bakarak yapabileceğin sonraki seçimi netleştiriyor.","Planladığın fırsat hiç oluşmadı diyelim. O zaman engel çıkınca atmayı seçtiğin adımın başarısız olduğunu söyleyemezsin. Fırsat oluştu ama kaçırdıysan işareti veya hatırlatıcıyı değiştir. Fark ettin ama iş büyük geldiyse sonraki işe yarayan parçayı küçült. Bunlar denenecek seçeneklerdir. Tek bir özel kaydın kanıtladığı araştırma sonuçları değil. Eski kayıtları, ilk seçtiğin en küçük adımla birlikte koru. Sonraki planı değiştirmek, geçmişte yarım kalmış işi tamamlanmış yapmaz. Gerçekte ne yaptığını değerlendir. Destek alma, dinlenme, ara verme veya hedefi değiştirme seçeneklerin de kalsın."]}],sourceIds:["M02","M10","M11"]}},photo:{id:"1591462391971-9ffc57b382b9",alt:"Renkli yapışkan notlar ve kalemler"},schemaVersion:2,title:"Hazır hissetmeyi bekleyip durma",minutes:6,goal:"Fark edebileceğin bir başlama işareti seç. Takıldığın yerde küçük bir adım dene.",reading:["Başlama işareti ve engel çıkınca yapacağın şey farklı işlere yarar. “Tabaklar kalkınca bir öz geçmiş cümlesi yaz” sana fırsat verir. “Takılırsam bir vardiya değişikliğini anlat” ise o fırsatın içinde ne yapacağını söyler.","Farklı hedeflerde yapılan araştırmalar, belirli “şu olursa bunu yaparım” planlarının işi sürdürmeye ortalama destek verdiğini buldu. Bütün unutkanlığı, çabayı veya somut engelleri kaldırmazlar. Seçtiğin işi koru. Varsa kaydettiğin engeli ele al. Fark edebileceğin tek işaret ve o anda atabileceğin küçük bir adım seç. İşaret hiç oluşmazsa fırsat olmadığını kaydet ve başka bir zaman bul."],practice:["Bir engeli fark edeceğin anı “Şu olursa…” diye anlat.","“Bunu yaparım…” kısmına tek küçük davranış yaz.","Planın elindeki zamana ve araçlara uyduğunu kontrol et. Sonra bir kez prova et."],reflection:"Senin “şu olursa bunu yaparım” cümlen ne?",question:"Hangi plan gerçekten denenebilir?",options:["Her şey kendiliğinden düzelir.","Dosyayı açınca takılırsam önce başlığı yazarım.","İyi enerji gönderirsem bütün engeller kaybolur."],correct:1,feedback:"İkinci seçenek, belirli bir durumu gözlenebilen davranışla birleştiriyor. Araştırmada sınanan yaklaşım, bu tür davranış planlamasına benzer.",takeaway:"Başlama anını seç. Takılırsan ne yapacağını belirle. Sonra ikisinin de gerçekleşip gerçekleşmediğine bak.",sources:["M02","M10","M11"],deeper:[{heading:"Belirli bir plan neye yardım eder?",paragraphs:["Gollwitzer ve Sheeran’ın 2006 bölümü, 8.461 katılımcıyla yapılan 94 bağımsız testi birleştirdi. “Şu olursa bunu yapacağım” planlarının hedefe ulaşmadaki ortalama etkisi d = 0,65, %95 güven aralığı 0,60 ile 0,70 arasındaydı. İşler ve yöntemler farklıydı. Bu eski araştırmaların hepsi önceden kayıt altına alınmış değildi. Sonuç, kendi yazdığın herhangi bir cümlenin kesin işe yarayacağını göstermez. Ortalamayı kişisel sonucun gibi kullanma. [M02]","Fırsat planlama deneyinde öğrenciler rapora başlayacakları belirli zaman ve yeri seçti. Zamanında yazma karşılaştırması herkesi değil, raporunu geri veren ve kimliği bilinen kişileri kapsıyordu. [M10] Buradaki pratik fikir, “plan iradenin yerini alır” iddiasından daha dar. Önceden ne yapacağını seç. Sonra o an geldi mi, fark ettin mi, seçtiğin adımı atabildin mi, bunlara bak. Gerekiyorsa dışarıdan hatırlatıcı kullanmayı sürdür. Bir aracın yanına not bırakmak ODA’da bir seçenek. Notu mutlaka fark edeceğini gösteren, deneyle sınanmış bir garanti değil."]},{heading:"Aynı denemede iki ayrı ihtiyaç",paragraphs:["Başlama planın işi ne zaman deneyeceğini söyler. Engel çıkınca yapacağın şey ise gördüğün güçlüğe karşılık verir. İncelenen zihinsel karşılaştırma uygulaması engelle davranışı eşleştirdi, olağan zamanını ve yerini ekledi. Herkesin iki ayrı kurala ihtiyacı olduğunu göstermedi. [M11] Kurs bu iki işi, mevcut denemende neyin aksadığını daha kolay görebilmen için ayırıyor. Bu, araştırmada ayrıca sınanmış bir teşhis yöntemi değil. Kendi kaydına bakarak yapabileceğin sonraki seçimi netleştiriyor.","Planladığın fırsat hiç oluşmadı diyelim. O zaman engel çıkınca atmayı seçtiğin adımın başarısız olduğunu söyleyemezsin. Fırsat oluştu ama kaçırdıysan işareti veya hatırlatıcıyı değiştir. Fark ettin ama iş büyük geldiyse sonraki işe yarayan parçayı küçült. Bunlar denenecek seçeneklerdir. Tek bir özel kaydın kanıtladığı araştırma sonuçları değil. Eski kayıtları, ilk seçtiğin en küçük adımla birlikte koru. Sonraki planı değiştirmek, geçmişte yarım kalmış işi tamamlanmış yapmaz. Gerçekte ne yaptığını değerlendir. Destek alma, dinlenme, ara verme veya hedefi değiştirme seçeneklerin de kalsın."]}],example:{title:"Emre işareti kullanıyor",text:"Emre ortak bilgisayarın yanına not bırakıyor: “Tabaklar kalkınca bir cümleyi düzelt. Takılırsan bir vardiya değişikliğini anlat.” Perşembe günü o an geliyor ve notu görüyor. Kullanabileceği bir cümle yazıyor. Ama aile sorumlulukları yeniden başlamadan bölümü bitiremiyor. Kaydında iki bilgi de var: Cümle yazıldı, bölüm henüz tamamlanmadı. Birini ötekinin yerine koymuyor."}},{id:"manifest-5",v2:{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"tr",title:"Sonuç yok mu? Önce yaptıklarına bak",goal:"Deneme kayıtlarına göre yapılabilir bir sonraki adım seç. Gelecek hafta ne zaman değerlendireceğini belirle.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Hayalinden vazgeçmeden önce bak: Bu yolu gerçekten denedin mi, yoksa hep plan mı yaptın?",reason:{id:"manifest-5-reason",label:"Bu yolu sürdürmek, değiştirmek veya bırakmak için neye bakarsın?",kind:"text",maxLength:160,optional:!0,suggestions:["Kullanılabilir taslak var; başvuruyu gönder","Zamanlar hep çakışıyor; fırsatı değiştir","Somut yorum var; belirsiz cümleyi düzelt","Henüz deneme yok; ilk adımı seç"]},why:{id:"manifest-5-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı hedef için tuttuğun kayıtları oku. Planladığını, provasını yaptığını, gerçekten yaptığını ve başkalarından geleni ayır. Sakladığın taslak, taslak üzerinde çalıştığını gösterir. Başvuruyu gönderdiğini veya işverenin ilgilendiğini göstermez. Kaydında olmayan bir sonucu kendiliğinden ekleme.","138 deneyi birleştiren derlemede, ilerlemeyi daha çok izlemenin ortalama yararları bulundu. Bu kayıt biçimi veya en iyi değerlendirme aralığı doğrulanmadı. Gerçeklerden yola çık: işe yarayan adımı tekrarla, tek sorunu değiştir, yorum iste veya uygun olmayan hedefi bırak. Deneme yoksa bu boşluğu belirt. Sonra kullanabileceğin ilk küçük işi yap."],example:{title:"Emre gelecek haftayı seçiyor",text:"Emre tarihli üç düzeltmeyi ve kaçırdığı bir bilgisayar fırsatını okuyor. Öz geçmişi daha açık. Ama başvuru göndermemiş. Uygun bir ilan seçiyor, koşullarını kontrol ediyor ve hazırladığı sürümü cuma günü gönderiyor. Gönderdiğini kaydedip gelecek hafta değerlendirmek için zaman ayırıyor. Henüz yanıt yok. Kaydı başvuruyu anlatıyor, işverenin ilgisini varsaymıyor."}},move:{invitation:"İşe yarayanı koru. Sonra ne yapacağını belirt. Öneriler, hazır bir başvurudan uyarlayabileceğin örnekler.",instructions:["Tekrarlarken seçtiğin en küçük adımı ve zamanı koru. Yalnızca gördüğün sorunu değiştir.","Kaydın yoksa kaydetmeden önce ilk işini ve ona uyan en küçük adımı belirt.","Bilgi istemek, soru sormaktır. Durmuş olan işi tamamlamak değildir."],prompts:[],suggestions:{action:["Hazır başvuruyu seçtiğim iş ilanına gönder","Başvurudaki belirsiz koşulu ilgili kişiye sor","Metni okuyanın yorumuyla bir öz geçmiş cümlesini düzelt"],minimum:["Hazır başvuruyu bir kez gönder","Başvuru koşuluyla ilgili soruyu gönder","Düzelttiğin öz geçmiş cümlesini kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Öğle yemeği bitince","Akşam yemeğinin sofrası toplandıktan sonra","İlanın başvuru sayfası açılınca"],place:["Mutfak masamda","Kütüphanedeki çalışma masasında","İlanın başvuru formunda"],minutes:[10,2,5],fallback:["Başvurudaki belirsiz koşulu ilgili kişiye sor","Belirsiz cümle hakkında metni okuyandan yorum iste","Gereken bilgi gelene kadar ara ver"],observation:["Gönderdiğim başvuru ve varsa gönderim onayı","Bilgi isteğim ve beklenen yanıt","Kontrolüm dışında kalan koşullar"]},suggested:{action:"Hazır başvuruyu seçtiğim iş ilanına gönder",minimum:"Hazır başvuruyu bir kez gönder",minutes:10,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Başvuruda gereken bir ayrıntı belirsiz",fallbackHint:"Başvurudaki belirsiz koşulu ilgili kişiye sor",observationHint:"Gönderdiğim başvuru ve varsa gönderim onayı"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Belirsiz bir sonucu kurtarmak için harcamanı artırma veya gereken bakım ve sağlık desteğinden vazgeçme."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Emre öz geçmişini düzenlemiş ama başvurmamış. Uygun ilanın süresi bu gece doluyor. Taslağı koşulları karşılıyor. Bir kişi yarın sürümleri karşılaştırabilir.",question:"Bu değerlendirme hangi adıma götürmeli?",options:[{id:"manifest-5-next-application",text:"Hazır başvuruyu göndermek, gönderimi kaydetmek ve yanıt belirsizken daha sonraki değerlendirme zamanını seçmek.",feedback:"Kayıt, Emre’nin yapabileceği ve hazır olan somut bir sonraki adımı gösteriyor. Yapılacak iş başvuruyu göndermek. Gerçek bir yanıt gelene kadar işverenin kararı belli değil. Gönderimi sonuçtan ayrı kaydet."},{id:"manifest-5-double-editing",text:"Zayıf ifadeleri azaltmak için göndermeden önce birinden iki öz geçmiş sürümünü karşılaştırmasını istemek.",feedback:"Karşılaştırmak metindeki sorunları gösterebilir. Ama bu gecenin son tarihine yetişmez. Emre koşulları kontrol etmiş, bilinen bir eksik kalmamış. Uygun sürümü gönder. Sonraki yorumları gerçek bir değişiklik için kullan."},{id:"manifest-5-change-direction",text:"Hangi öz geçmiş sürümünü koruyacağını seçmeden önce daha çok yere ulaşmak için birkaç genel başvuru göndermek.",feedback:"Daha geniş aramak fırsat yaratabilir. Burada uygun bir başvuru zaten hazır. Onu göndermek bu eşleşmeyi sınar. Başvuru sayısını artırmak sonraki seçim olabilir. Hazır ve uygun başvurunun yerine geçmesi gerekmez."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Sonraki adımı kaydına göre seç. Çaba, hazırlık ve dışarıdan gelen sonuç aynı şey değil.",followUp:{questionId:"manifest-5-return",question:"Seçtiğin işte veya bilgi isteğinde ne oldu? Hangi konu hâlâ yanıt bekliyor?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Takip, bir sonraki kararına bilgi verir",paragraphs:["Harkin ve arkadaşlarının 2016 derlemesinde rastgele gruplara ayrılan toplam 19.951 kişiyle 138 deney vardı. Hedefe ulaşma analizi 18.398 katılımcı içeriyordu. Etki d = 0,40, %95 güven aralığı 0,32 ile 0,48 arasındaydı. Küçük çalışmaların olası etkisini kontrol eden duyarlılık düzeltmesi daha düşük tahmin verdi. Müdahaleler, hedefler ve kayıt yöntemleri farklıydı. Derleme ODA’nın kayıt özetini veya ertesi gün kartını sınamadı. Bu ortalama, senin işinde aynı yararın olacağına söz vermez. [M03]","Çalışmalar arasında ilerlemeyi yazmak veya başkalarına bildirmek daha büyük etkilerle ilişkiliydi. Bu karşılaştırmalar herkese açık paylaşımın gerekli olduğunu göstermez. Tek bir uygulama biçiminin yarara neden olduğunu da kanıtlamaz. Durumuna uyuyorsa kişisel ayrıntılarını kendine sakla. Kayıtlarına bak: ne yapmayı planlamıştın, gerçekte ne yaptığını yazdın? İkisini karşılaştır. Kayıt yoksa ne olduğu bilinmiyor. Tamamladığın hazırlık, yanıtsız istek veya bıraktığın deneme kendi adıyla kalsın. Böylece sonraki seçimin incelenebilir olur. Olumlu bir hikâye yazman veya olmayan ilerlemeyi varmış gibi göstermen gerekmez."]},{heading:"Geçmişi değiştirmeden gelecek haftayı seç",paragraphs:["Kısa bir kişisel kayıt, tekrar eden bir durum düşündürebilir. Ama dışarıdan gelen sonucun nedenini kanıtlayamaz. Başvurular, siparişler ve başkasının yanıtı kaliteye, zamana, kaynaklara veya kaydının ölçmediği koşullara bağlı olabilir. Takip araştırması bilgiyi kullanmayı destekler. Hedefini değiştirmeden önce herkesin belli sayıda deneme yapması gerektiğini göstermez. [M03] Değerlendirirken bu belirsizliği görünür tut. Tek kişinin kaydı, o sonuca neyin neden olduğunu açıklayan bir deney değil.","Gelecek hafta için yapılabilir tek bir fırsat ve değerlendirme zamanı seç. Kullanabildiğin en küçük adımı ve işe erişmeni kolaylaştıran koşulları koru. Kayıtlarında sorun gördüğün kısmı değiştir. Deneme kaydı yoksa bildiğin gerçekleri yaz veya sonraki küçük işi ilk denemen say. Olmayan bir emek geçmişi uydurma. Planlama çalışmaları farklı sonuçlarla birlikte ortalama yararlar gösteriyor, garanti değil. [M01] Ara vermek, yorum istemek, somut destek bulmak veya yön değiştirmek değerlendirmenin bilinçli sonucu olabilir. Önceki kaydı koru. Böylece bu seçimin nedenini daha sonra da görebilirsin."]}],sourceIds:["M03","M01"]}},photo:{id:"1762920738995-f393efe82205",alt:"Ormanda farklı yönleri gösteren ahşap yön tabelası"},schemaVersion:2,title:"Sonuç yok mu? Önce yaptıklarına bak",minutes:6,goal:"Deneme kayıtlarına göre yapılabilir bir sonraki adım seç. Gelecek hafta ne zaman değerlendireceğini belirle.",reading:["Aynı hedef için tuttuğun kayıtları oku. Planladığını, provasını yaptığını, gerçekten yaptığını ve başkalarından geleni ayır. Sakladığın taslak, taslak üzerinde çalıştığını gösterir. Başvuruyu gönderdiğini veya işverenin ilgilendiğini göstermez. Kaydında olmayan bir sonucu kendiliğinden ekleme.","138 deneyi birleştiren derlemede, ilerlemeyi daha çok izlemenin ortalama yararları bulundu. Bu kayıt biçimi veya en iyi değerlendirme aralığı doğrulanmadı. Gerçeklerden yola çık: işe yarayan adımı tekrarla, tek sorunu değiştir, yorum iste veya uygun olmayan hedefi bırak. Deneme yoksa bu boşluğu belirt. Sonra kullanabileceğin ilk küçük işi yap."],practice:["İlk küçük denemeni yap veya ne zaman yapacağını kesinleştir.","Sonuca bakmak için makul bir tarih seç. “Neyi denedim, ne öğrendim?” diye sor.","Sana uyan seçeneği belirle: sürdür, küçült, destek al veya hedefi değiştir."],reflection:"Hangi gün, hangi bilgilere bakarak planını değerlendireceksin?",question:"İstediğin sonuç gelmediğinde hangi değerlendirme daha işe yarar?",options:["Düşüncelerim yeterince güçlü değildi.","Denediğim davranışlara ve koşullara bakıp sonraki seçimi yapmak.","Gerçeklere bakmadan aynı beklentiyi sürdürmek."],correct:1,feedback:"Planla gerçeği karşılaştırmak yeni bilgi verir. Hiçbir kurs sonucu garanti etmez. Kendi yaptığınla dış koşulları birlikte değerlendirebilirsin.",takeaway:"Sonraki adımı kaydına göre seç. Çaba, hazırlık ve dışarıdan gelen sonuç aynı şey değil.",sources:["M03","M01"],deeper:[{heading:"Takip, bir sonraki kararına bilgi verir",paragraphs:["Harkin ve arkadaşlarının 2016 derlemesinde rastgele gruplara ayrılan toplam 19.951 kişiyle 138 deney vardı. Hedefe ulaşma analizi 18.398 katılımcı içeriyordu. Etki d = 0,40, %95 güven aralığı 0,32 ile 0,48 arasındaydı. Küçük çalışmaların olası etkisini kontrol eden duyarlılık düzeltmesi daha düşük tahmin verdi. Müdahaleler, hedefler ve kayıt yöntemleri farklıydı. Derleme ODA’nın kayıt özetini veya ertesi gün kartını sınamadı. Bu ortalama, senin işinde aynı yararın olacağına söz vermez. [M03]","Çalışmalar arasında ilerlemeyi yazmak veya başkalarına bildirmek daha büyük etkilerle ilişkiliydi. Bu karşılaştırmalar herkese açık paylaşımın gerekli olduğunu göstermez. Tek bir uygulama biçiminin yarara neden olduğunu da kanıtlamaz. Durumuna uyuyorsa kişisel ayrıntılarını kendine sakla. Kayıtlarına bak: ne yapmayı planlamıştın, gerçekte ne yaptığını yazdın? İkisini karşılaştır. Kayıt yoksa ne olduğu bilinmiyor. Tamamladığın hazırlık, yanıtsız istek veya bıraktığın deneme kendi adıyla kalsın. Böylece sonraki seçimin incelenebilir olur. Olumlu bir hikâye yazman veya olmayan ilerlemeyi varmış gibi göstermen gerekmez."]},{heading:"Geçmişi değiştirmeden gelecek haftayı seç",paragraphs:["Kısa bir kişisel kayıt, tekrar eden bir durum düşündürebilir. Ama dışarıdan gelen sonucun nedenini kanıtlayamaz. Başvurular, siparişler ve başkasının yanıtı kaliteye, zamana, kaynaklara veya kaydının ölçmediği koşullara bağlı olabilir. Takip araştırması bilgiyi kullanmayı destekler. Hedefini değiştirmeden önce herkesin belli sayıda deneme yapması gerektiğini göstermez. [M03] Değerlendirirken bu belirsizliği görünür tut. Tek kişinin kaydı, o sonuca neyin neden olduğunu açıklayan bir deney değil.","Gelecek hafta için yapılabilir tek bir fırsat ve değerlendirme zamanı seç. Kullanabildiğin en küçük adımı ve işe erişmeni kolaylaştıran koşulları koru. Kayıtlarında sorun gördüğün kısmı değiştir. Deneme kaydı yoksa bildiğin gerçekleri yaz veya sonraki küçük işi ilk denemen say. Olmayan bir emek geçmişi uydurma. Planlama çalışmaları farklı sonuçlarla birlikte ortalama yararlar gösteriyor, garanti değil. [M01] Ara vermek, yorum istemek, somut destek bulmak veya yön değiştirmek değerlendirmenin bilinçli sonucu olabilir. Önceki kaydı koru. Böylece bu seçimin nedenini daha sonra da görebilirsin."]}],example:{title:"Emre gelecek haftayı seçiyor",text:"Emre tarihli üç düzeltmeyi ve kaçırdığı bir bilgisayar fırsatını okuyor. Öz geçmişi daha açık. Ama başvuru göndermemiş. Uygun bir ilan seçiyor, koşullarını kontrol ediyor ve hazırladığı sürümü cuma günü gönderiyor. Gönderdiğini kaydedip gelecek hafta değerlendirmek için zaman ayırıyor. Henüz yanıt yok. Kaydı başvuruyu anlatıyor, işverenin ilgisini varsaymıyor."}},...n.map(l)],lang:"tr"};export{s as COURSE,m as SOURCES};
